def merge_intervals(
    intervals: list[tuple[int, int, str]],
) -> list[tuple[int, int, list[str]]]:
    if any(start >= end for start, end, _ in intervals):
        raise ValueError("Each interval must have start < end.")

    if not intervals:
        return []

    ordered = iter(sorted(intervals, key=lambda item: item[0]))
    start, end, label = next(ordered)
    labels = {label}
    merged: list[tuple[int, int, list[str]]] = []

    for next_start, next_end, next_label in ordered:
        if next_start <= end:
            end = max(end, next_end)
            labels.add(next_label)
        else:
            merged.append((start, end, sorted(labels)))
            start, end = next_start, next_end
            labels = {next_label}

    merged.append((start, end, sorted(labels)))
    return merged
