import re

def parse_duration(s: str) -> float:
    # Check for empty string
    if not s:
        raise ValueError("Empty string")

    # Check for leading 'P'
    if not s.startswith('P'):
        raise ValueError("Missing leading 'P'")

    # Split into date and time parts
    parts = s[1:].split('T', 1)
    if len(parts) == 2:
        date_part, time_part = parts
        if not time_part:
            raise ValueError("'T' with nothing after it")
    else:
        date_part = parts[0]
        time_part = ''

    # Check for no components at all
    if not date_part and not time_part:
        raise ValueError("No components after 'P'")

    # Process date part
    date_components = []
    if date_part:
        # Check for invalid characters
        if not re.fullmatch(r'(\d+[YMWD])+', date_part):
            raise ValueError("Invalid date part")

        # Split into components
        date_components = re.findall(r'(\d+(?:[.,]\d+)?)(Y|M|W|D)', date_part)
        if not date_components:
            raise ValueError("Invalid date components")

        # Check order and uniqueness
        expected_order = ['Y', 'M', 'W', 'D']
        seen = set()
        for num, unit in date_components:
            if unit in seen:
                raise ValueError(f"Repeated unit '{unit}'")
            seen.add(unit)
            if expected_order.index(unit) != len(seen) - 1:
                raise ValueError("Components out of order")

        # Check fractional part only on last component
        for i, (num, unit) in enumerate(date_components):
            if i < len(date_components) - 1 and (',' in num or '.' in num):
                raise ValueError("Fractional part on non-last component")

    # Process time part
    time_components = []
    if time_part:
        # Check for invalid characters
        if not re.fullmatch(r'(\d+[HMS])+', time_part.replace(',', '.').replace('.', '', 1)):
            raise ValueError("Invalid time part")

        # Split into components
        time_components = re.findall(r'(\d+(?:[.,]\d+)?)(H|M|S)', time_part)
        if not time_components:
            raise ValueError("Invalid time components")

        # Check order and uniqueness
        expected_order = ['H', 'M', 'S']
        seen = set()
        for num, unit in time_components:
            if unit in seen:
                raise ValueError(f"Repeated unit '{unit}'")
            seen.add(unit)
            if expected_order.index(unit) != len(seen) - 1:
                raise ValueError("Components out of order")

        # Check fractional part only on last component
        for i, (num, unit) in enumerate(time_components):
            if i < len(time_components) - 1 and (',' in num or '.' in num):
                raise ValueError("Fractional part on non-last component")

    # Combine all components
    all_components = date_components + time_components

    # Check for at least one component
    if not all_components:
        raise ValueError("No components present")

    # Calculate total seconds
    total = 0.0
    for num, unit in all_components:
        # Convert number to float (handling both . and , as decimal separators)
        num_float = float(num.replace(',', '.'))
        if unit == 'Y':
            total += num_float * 365 * 86400
        elif unit == 'M' and (not time_part or unit not in [u for _, u in time_components]):
            total += num_float * 30 * 86400
        elif unit == 'W':
            total += num_float * 7 * 86400
        elif unit == 'D':
            total += num_float * 86400
        elif unit == 'H':
            total += num_float * 3600
        elif unit == 'M' and time_part and unit in [u for _, u in time_components]:
            total += num_float * 60
        elif unit == 'S':
            total += num_float

    return total
