import re


_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?"
    r"(?:\+([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?"
)
_COMPARATOR_RE = re.compile(r"(>=|<=|=|>|<|\^|~)?(.+)")


def _numeric_key(digits: str) -> tuple[int, str]:
    normalized = digits.lstrip("0") or "0"
    return len(normalized), normalized


def _version_key(core: tuple[str, str, str], prerelease: str | None):
    identifiers = []
    if prerelease is not None:
        for identifier in prerelease.split("."):
            if identifier.isascii() and identifier.isdigit():
                identifiers.append((0, *_numeric_key(identifier)))
            else:
                identifiers.append((1, identifier))

    return (
        *(_numeric_key(part) for part in core),
        prerelease is None,
        tuple(identifiers),
    )


def _parse_version(text: str):
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"Malformed version: {text!r}")
    core = (match[1], match[2], match[3])
    return core, _version_key(core, match[4])


def _increment(digits: str) -> str:
    # String arithmetic also supports integers beyond Python's int-string limit.
    chars = list(digits)
    index = len(chars) - 1
    while index >= 0 and chars[index] == "9":
        chars[index] = "0"
        index -= 1
    if index < 0:
        return "1" + "".join(chars)
    chars[index] = chr(ord(chars[index]) + 1)
    return "".join(chars)


def satisfies(version: str, range_expr: str) -> bool:
    if not isinstance(version, str) or not isinstance(range_expr, str):
        raise ValueError("Version and range must be strings")

    _, candidate = _parse_version(version)
    comparator_sets = []

    # Parse the entire range before evaluating, so malformed alternatives
    # raise even when another alternative would already match.
    for set_text in range_expr.split("||"):
        tokens = set_text.split()
        if not tokens:
            raise ValueError("Range contains an empty comparator set")

        comparisons = []
        for token in tokens:
            if token == "*":
                continue

            match = _COMPARATOR_RE.fullmatch(token)
            if match is None:
                raise ValueError(f"Malformed comparator: {token!r}")

            operator = match[1] or "="
            core, target = _parse_version(match[2])

            if operator in ("^", "~"):
                major, minor, patch = core
                if operator == "~":
                    upper_core = (major, _increment(minor), "0")
                elif major != "0":
                    upper_core = (_increment(major), "0", "0")
                elif minor != "0":
                    upper_core = ("0", _increment(minor), "0")
                else:
                    upper_core = ("0", "0", _increment(patch))

                comparisons.append((">=", target))
                comparisons.append(("<", _version_key(upper_core, None)))
            else:
                comparisons.append((operator, target))

        comparator_sets.append(comparisons)

    def matches(operator, target):
        if operator == "=":
            return candidate == target
        if operator == ">":
            return candidate > target
        if operator == ">=":
            return candidate >= target
        if operator == "<":
            return candidate < target
        return candidate <= target

    return any(
        all(matches(operator, target) for operator, target in comparisons)
        for comparisons in comparator_sets
    )
