                raise ValueError("Empty item in field")

            # Handle step patterns
            step_match = re.fullmatch(r'^(?:\*|(\d+)-(\d+))(/(\d+))?$', item)
            if step_match:
                start, end, _, step = step_match.groups()
                if step is not None:
                    try:
                        step = int(step)
                    except ValueError:
                        raise ValueError("Invalid step value")
                    if step < 1:
                        raise ValueError("Step must be >= 1")
                else:
                    step = 1

