                        start = int(start)
                        end = int(end)
                    except ValueError:
                        raise ValueError("Invalid range values")
                    if start > end:
                        raise ValueError("Descending range")
                    if start < min_val or end > max_val:
                        raise ValueError("Value out of range")
                    result.append((start, end, step))
