import re
from typing import List, Tuple, Optional

def satisfies(version: str, range_expr: str) -> bool:
    if not range_expr.strip():
        raise ValueError("empty range expression")

    # Parse the version
    v = _parse_version(version)

    # Split into comparator sets
    sets = [s.strip() for s in range_expr.split('||')]
    if not sets:
        raise ValueError("empty range expression")
    for s in sets:
        if not s:
            raise ValueError("empty comparator set")

    # Check if any set is satisfied
    for set_expr in sets:
        comparators = []
        for comp in re.split(r'\s+', set_expr.strip()):
            if not comp:
                continue
            comparators.append(_parse_comparator(comp))
        if not comparators:
            raise ValueError("empty comparator set")
        if all(_compare(v, op, _parse_version(ver)) for op, ver in comparators):
            return True
    return False

def _parse_version(version: str) -> Tuple[int, int, int, Optional[List[str]], Optional[List[str]]]:
    # Regex for semantic version
    pattern = r'^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
    match = re.fullmatch(pattern, version)
    if not match:
        raise ValueError(f"malformed version: {version}")

    major = int(match.group(1))
    minor = int(match.group(2))
    patch = int(match.group(3))
    prerelease = match.group(4).split('.') if match.group(4) else None
    build = match.group(5).split('.') if match.group(5) else None

    # Validate no leading zeros
    if (len(match.group(1)) > 1 and match.group(1)[0] == '0') or \
       (len(match.group(2)) > 1 and match.group(2)[0] == '0') or \
       (len(match.group(3)) > 1 and match.group(3)[0] == '0'):
        raise ValueError(f"malformed version: {version}")

    return (major, minor, patch, prerelease, build)

def _parse_comparator(comp: str) -> Tuple[str, str]:
    if comp == '*':
        return ('>=', '0.0.0')

    # Regex for comparator
    pattern = r'^([=<>~^]*)(.+)$'
    match = re.fullmatch(pattern, comp)
    if not match:
        raise ValueError(f"malformed comparator: {comp}")

    op = match.group(1)
    ver = match.group(2)

    if not op:
        op = '='

    if op not in {'=', '>', '>=', '<', '<=', '^', '~'}:
        raise ValueError(f"unknown operator: {op}")

    if op in {'^', '~'}:
        # Expand ^ and ~ operators
        v = _parse_version(ver)
        major, minor, patch, _, _ = v
        if op == '^':
            if major > 0:
                upper = f"{major + 1}.0.0"
            elif minor > 0:
                upper = f"0.{minor + 1}.0"
            else:
                upper = f"0.0.{patch + 1}"
            return ('>=', ver), ('<', upper)
        elif op == '~':
            upper = f"{major}.{minor + 1}.0"
