import re


_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?"
    r"(?:\+([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?"
)
_COMPARATOR_RE = re.compile(r"(>=|<=|[=<>^~])?(.+)")


def _precedence_key(core, prerelease=None):
    # Length/string pairs compare arbitrary-size integers without int().
    core_key = tuple((len(part), part) for part in core)
    prerelease_key = []

    if prerelease is not None:
        for identifier in prerelease.split("."):
            if identifier.isdigit():
                number = identifier.lstrip("0") or "0"
                prerelease_key.append((0, len(number), number))
            else:
                prerelease_key.append((1, 0, identifier))

    return core_key, prerelease is None, tuple(prerelease_key)


def _parse_version(text: str):
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"Malformed version: {text!r}")

    core = match.group(1, 2, 3)
    return core, _precedence_key(core, match.group(4))


def _increment_decimal(number: str) -> str:
    digits = list(number)
    for index in range(len(digits) - 1, -1, -1):
        if digits[index] != "9":
            digits[index] = chr(ord(digits[index]) + 1)
            return "".join(digits)
        digits[index] = "0"
    return "1" + "".join(digits)


def satisfies(version: str, range_expr: str) -> bool:
    _, candidate = _parse_version(version)
    range_matches = False

    for comparator_set in range_expr.split("||"):
        comparators = comparator_set.split()
        if not comparators:
            raise ValueError("Range contains an empty comparator set")

        set_matches = True

        for comparator in comparators:
            if comparator == "*":
                continue

            match = _COMPARATOR_RE.fullmatch(comparator)
            if match is None:
                raise ValueError(f"Malformed comparator: {comparator!r}")

            operator = match.group(1) or "="
            core, target = _parse_version(match.group(2))

            if operator in ("^", "~"):
                major, minor, patch = core

                if operator == "~":
                    upper_core = (major, _increment_decimal(minor), "0")
                elif major != "0":
                    upper_core = (_increment_decimal(major), "0", "0")
                elif minor != "0":
                    upper_core = ("0", _increment_decimal(minor), "0")
                else:
                    upper_core = ("0", "0", _increment_decimal(patch))

                upper = _precedence_key(upper_core)
                matches = target <= candidate < upper
            elif operator == "=":
                matches = candidate == target
            elif operator == ">":
                matches = candidate > target
            elif operator == ">=":
                matches = candidate >= target
            elif operator == "<":
                matches = candidate < target
            else:  # <=
                matches = candidate <= target

            set_matches = set_matches and matches

        # Do not return early: every comparator must be validated.
        range_matches = range_matches or set_matches

    return range_matches
