def merge_intervals(intervals: list[tuple[int, int, str]]) -> list[tuple[int, int, list[str]]]:
    """Merge overlapping or touching half-open intervals and collect sorted labels."""
    prepared: list[tuple[int, int, str]] = []
    for start, end, label in intervals:
        if start >= end:
            raise ValueError("start must be less than end")
        prepared.append((start, end, label))

    prepared.sort(key=lambda item: (item[0], item[1]))

    merged = []  # each item: [start, end, set_of_labels]
    for start, end, label in prepared:
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
            merged[-1][2].add(label)
        else:
            merged.append([start, end, {label}])

    return [(start, end, sorted(labels)) for start, end, labels in merged]
