def resolve_pointer(doc, pointer: str):
    if pointer == "":
        return doc

    if not pointer.startswith("/"):
        raise ValueError("pointer must start with '/'")

    current = doc

    # Split on '/', dropping the empty piece before the leading '/'
    tokens = pointer.split("/")[1:]

    for token in tokens:
        # Decode ~1 before ~0
        decoded = []
        i = 0
        while i < len(token):
            ch = token[i]
            if ch == "~":
                if i + 1 >= len(token):
                    raise ValueError("invalid escape: '~' at end of token")
                nxt = token[i + 1]
                if nxt == "1":
                    decoded.append("/")
                    i += 2
                elif nxt == "0":
                    decoded.append("~")
                    i += 2
                else:
                    raise ValueError("invalid escape: '~' followed by %r" % nxt)
            else:
                decoded.append(ch)
                i += 1
        key = "".join(decoded)

        if isinstance(current, dict):
            if key not in current:
                raise KeyError(key)
            current = current[key]
        elif isinstance(current, list):
            if key == "-":
                raise KeyError(key)
            # Must be ASCII digits, no leading zeros unless the token is exactly "0"
            if not key.isascii() or not key.isdigit():
                raise ValueError("invalid array index: %r" % key)
            if len(key) > 1 and key[0] == "0":
                raise ValueError("invalid array index: %r" % key)
            idx = int(key)
            if idx >= len(current):
                raise KeyError(key)
            current = current[idx]
        else:
            raise KeyError(key)

    return current
