import re
from datetime import date, timedelta

def _parse_date(s: str) -> date:
    if not isinstance(s, str):
        raise ValueError(f"Invalid date: {s!r}")
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", s):
        raise ValueError(f"Invalid date format: {s!r}")
    try:
        return date.fromisoformat(s)
    except ValueError:
        raise ValueError(f"Invalid date: {s!r}")

def add_business_days(start: str, days: int, holidays: list[str]) -> str:
    start_date = _parse_date(start)
    holiday_set = {_parse_date(h) for h in holidays}

    def is_business_day(d: date) -> bool:
        return d.weekday() < 5 and d not in holiday_set

    if days == 0:
        if is_business_day(start_date):
            return start_date.isoformat()
        d = start_date + timedelta(days=1)
        while not is_business_day(d):
            d += timedelta(days=1)
        return d.isoformat()

    step = 1 if days > 0 else -1
    remaining = abs(days)
    d = start_date

    while remaining > 0:
        d += timedelta(days=step)
        if is_business_day(d):
            remaining -= 1

    return d.isoformat()
