import re

def resolve_pointer(doc, pointer: str):
    if not pointer:
        return doc

    if not pointer.startswith('/'):
        raise ValueError("Pointer must start with '/'")

    tokens = pointer.split('/')[1:]  # Skip the initial empty string from leading '/'

    current = doc
    for token in tokens:
        # Decode ~0 and ~1
        decoded_token = []
        i = 0
        n = len(token)
        while i < n:
            if token[i] == '~':
                if i + 1 >= n:
                    raise ValueError("Invalid escape sequence in pointer")
                if token[i+1] == '0':
                    decoded_token.append('~')
                    i += 2
                elif token[i+1] == '1':
                    decoded_token.append('/')
                    i += 2
                else:
                    raise ValueError("Invalid escape sequence in pointer")
            else:
                decoded_token.append(token[i])
                i += 1
        decoded_token = ''.join(decoded_token)

        # Handle dict or list
        if isinstance(current, dict):
            if decoded_token not in current:
                raise KeyError(f"Key not found: {decoded_token}")
            current = current[decoded_token]
        elif isinstance(current, list):
            if decoded_token == '-':
                raise KeyError("Index '-' refers to non-existent element after last")
            if not re.fullmatch(r'0|[1-9][0-9]*', decoded_token):
                raise ValueError(f"Invalid list index: {decoded_token}")
            index = int(decoded_token)
            if index >= len(current):
                raise KeyError(f"Index out of range: {index}")
            current = current[index]
        else:
            raise KeyError("Cannot apply token to non-dict and non-list")

    return current
