def token_bucket(capacity: int, refill_per_sec: float, requests: list[tuple[float, int]]) -> list[bool]:
    if capacity < 1:
        raise ValueError("capacity must be >= 1")
    if refill_per_sec < 0:
        raise ValueError("refill_per_sec must be >= 0")

    tokens = float(capacity)
    last_time: float | None = None
    result: list[bool] = []

    for timestamp, cost in requests:
        if not isinstance(cost, int) or isinstance(cost, bool) or cost < 1:
            raise ValueError("cost must be an integer >= 1")
        if last_time is not None and timestamp < last_time:
            raise ValueError("timestamps must be non-decreasing")

        if last_time is not None:
            elapsed = timestamp - last_time
            tokens = min(float(capacity), tokens + elapsed * refill_per_sec)

        last_time = timestamp

        if tokens >= cost:
            tokens -= cost
            result.append(True)
        else:
            result.append(False)

    return result
