import ipaddress

def cidr_subtract(base: str, remove: list[str]) -> list[str]:
    try:
        base_net = ipaddress.IPv4Network(base, strict=True)
    except ValueError as e:
        raise ValueError(f"Invalid base CIDR block: {e}")

    remove_nets = []
    for cidr in remove:
        try:
            net = ipaddress.IPv4Network(cidr, strict=True)
        except ValueError as e:
            raise ValueError(f"Invalid remove CIDR block '{cidr}': {e}")
        remove_nets.append(net)

    # Start with the base network
    remaining = [base_net]

    for net in remove_nets:
        new_remaining = []
        for current in remaining:
            # If the current network is completely outside the remove network, keep it
            if current.is_disjoint(net):
                new_remaining.append(current)
            else:
                # Otherwise, subtract the remove network from the current network
                new_remaining.extend(current.address_exclude(net))
        remaining = new_remaining
        if not remaining:
            return []

    # Convert to strings and sort by network address
    result = [str(net) for net in sorted(remaining, key=lambda n: (n.network_address, n.prefixlen))]
    return result
