def token_bucket(capacity: int, refill_per_sec: float, requests: list[tuple[float, int]]) -> list[bool]:
    if capacity < 1:
        raise ValueError("Capacity must be at least 1")
    if refill_per_sec < 0:
        raise ValueError("Refill rate must be non-negative")

    if not requests:
        return []

    # Validate requests
    prev_timestamp = requests[0][0]
    for timestamp, cost in requests:
        if timestamp < prev_timestamp:
            raise ValueError("Timestamps must be non-decreasing")
        if not isinstance(cost, int) or cost < 1:
            raise ValueError("Cost must be an integer >= 1")
        prev_timestamp = timestamp

    tokens = float(capacity)
    last_refill_time = requests[0][0]
    results = []

    for timestamp, cost in requests:
        # Calculate tokens added since last refill
        time_elapsed = timestamp - last_refill_time
        tokens_added = time_elapsed * refill_per_sec
        tokens = min(tokens + tokens_added, capacity)
        last_refill_time = timestamp

        # Check if request can be allowed
        if tokens >= cost:
            tokens -= cost
            results.append(True)
        else:
            results.append(False)

    return results
