import re


def resolve_pointer(doc, pointer: str):
    if pointer == "":
        return doc
    if not pointer.startswith("/"):
        raise ValueError("A non-empty JSON Pointer must start with '/'")

    tokens = []
    for raw_token in pointer.split("/")[1:]:
        if re.search(r"~(?:[^01]|$)", raw_token):
            raise ValueError(f"Invalid escape in token: {raw_token!r}")
        tokens.append(raw_token.replace("~1", "/").replace("~0", "~"))

    current = doc
    for token in tokens:
        if isinstance(current, dict):
            current = current[token]
        elif isinstance(current, list):
            if token == "-":
                raise KeyError(token)
            if re.fullmatch(r"(?:0|[1-9][0-9]*)", token) is None:
                raise ValueError(f"Invalid list index: {token!r}")

            # Compare before converting, avoiding limits on huge integer strings.
            bound = str(len(current))
            if len(token) > len(bound) or (
                len(token) == len(bound) and token >= bound
            ):
                raise KeyError(token)
            current = current[int(token)]
        else:
            raise KeyError(token)

    return current
