def glob_match(pattern: str, name: str) -> bool:
    # Parse pattern into tokens for easier processing
    # Token types: 'char', 'any' (?), 'star' (*), 'doublestar' (**), 'class' (set)

    tokens = []
    i = 0
    n = len(pattern)

    while i < n:
        c = pattern[i]
        if c == '\\':
            # Escape: next char is literal, or trailing backslash is literal backslash
            if i + 1 < n:
                tokens.append(('char', pattern[i + 1]))
                i += 2
            else:
                tokens.append(('char', '\\'))
                i += 1
        elif c == '?':
            tokens.append(('any', None))
            i += 1
        elif c == '*':
            if i + 1 < n and pattern[i + 1] == '*':
                tokens.append(('doublestar', None))
                i += 2
            else:
                tokens.append(('star', None))
                i += 1
        elif c == '[':
            # Try to parse a character class
            j = i + 1
            negated = False
            if j < n and pattern[j] in '!^':
                negated = True
                j += 1
            # Check for literal ] as first char
            members = []  # list of (start, end) ranges or single chars
            first = True
            closed = False
            while j < n:
                if pattern[j] == ']' and not first:
                    closed = True
                    j += 1
                    break
                first = False
                # Parse one member (could be range)
                if j + 2 < n and pattern[j + 1] == '-' and pattern[j + 2] != ']':
                    # Range
                    start = pattern[j]
                    end = pattern[j + 2]
                    members.append((start, end))
                    j += 3
                else:
                    # Single char
                    members.append((pattern[j], pattern[j]))
                    j += 1
            if closed:
                tokens.append(('class', (negated, members)))
                i = j
            else:
                # No closing ], literal [
                tokens.append(('char', '['))
                i += 1
        else:
            tokens.append(('char', c))
            i += 1

    # DP matching: dp[i][j] = does tokens[i:] match name[j:]?
