from fractions import Fraction


def evaluate(expr: str) -> Fraction:
    tokens: list[int | str] = []
    i = 0

    while i < len(expr):
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif "0" <= ch <= "9":
            value = 0
            while i < len(expr) and "0" <= expr[i] <= "9":
                value = value * 10 + ord(expr[i]) - ord("0")
                i += 1
            tokens.append(value)
        elif expr.startswith("**", i):
            tokens.append("**")
            i += 2
        elif ch in "+-*/()":
            tokens.append(ch)
            i += 1
        else:
            raise ValueError(f"Unknown character at position {i}: {ch!r}")

    pos = 0

    def peek() -> int | str | None:
        return tokens[pos] if pos < len(tokens) else None

    def atom() -> Fraction:
        nonlocal pos
        token = peek()
        if isinstance(token, int):
            pos += 1
            return Fraction(token)
        if token == "(":
            pos += 1
            value = expression()
            if peek() != ")":
                raise ValueError("Expected closing parenthesis")
            pos += 1
            return value
        raise ValueError("Expected an integer or opening parenthesis")

    def power() -> Fraction:
        nonlocal pos
        base = atom()
        if peek() == "**":
            pos += 1
            exponent = unary()
            if exponent.denominator != 1:
                raise ValueError("Exponent must be an integer")
            return base ** exponent.numerator
        return base

    def unary() -> Fraction:
        nonlocal pos
        negative = False
        while peek() in ("+", "-"):
            if peek() == "-":
                negative = not negative
            pos += 1
        value = power()
        return -value if negative else value

    def term() -> Fraction:
        nonlocal pos
        value = unary()
        while peek() in ("*", "/"):
            operator = peek()
            pos += 1
            right = unary()
            value = value * right if operator == "*" else value / right
        return value

    def expression() -> Fraction:
        nonlocal pos
        value = term()
        while peek() in ("+", "-"):
            operator = peek()
            pos += 1
            right = term()
            value = value + right if operator == "+" else value - right
        return value

    result = expression()
    if pos != len(tokens):
        raise ValueError("Unexpected token")
    return result
