import ipaddress
import re


_CIDR_PATTERN = re.compile(
    r"(?:0|[1-9][0-9]{0,2})"
    r"(?:\.(?:0|[1-9][0-9]{0,2})){3}/[0-9]+"
)


def cidr_subtract(base: str, remove: list[str]) -> list[str]:
    def parse(block: str) -> ipaddress.IPv4Network:
        if not isinstance(block, str) or _CIDR_PATTERN.fullmatch(block) is None:
            raise ValueError(f"Malformed IPv4 CIDR block: {block!r}")

        address, prefix = block.split("/")
        # Normalize leading zeros in the prefix without converting an
        # arbitrarily long decimal string to an integer.
        prefix = prefix.lstrip("0") or "0"
        if len(prefix) > 2 or int(prefix) > 32:
            raise ValueError(f"Invalid prefix length: {block!r}")

        return ipaddress.IPv4Network(f"{address}/{prefix}", strict=True)

    network = parse(base)
    start = int(network.network_address)
    end = int(network.broadcast_address)

    intervals = []
    for block in remove:
        other = parse(block)  # Validate every entry, even if nothing remains.
        left = max(start, int(other.network_address))
        right = min(end, int(other.broadcast_address))
        if left <= right:
            intervals.append((left, right))

    intervals.sort()
    result = []

    def append_range(left: int, right: int) -> None:
        result.extend(
            str(block)
            for block in ipaddress.summarize_address_range(
                ipaddress.IPv4Address(left),
                ipaddress.IPv4Address(right),
            )
        )

    cursor = start
    for left, right in intervals:
        if right < cursor:
            continue
        if left > cursor:
            append_range(cursor, left - 1)
        cursor = right + 1
        if cursor > end:
            break

    if cursor <= end:
        append_range(cursor, end)

    return result
