def evaluate(expr: str) -> Fraction:
    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif c in '+-*/()':
            if c == '*':
                if i + 1 < n and expr[i+1] == '*':
                    tokens.append(('OP', '**'))
                    i += 2
                else:
                    tokens.append(('OP', '*'))
                    i += 1
            else:
                tokens.append(('OP', c))
                i += 1
        else:
            raise ValueError(f"Unknown character: {c!r}")

    if not tokens:
        raise ValueError("Empty expression")

    # Parser using recursive descent
    pos = [0]  # mutable position

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return None

    def consume():
        tok = tokens[pos[0]]
        pos[0] += 1
        return tok

    def expect_op(op):
        tok = peek()
        if tok is None or tok[0] != 'OP' or tok[1] != op:
            raise ValueError(f"Expected {op!r}")
        consume()

    # Grammar:
    # expr := term (('+' | '-') term)*
    # term := factor (('*' | '/') factor)*
    # factor := ('+' | '-') factor | power
    # power := primary ('**' factor)?    # right-associative, right side can have unary
    # primary := NUM | '(' expr ')'

    def parse_expr():
        result = parse_term()
        while True:
            tok = peek()
            if tok is not None and tok[0] == 'OP' and tok[1] in ('+', '-'):
                op = consume()[1]
                right = parse_term()
                if op == '+':
                    result = result + right
                else:
                    result = result - right
            else:
                break
        return result

    def parse_term():
        result = parse_factor()
        while True:
            tok = peek()
            if tok is not None and tok[0] == 'OP' and tok[1] in ('*', '/'):
                op = consume()[1]
                right = parse_factor()
                if op == '*':
                    result = result * right
                else:
                    if right == 0:
                        raise ZeroDivisionError("Division by zero")
                    result = result / right
            else:
                break
        return result

    def parse_factor():
        tok = peek()
        if tok is not None and tok[0] == 'OP' and tok[1] in ('+', '-'):
            op = consume()[1]
            val = parse_factor()
            if op == '-':
                return -val
            return val
        return parse_power()

    def parse_power():
        base = parse_primary()
        tok = peek()
        if tok is not None and tok[0] == 'OP' and tok[1] == '**':
            consume()
            # Right side of ** can start with unary operators
            exponent = parse_factor()
            # Check for integer exponent
            if exponent.denominator != 1:
                raise ValueError("Non-integer exponent")
            exp_int = exponent.numerator
