            if base == 0 and exp_int < 0:
                raise ZeroDivisionError("0 cannot be raised to a negative power")
            # Use exact integer power
            if exp_int >= 0:
                result = Fraction(base.numerator ** exp_int, base.denominator ** exp_int)
            else:
                result = Fraction(base.denominator ** (-exp_int), base.numerator ** (-exp_int))
            return result
