```python
def resolve_pointer(doc, pointer: str):
    """Return the value referenced by an RFC 6901 JSON Pointer."""
    if pointer == "":
        return doc
    if not pointer.startswith("/"):
        raise ValueError("A nonempty JSON Pointer must start with '/'")

    current = doc
    for raw_token in pointer.split("/")[1:]:
        for i, char in enumerate(raw_token):
            if char == "~" and (
                i + 1 == len(raw_token) or raw_token[i + 1] not in "01"
            ):
                raise ValueError(f"Invalid escape in token: {raw_token!r}")

        token = raw_token.replace("~1", "/").replace("~0", "~")

        if isinstance(current, dict):
            current = current[token]
        elif isinstance(current, list):
            if token == "-":
                raise KeyError(token)

            if (
                not token
                or (len(token) > 1 and token[0] == "0")
                or any(char < "0" or char > "9" for char in token)
            ):
                raise ValueError(f"Invalid array index: {token!r}")

            # Compare before converting, so arbitrarily long valid indices
            # raise KeyError rather than hitting Python's integer-string limit.
            length = str(len(current))
            if len(token) > len(length) or (
                len(token) == len(length) and token >= length
            ):
                raise KeyError(token)

            current = current[int(token)]
        else:
            raise KeyError(token)

    return current
