def glob_match(pattern: str, name: str) -> bool:
    """Match an entire name against a case-sensitive glob pattern."""
    tokens = []
    i = 0

    while i < len(pattern):
        ch = pattern[i]

        if ch == "\\":
            if i + 1 < len(pattern):
                tokens.append(("literal", pattern[i + 1]))
                i += 2
            else:
                tokens.append(("literal", "\\"))
                i += 1

        elif ch == "*":
            if i + 1 < len(pattern) and pattern[i + 1] == "*":
                tokens.append(("globstar", None))
                i += 2
            else:
                tokens.append(("star", None))
                i += 1

        elif ch == "?":
            tokens.append(("any", None))
            i += 1

        elif ch == "[":
            start = i + 1
            negated = (
                start < len(pattern) and pattern[start] in "!^"
            )
            if negated:
                start += 1

            # An initial ']' is a member, not the closing delimiter.
            search_from = start
            if search_from < len(pattern) and pattern[search_from] == "]":
                search_from += 1
            end = pattern.find("]", search_from)

            if end == -1:
                tokens.append(("literal", "["))
                i += 1
                continue

            members = pattern[start:end]
            singles = set()
            ranges = []
            k = 0

            while k < len(members):
                # Boundary hyphens are always literal.
                if members[k] == "-" and k in (0, len(members) - 1):
                    singles.add("-")
                    k += 1
                elif (
                    k + 2 < len(members)
                    and members[k + 1] == "-"
                    and not (
                        k + 2 == len(members) - 1
                        and members[k + 2] == "-"
                    )
                ):
                    low, high = ord(members[k]), ord(members[k + 2])
                    if low <= high:
                        ranges.append((low, high))
                    k += 3
                else:
                    singles.add(members[k])
                    k += 1

            tokens.append(("set", (negated, singles, ranges)))
            i = end + 1

        else:
            tokens.append(("literal", ch))
            i += 1

    # dp[j]: the tokens processed so far match name[:j].
    dp = [False] * (len(name) + 1)
    dp[0] = True

    for kind, value in tokens:
        current = [False] * (len(name) + 1)

        if kind in ("star", "globstar"):
            current[0] = dp[0]
            for j, ch in enumerate(name, 1):
                current[j] = dp[j] or (
                    current[j - 1] and (kind == "globstar" or ch != "/")
                )
        else:
            for j, ch in enumerate(name, 1):
                if not dp[j - 1]:
                    continue

                if kind == "literal":
                    matches = ch == value
                elif kind == "any":
                    matches = ch != "/"
                else:
                    negated, singles, ranges = value
                    code = ord(ch)
                    contained = ch in singles or any(
                        low <= code <= high for low, high in ranges
                    )
                    matches = ch != "/" and (contained != negated)

                current[j] = matches

        dp = current

    return dp[-1]
```

```python
def osa_distance(a: str, b: str) -> int:
    """Return the optimal string alignment distance using linear space."""
    if a == b:
        return 0

    # Use the shorter string for the columns.
    if len(a) < len(b):
        a, b = b, a

    n = len(b)
    if n == 0:
        return len(a)

    previous = list(range(n + 1))
    previous_previous = previous

    for i, char_a in enumerate(a, start=1):
        current = [i] + [0] * n

        for j, char_b in enumerate(b, start=1):
            current[j] = min(
                previous[j] + 1,                      # Deletion
                current[j - 1] + 1,                   # Insertion
                previous[j - 1] + (char_a != char_b),  # Substitution
            )

            if (
                i > 1
                and j > 1
                and char_a == b[j - 2]
                and a[i - 2] == char_b
            ):
                current[j] = min(
                    current[j],
                    previous_previous[j - 2] + 1,
                )

        previous_previous, previous = previous, current

    return previous[n]
