import re
from ipaddress import IPv4Address, IPv4Network, summarize_address_range


def cidr_subtract(base: str, remove: list[str]) -> list[str]:
    def parse(block: str) -> IPv4Network:
        if not isinstance(block, str) or re.fullmatch(
            r"(?:[0-9]{1,3}\.){3}[0-9]{1,3}/[0-9]+", block
        ) is None:
            raise ValueError(f"Malformed IPv4 CIDR block: {block!r}")
        return IPv4Network(block, strict=True)

    base_network = parse(base)
    base_start = int(base_network.network_address)
    base_end = int(base_network.broadcast_address)

    # Validate every removal block, even if an earlier one covers all of base.
    intervals: list[tuple[int, int]] = []
    for block in remove:
        network = parse(block)
        start = max(base_start, int(network.network_address))
        end = min(base_end, int(network.broadcast_address))
        if start <= end:
            intervals.append((start, end))
    intervals.sort()

    result: list[str] = []

    def append_range(start: int, end: int) -> None:
        result.extend(
            str(network)
            for network in summarize_address_range(
                IPv4Address(start), IPv4Address(end)
            )
        )

    cursor = base_start
    for start, end in intervals:
        if start > cursor:
            append_range(cursor, start - 1)
        cursor = max(cursor, end + 1)
        if cursor > base_end:
            break

    if cursor <= base_end:
        append_range(cursor, base_end)

    return result
