def glob_match(pattern: str, name: str) -> bool:
    """Return whether the whole name matches the case-sensitive glob pattern."""
    tokens = []
    i = 0

    while i < len(pattern):
        ch = pattern[i]

        if ch == "\\":
            if i + 1 < len(pattern):
                tokens.append(("literal", pattern[i + 1]))
                i += 2
            else:
                tokens.append(("literal", "\\"))
                i += 1

        elif ch == "*":
            end = i + 1
            while end < len(pattern) and pattern[end] == "*":
                end += 1
            # Any uninterrupted run of at least two stars is equivalent to **.
            tokens.append(("globstar" if end - i >= 2 else "star", None))
            i = end

        elif ch == "?":
            tokens.append(("question", None))
            i += 1

        elif ch == "[":
            start = i + 1
            negated = start < len(pattern) and pattern[start] in "!^"
            if negated:
                start += 1

            # A leading ] belongs to the set, so cannot close it.
            search_from = start
            if search_from < len(pattern) and pattern[search_from] == "]":
                search_from += 1
            end = pattern.find("]", search_from)

            if end == -1:
                tokens.append(("literal", "["))
                i += 1
                continue

            members = pattern[start:end]
            intervals = []
            k = 0
            while k < len(members):
                if k + 2 < len(members) and members[k + 1] == "-":
                    low, high = members[k], members[k + 2]
                    if low <= high:
                        intervals.append((low, high))
                    k += 3
                else:
                    intervals.append((members[k], members[k]))
                    k += 1

            tokens.append(("set", (negated, intervals)))
            i = end + 1

        else:
            tokens.append(("literal", ch))
            i += 1

    # previous[j] means the processed tokens match name[:j].
    previous = [False] * (len(name) + 1)
    previous[0] = True

    for kind, value in tokens:
        current = [False] * (len(name) + 1)

        if kind in ("star", "globstar"):
            current[0] = previous[0]
            crosses_slashes = kind == "globstar"
            for j, ch in enumerate(name, 1):
                current[j] = previous[j] or (
                    current[j - 1] and (crosses_slashes or ch != "/")
                )

        elif kind == "literal":
            for j, ch in enumerate(name, 1):
                current[j] = previous[j - 1] and ch == value

        elif kind == "question":
            for j, ch in enumerate(name, 1):
                current[j] = previous[j - 1] and ch != "/"

        else:
            negated, intervals = value
            for j, ch in enumerate(name, 1):
                if previous[j - 1] and ch != "/":
                    contained = any(low <= ch <= high for low, high in intervals)
                    current[j] = contained != negated

        previous = current

    return previous[len(name)]
