```python
from fractions import Fraction


def evaluate(expr: str) -> Fraction:
    """Evaluate an arithmetic expression exactly, without executing Python code."""
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2,
                  "u+": 3, "u-": 3, "**": 4}
    output: list[int | str] = []
    operators: list[str] = []
    need_operand = True
    i = 0
    n = len(expr)

    # Validate the entire expression and produce postfix notation before
    # performing arithmetic, so syntax errors always raise ValueError.
    while i < n:
        ch = expr[i]

        if ch.isspace():
            i += 1
            continue

        if "0" <= ch <= "9":
            if not need_operand:
                raise ValueError("Two operands in a row")

            # Avoid Python's limit on decimal string-to-integer conversion.
            value = 0
            while i < n and "0" <= expr[i] <= "9":
                value = value * 10 + ord(expr[i]) - ord("0")
                i += 1
            output.append(value)
            need_operand = False
            continue

        if ch == "(":
            if not need_operand:
                raise ValueError("Missing operator before '('")
            operators.append("(")
            i += 1
            continue

        if ch == ")":
            if need_operand:
                raise ValueError("Missing operand before ')'")
            while operators and operators[-1] != "(":
                output.append(operators.pop())
            if not operators:
                raise ValueError("Unbalanced parentheses")
            operators.pop()
            i += 1
            continue

        if ch not in "+-*/":
            raise ValueError(f"Unknown character: {ch!r}")

        op = ch
        i += 1
        if op == "*" and i < n and expr[i] == "*":
            op = "**"
            i += 1

        if need_operand:
            if op not in ("+", "-"):
                raise ValueError("Missing operand")
            # Prefix operators never pop pending operators. In particular,
            # this permits a unary operator on the right side of '**'.
            operators.append("u" + op)
        else:
            while operators and operators[-1] != "(":
                top = operators[-1]
                if (precedence[top] > precedence[op]
                        or (precedence[top] == precedence[op] and op != "**")):
                    output.append(operators.pop())
                else:
                    break
            operators.append(op)
            need_operand = True

    if need_operand:
        raise ValueError("Empty expression or missing operand")

    while operators:
        op = operators.pop()
        if op == "(":
            raise ValueError("Unbalanced parentheses")
        output.append(op)

    values: list[Fraction] = []
    for token in output:
        if isinstance(token, int):
            values.append(Fraction(token))
        elif token == "u+":
            continue
        elif token == "u-":
            values[-1] = -values[-1]
        else:
            right = values.pop()
            left = values.pop()

            if token == "+":
                result = left + right
            elif token == "-":
                result = left - right
            elif token == "*":
                result = left * right
            elif token == "/":
                result = left / right
            else:  # **
                if right.denominator != 1:
                    raise ValueError("Exponent must be an integer")
                result = left ** right.numerator

            values.append(result)

    return values[0]
```

