def merge_intervals(
    intervals: list[tuple[int, int, str]],
) -> list[tuple[int, int, list[str]]]:
    for start, end, _ in intervals:
        if start >= end:
            raise ValueError("Each interval must have start < end")

    if not intervals:
        return []

    ordered = sorted(intervals, key=lambda interval: interval[0])
    start, end, label = ordered[0]
    labels = {label}
    result: list[tuple[int, int, list[str]]] = []

    for next_start, next_end, label in ordered[1:]:
        if next_start <= end:
            end = max(end, next_end)
            labels.add(label)
        else:
            result.append((start, end, sorted(labels)))
            start, end = next_start, next_end
            labels = {label}

    result.append((start, end, sorted(labels)))
    return result
