import re
from functools import total_ordering

_VERSION_RE = re.compile(
    r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
    r'(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)'
    r'(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?'
    r'(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'
)

@total_ordering
class SemVer:
    __slots__ = ('major', 'minor', 'patch', 'prerelease')

    def __init__(self, major: int, minor: int, patch: int, prerelease: tuple[str, ...] | None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease

    def _key(self):
        # A version without prerelease is greater than one with prerelease.
        # Represent prerelease as a tuple where None sorts higher than any tuple.
        if self.prerelease is None:
            pre_key = (1,)
        else:
            pre_key = (0,) + tuple(
                (0, int(p), '') if p.isdigit() else (1, 0, p)
                for p in self.prerelease
            )
        return (self.major, self.minor, self.patch, pre_key)

    def __eq__(self, other):
        if not isinstance(other, SemVer):
            return NotImplemented
        return self._key() == other._key()

    def __lt__(self, other):
        if not isinstance(other, SemVer):
            return NotImplemented
        return self._key() < other._key()

    def __hash__(self):
        return hash(self._key())

def _parse_version(s: str) -> SemVer:
    s = s.strip()
    m = _VERSION_RE.match(s)
    if not m:
        raise ValueError(f"malformed version: {s!r}")
    major = int(m.group(1))
    minor = int(m.group(2))
    patch = int(m.group(3))
    pre_str = m.group(4)
    prerelease = tuple(pre_str.split('.')) if pre_str is not None else None
    return SemVer(major, minor, patch, prerelease)

def _parse_comparator(comp: str) -> tuple[str, SemVer]:
    comp = comp.strip()
    if comp == '*':
        return ('*', None)
    for op in ('>=', '<=', '>', '<', '=', '^', '~'):
        if comp.startswith(op):
            ver_str = comp[len(op):]
            if not ver_str:
                raise ValueError(f"malformed comparator: {comp!r}")
            return (op, _parse_version(ver_str))
    # No operator means '='
    return ('=', _parse_version(comp))

def _expand_comparator(op: str, ver: SemVer) -> list[tuple[str, SemVer]]:
    if op == '^':
        if ver.major > 0:
            upper = SemVer(ver.major + 1, 0, 0, None)
        elif ver.minor > 0:
            upper = SemVer(0, ver.minor + 1, 0, None)
        else:
            upper = SemVer(0, 0, ver.patch + 1, None)
        return [('>=', ver), ('<', upper)]
    if op == '~':
        upper = SemVer(ver.major, ver.minor + 1, 0, None)
        return [('>=', ver), ('<', upper)]
    return [(op, ver)]

def _satisfies_comparator(version: SemVer, op: str, target: SemVer) -> bool:
    if op == '=':
        return version == target
    if op == '>':
        return version > target
    if op == '>=':
        return version >= target
    if op == '<':
        return version < target
    if op == '<=':
        return version <= target
    raise ValueError(f"unknown operator: {op!r}")

def satisfies(version: str, range_expr: str) -> bool:
    ver = _parse_version(version)
    if not isinstance(range_expr, str) or not range_expr.strip():
        raise ValueError("empty range")

    for comp_set_str in range_expr.split('||'):
        comp_set_str = comp_set_str.strip()
        if not comp_set_str:
            raise ValueError("empty comparator set")

        comparators = comp_set_str.split()
        if not comparators:
            raise ValueError("empty comparator set")

        ok = True
        for comp in comparators:
            op, target = _parse_comparator(comp)
            if op == '*':
                continue
            for expanded_op, expanded_target in _expand_comparator(op, target):
                if not _satisfies_comparator(ver, expanded_op, expanded_target):
                    ok

