import re
from datetime import datetime, timedelta

def next_run(expr: str, after: str) -> str:
    # Parse the after time
    try:
        after_dt = datetime.strptime(after, "%Y-%m-%d %H:%M")
    except ValueError:
        raise ValueError("Invalid 'after' format")

    # Parse and validate the cron expression
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Expression must have exactly 5 fields")

    minute_field, hour_field, dom_field, month_field, dow_field = fields

    # Field ranges: (min, max)
    ranges = [
        (0, 59),   # minute
        (0, 23),   # hour
        (1, 31),   # day of month
        (1, 12),   # month
        (0, 6),    # day of week (0=Sunday, 6=Saturday)
    ]

    def parse_field(field: str, min_val: int, max_val: int, field_name: str) -> set:
        """Parse a cron field into a set of allowed values."""
        if not field:
            raise ValueError(f"Empty field: {field_name}")

        allowed = set()

        for item in field.split(','):
            if not item:
                raise ValueError(f"Empty item in field: {field_name}")

            # Check for step
            step = 1
            if '/' in item:
                parts = item.split('/')
                if len(parts) != 2:
                    raise ValueError(f"Invalid step syntax: {item}")
                base, step_str = parts
                if not step_str.isdigit():
                    raise ValueError(f"Invalid step value: {step_str}")
                step = int(step_str)
                if step < 1:
                    raise ValueError(f"Step must be >= 1: {step}")
            else:
                base = item

            # Parse the base (either *, number, or range)
            if base == '*':
                start, end = min_val, max_val
            elif '-' in base:
                # Range
                range_parts = base.split('-')
                if len(range_parts) != 2:
                    raise ValueError(f"Invalid range: {base}")
                start_str, end_str = range_parts
                if not start_str.isdigit() or not end_str.isdigit():
                    raise ValueError(f"Invalid range values: {base}")
                start, end = int(start_str), int(end_str)
                if start > end:
                    raise ValueError(f"Descending range: {base}")
                if start < min_val or end > max_val:
                    raise ValueError(f"Range out of bounds: {base}")
            else:
                # Single number
                if not base.isdigit():
                    raise ValueError(f"Invalid number: {base}")
                start = int(base)
                if start < min_val or start > max_val:
                    raise ValueError(f"Value out of range: {base}")
                # Step on single number is invalid
                if '/' in item:
                    raise ValueError(f"Step on single number is invalid: {item}")
                end = start

            # Generate values
            if step == 1:
                allowed.update(range(start, end + 1))
            else:
                allowed.update(range(start, end + 1, step))

        # Validate all values are in range
        for v in allowed:
            if v < min_val or v > max_val:
                raise ValueError(f"Value out of range in {field_name}: {v}")

        return allowed

    try:
