import re
from bisect import bisect_right
from calendar import monthrange
from datetime import date, datetime


def next_run(expr: str, after: str) -> str:
    def parse_field(text: str, low: int, high: int) -> set[int]:
        values = set()
        for item in text.split(","):
            match = re.fullmatch(
                r"(\*|[0-9]+(?:-[0-9]+)?)(?:/([0-9]+))?", item
            )
            if match is None:
                raise ValueError(f"Invalid cron item: {item!r}")

            base, step_text = match.groups()
            step = int(step_text) if step_text is not None else 1
            if step < 1:
                raise ValueError("Step must be positive")

            if base == "*":
                start, stop = low, high
            elif "-" in base:
                start, stop = map(int, base.split("-"))
            else:
                if step_text is not None:
                    raise ValueError("Steps on single numbers are invalid")
                start = stop = int(base)

            if not low <= start <= stop <= high:
                raise ValueError(f"Invalid range in item: {item!r}")
            values.update(range(start, stop + 1, step))
        return values

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("A cron expression must have exactly five fields")

    minutes, hours, days, months, weekdays = [
        parse_field(text, low, high)
        for text, (low, high) in zip(
            fields, ((0, 59), (0, 23), (1, 31), (1, 12), (0, 6))
        )
    ]
    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"

    if re.fullmatch(
        r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}", after
    ) is None:
        raise ValueError("after must have format YYYY-MM-DD HH:MM")
    start = datetime.strptime(after, "%Y-%m-%d %H:%M")

    # Use a calendar-year horizon, clamping February 29 to February 28.
    if start.year + 5 <= 9999:
        end_year = start.year + 5
        end_day = min(start.day, monthrange(end_year, start.month)[1])
        end = start.replace(year=end_year, day=end_day)
    else:
        end = datetime(9999, 12, 31, 23, 59)

    times = sorted(hour * 60 + minute for hour in hours for minute in minutes)
    start_ordinal = start.date().toordinal()
    end_ordinal = end.date().toordinal()
    start_minute = start.hour * 60 + start.minute
    end_minute = end.hour * 60 + end.minute

    for ordinal in range(start_ordinal, end_ordinal + 1):
        day = date.fromordinal(ordinal)
        if day.month not in months:
            continue

        dom_matches = day.day in days
        dow_matches = (day.weekday() + 1) % 7 in weekdays

        if dom_restricted and dow_restricted:
            matches = dom_matches or dow_matches
        elif dom_restricted:
            matches = dom_matches
        elif dow_restricted:
            matches = dow_matches
        else:
            matches = True
        if not matches:
            continue

        index = bisect_right(times, start_minute) if ordinal == start_ordinal else 0
        if index == len(times):
            continue

        minute_of_day = times[index]
        if ordinal == end_ordinal and minute_of_day > end_minute:
            continue

        hour, minute = divmod(minute_of_day, 60)
        return (
            f"{day.year:04d}-{day.month:02d}-{day.day:02d} "
            f"{hour:02d}:{minute:02d}"
        )

    raise ValueError("No matching minute within five years after after")
