import re
from datetime import datetime, timedelta

def next_run(expr: str, after: str) -> str:
    # Parse the after time
    try:
        after_dt = datetime.strptime(after, "%Y-%m-%d %H:%M")
    except ValueError:
        raise ValueError("Invalid after time format")

    # Parse the cron expression
    parts = expr.split()
    if len(parts) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    minute_field, hour_field, dom_field, month_field, dow_field = parts

    # Validate and parse each field
    def parse_field(field: str, min_val: int, max_val: int, field_name: str) -> set[int]:
        if not field:
            raise ValueError(f"Empty {field_name} field")

        items = field.split(',')
        values = set()

        for item in items:
            if not item:
                raise ValueError(f"Empty item in {field_name} field")

