import re

_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?"
    r"(?:\+[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*)?"
)
_COMPARATOR_RE = re.compile(r"(>=|<=|=|>|<|\^|~)?(.+)")


def _number(text: str) -> int:
    # Avoid Python's string-to-integer digit limit for valid long identifiers.
    result = 0
    for char in text:
        result = result * 10 + ord(char) - ord("0")
    return result


def _parse_version(text: str) -> tuple:
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"Malformed version: {text!r}")

    major, minor, patch = map(_number, match.group(1, 2, 3))
    prerelease = match.group(4)
    if prerelease is None:
        return major, minor, patch, (1, ())

    identifiers = tuple(
        (0, _number(part)) if part.isascii() and part.isdigit() else (1, part)
        for part in prerelease.split(".")
    )
    return major, minor, patch, (0, identifiers)


def satisfies(version: str, range_expr: str) -> bool:
    candidate = _parse_version(version)
    comparator_sets = []

    # Validate the entire expression before evaluating any alternatives.
    for section in range_expr.split("||"):
        tokens = section.split()
        if not tokens:
            raise ValueError("Range contains an empty comparator set")

        comparators = []
        for token in tokens:
            if token == "*":
                continue

            match = _COMPARATOR_RE.fullmatch(token)
            if match is None:
                raise ValueError(f"Malformed comparator: {token!r}")

            operator = match.group(1) or "="
            bound = _parse_version(match.group(2))

            if operator in ("^", "~"):
                major, minor, patch = bound[:3]
                if operator == "~":
                    upper_core = (major, minor + 1, 0)
                elif major > 0:
                    upper_core = (major + 1, 0, 0)
                elif minor > 0:
                    upper_core = (0, minor + 1, 0)
                else:
                    upper_core = (0, 0, patch + 1)

                upper = (*upper_core, (1, ()))
                comparators.extend(((">=", bound), ("<", upper)))
            else:
                comparators.append((operator, bound))

        comparator_sets.append(comparators)

    def matches(operator: str, bound: tuple) -> bool:
        match operator:
            case "=":
                return candidate == bound
            case ">":
                return candidate > bound
            case ">=":
                return candidate >= bound
            case "<":
                return candidate < bound
            case "<=":
                return candidate <= bound
        raise AssertionError("Unexpected operator")

    return any(
        all(matches(operator, bound) for operator, bound in comparators)
        for comparators in comparator_sets
    )
