def satisfies(version: str, range_expr: str) -> bool:
    if not range_expr.strip():
        raise ValueError("empty range expression")

    # Parse the version
    v = _parse_version(version)

    # Split into comparator sets
    sets = [s.strip() for s in range_expr.split('||')]
    if not all(sets):
        raise ValueError("empty comparator set")

    for set_expr in sets:
        comparators = set_expr.split()
        if not comparators:
            raise ValueError("empty comparator set")

        satisfied = True
        for comp in comparators:
            if comp == '*':
                continue
            op, ver = _parse_comparator(comp)
            if not _compare(v, op, ver):
                satisfied = False
                break
        if satisfied:
            return True
    return False

def _parse_version(version: str) -> Tuple[int, int, int, Optional[List[str]], Optional[List[str]]]:
    # Regex for semantic version
    pattern = r'^(\d+)\.(\d+)\.(\d+)(?:-([a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)*))?(?:\+([a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)*))?$'
    match = re.fullmatch(pattern, version)
    if not match:
        raise ValueError(f"malformed version: {version}")

    major = int(match.group(1))
    minor = int(match.group(2))
    patch = int(match.group(3))
    prerelease = match.group(4)
    build = match.group(5)

    if prerelease:
        prerelease_parts = prerelease.split('.')
    else:
        prerelease_parts = None

    if build:
        build_parts = build.split('.')
    else:
        build_parts = None

    return (major, minor, patch, prerelease_parts, build_parts)

def _parse_comparator(comp: str) -> Tuple[str, Tuple[int, int, int, Optional[List[str]], Optional[List[str]]]]:
    # Regex for comparator
    pattern = r'^([=<>~^~]*)(.+)$'
    match = re.fullmatch(pattern, comp)
    if not match:
        raise ValueError(f"malformed comparator: {comp}")

    op_part = match.group(1)
    version_part = match.group(2)

    if not op_part:
        op = '='
    else:
        op = op_part
        if op not in ('=', '>', '>=', '<', '<=', '^', '~'):
            raise ValueError(f"unknown operator: {op}")

    ver = _parse_version(version_part)
    return (op, ver)

