        return _version_compare(v1, v2) == 0
    elif op == '>':
        return _version_compare(v1, v2) > 0
    elif op == '>=':
        return _version_compare(v1, v2) >= 0
    elif op == '<':
        return _version_compare(v1, v2) < 0
    elif op == '<=':
        return _version_compare(v1, v2) <= 0
    elif op == '^':
        return _caret_compare(v1, v2)
    elif op == '~':
        return _tilde_compare(v1, v2)
    else:
        raise ValueError(f"unknown operator: {op}")

def _version_compare(v1: Tuple[int, int, int, Optional[List[str]], Optional[List[str]]],
                     v2: Tuple[int, int, int, Optional[List[str]], Optional[List[str]]]) -> int:
    # Compare major, minor, patch
