import re


def satisfies(version: str, range_expr: str) -> bool:
    version_pattern = re.compile(
        r"(0|[1-9][0-9]*)\."
        r"(0|[1-9][0-9]*)\."
        r"(0|[1-9][0-9]*)"
        r"(?:-([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?"
        r"(?:\+[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*)?"
    )

    def parse_version(text):
        match = version_pattern.fullmatch(text)
        if match is None:
            raise ValueError(f"Malformed version: {text!r}")
        major, minor, patch, prerelease = match.groups()
        return (
            (major, minor, patch),
            None if prerelease is None else tuple(prerelease.split(".")),
        )

    def number_key(text):
        # Compare arbitrary-size numbers without Python's int conversion limit.
        normalized = text.lstrip("0") or "0"
        return len(normalized), normalized

    def precedence_key(core, prerelease=None):
        identifiers = tuple(
            (0, *number_key(identifier))
            if identifier.isdigit()
            else (1, 0, identifier)
            for identifier in (prerelease or ())
        )
        return (
            tuple(number_key(component) for component in core),
            prerelease is None,
            identifiers,
        )

    def increment(text):
        digits = list(text)
        index = len(digits) - 1
        while index >= 0 and digits[index] == "9":
            digits[index] = "0"
            index -= 1
        if index < 0:
            digits.insert(0, "1")
        else:
            digits[index] = chr(ord(digits[index]) + 1)
        return "".join(digits)

    core, prerelease = parse_version(version)
    candidate = precedence_key(core, prerelease)
    comparator_sets = []

    # Parse every set before evaluating, so invalid alternatives always raise.
    for set_text in range_expr.split("||"):
        tokens = set_text.split()
        if not tokens:
            raise ValueError("The range and every comparator set must be non-empty")

        comparators = []
        for token in tokens:
            if token == "*":
                continue

            match = re.fullmatch(r"(>=|<=|[=<>^~])?(.+)", token)
            if match is None:
                raise ValueError(f"Malformed comparator: {token!r}")

            operator, target_text = match.groups()
            operator = operator or "="
            target_core, target_prerelease = parse_version(target_text)
            target = precedence_key(target_core, target_prerelease)

            if operator in ("^", "~"):
                major, minor, patch = target_core
                if operator == "~":
                    upper_core = (major, increment(minor), "0")
                elif major != "0":
                    upper_core = (increment(major), "0", "0")
                elif minor != "0":
                    upper_core = ("0", increment(minor), "0")
                else:
                    upper_core = ("0", "0", increment(patch))

                comparators.append((">=", target))
                comparators.append(("<", precedence_key(upper_core)))
            else:
                comparators.append((operator, target))

        comparator_sets.append(comparators)

    def matches(operator, target):
        if operator == "=":
            return candidate == target
        if operator == ">":
            return candidate > target
        if operator == ">=":
            return candidate >= target
        if operator == "<":
            return candidate < target
        if operator == "<=":
            return candidate <= target
        raise ValueError(f"Unknown operator: {operator!r}")

    return any(
        all(matches(operator, target) for operator, target in comparators)
        for comparators in comparator_sets
    )
