import re
from bisect import bisect_right
from calendar import monthrange
from datetime import date, datetime


def next_run(expr: str, after: str) -> str:
    """Find the next firing within five calendar years, inclusive.

    A February 29 five-year deadline is clamped to February 28.
    """
    if not isinstance(expr, str):
        raise ValueError("Expression must be a string")

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Expression must contain exactly five fields")

    item_pattern = re.compile(
        r"(\*|([0-9]+)(?:-([0-9]+))?)(?:/([0-9]+))?"
    )

    def capped_decimal(text: str, cap: int) -> int:
        # Avoid Python's integer-string length limit. Values above cap
        # are indistinguishable for validation or sufficiently large steps.
        text = text.lstrip("0") or "0"
        if len(text) > len(str(cap)):
            return cap + 1
        return min(int(text), cap + 1)

    def parse_field(text: str, low: int, high: int) -> set[int]:
        values = set()

        for item in text.split(","):
            match = item_pattern.fullmatch(item)
            if match is None:
                raise ValueError(f"Invalid cron item: {item!r}")

            base, first, last, step_text = match.groups()

            if base == "*":
                start, stop = low, high
            else:
                start = capped_decimal(first, high)
                stop = (
                    start if last is None
                    else capped_decimal(last, high)
                )
                if not (low <= start <= stop <= high):
                    raise ValueError(f"Invalid cron range: {item!r}")
                if step_text is not None and last is None:
                    raise ValueError("Steps on single numbers are invalid")

            step = (
                1 if step_text is None
                else capped_decimal(step_text, high - low + 1)
            )
            if step == 0:
                raise ValueError("Step must be positive")

            values.update(range(start, stop + 1, step))

        return values

    bounds = ((0, 59), (0, 23), (1, 31), (1, 12), (0, 6))
    minutes, hours, month_days, months, week_days = [
        parse_field(field, low, high)
        for field, (low, high) in zip(fields, bounds)
    ]

    if not isinstance(after, str) or re.fullmatch(
        r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}", after
    ) is None:
        raise ValueError("after must have format YYYY-MM-DD HH:MM")

    start = datetime.fromisoformat(after)

    if start.year + 5 > 9999:
        deadline = datetime(9999, 12, 31, 23, 59)
    else:
        deadline_year = start.year + 5
        deadline_day = min(
            start.day, monthrange(deadline_year, start.month)[1]
        )
        deadline = start.replace(year=deadline_year, day=deadline_day)

    dom_unrestricted = fields[2] == "*"
    dow_unrestricted = fields[4] == "*"

    daily_minutes = sorted(hour * 60 + minute
                           for hour in hours for minute in minutes)
    first_index = bisect_right(
        daily_minutes, start.hour * 60 + start.minute
    )

    start_ordinal = start.date().toordinal()
    for ordinal in range(start_ordinal, deadline.date().toordinal() + 1):
        day = date.fromordinal(ordinal)
        if day.month not in months:
            continue

        dom_matches = day.day in month_days
        dow_matches = (day.weekday() + 1) % 7 in week_days

        if dom_unrestricted and dow_unrestricted:
            day_matches = True
        elif dom_unrestricted:
            day_matches = dow_matches
        elif dow_unrestricted:
            day_matches = dom_matches
        else:
            day_matches = dom_matches or dow_matches

        if not day_matches:
            continue

        index = first_index if ordinal == start_ordinal else 0
        if index == len(daily_minutes):
            continue

        minute_of_day = daily_minutes[index]

