def merge_intervals(intervals: list[tuple[int, int, str]]) -> list[tuple[int, int, list[str]]]:
    """Merge overlapping or touching half-open intervals and collect labels."""
    ordered = sorted(intervals, key=lambda item: item[0])
    merged = []

    for start, end, label in ordered:
        if start >= end:
            raise ValueError(f"Invalid interval: [{start}, {end})")

        if not merged or start > merged[-1][1]:
            merged.append([start, end, {label}])
        else:
            merged[-1][1] = max(merged[-1][1], end)
            merged[-1][2].add(label)

    return [(start, end, sorted(labels)) for start, end, labels in merged]
