from fractions import Fraction

def token_bucket(capacity: int, refill_per_sec: float, requests: list[tuple[float, int]]) -> list[bool]:
    if capacity < 1:
        raise ValueError("capacity must be at least 1")
    if refill_per_sec < 0:
        raise ValueError("refill_per_sec must be non-negative")

    cap = Fraction(capacity)
    refill = Fraction(refill_per_sec)
    tokens = cap
    last_time = None
    result = []

    for timestamp, cost in requests:
        if not isinstance(cost, int) or isinstance(cost, bool) or cost < 1:
            raise ValueError("cost must be an integer >= 1")
        if last_time is not None and timestamp < last_time:
            raise ValueError("timestamps must be non-decreasing")

        if last_time is not None:
            elapsed = Fraction(timestamp) - Fraction(last_time)
            tokens = min(cap, tokens + elapsed * refill)

        if tokens >= cost:
            result.append(True)
            tokens -= cost
        else:
            result.append(False)

        last_time = timestamp

    return result
