import heapq

def topo_order(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    # Check for duplicate nodes
    if len(nodes) != len(set(nodes)):
        raise ValueError("nodes contains duplicates")

    node_set = set(nodes)

    # Validate edges and build graph
    adj: dict[str, list[str]] = {node: [] for node in nodes}
    in_degree: dict[str, int] = {node: 0 for node in nodes}
    seen_edges: set[tuple[str, str]] = set()

    for a, b in edges:
        if a not in node_set or b not in node_set:
            raise ValueError(f"edge mentions node not in nodes: ({a}, {b})")
        if a == b:
            raise ValueError(f"self-loop detected: ({a}, {b})")
        if (a, b) not in seen_edges:
            seen_edges.add((a, b))
            adj[a].append(b)
            in_degree[b] += 1

    # Kahn's algorithm with min-heap for lexicographically smallest order
    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result: list[str] = []

    while heap:
        node = heapq.heappop(heap)
        result.append(node)

        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("cycle detected in edges")

    return result
