def wrap_text(text: str, width: int) -> list[str]:
    if width < 1:
        raise ValueError("width must be at least 1")

    words = text.split()
    if not words:
        return []

    lines = []
    current_line = []
    current_length = 0

    for word in words:
        if len(word) > width:
            # Handle long word
            if current_line:
                lines.append(" ".join(current_line))
                current_line = []
                current_length = 0

            # Split the long word into chunks
            for i in range(0, len(word), width):
                chunk = word[i:i+width]
                if i + width < len(word):
                    lines.append(chunk)
                else:
                    current_line.append(chunk)
                    current_length = len(chunk)
        else:
            # Try to add the word to current line
            if current_line:
                new_length = current_length + 1 + len(word)
            else:
                new_length = len(word)

            if new_length <= width:
                current_line.append(word)
                current_length = new_length
            else:
                lines.append(" ".join(current_line))
                current_line = [word]
                current_length = len(word)

    if current_line:
        lines.append(" ".join(current_line))

    return lines
