            not isinstance(value, str)
            or len(value) != 5
            or value[2] != ":"
            or any(value[i] not in "0123456789" for i in (0, 1, 3, 4))
        ):
            raise ValueError(f"Malformed time: {value!r}")
        hour, minute = int(value[:2]), int(value[3:])
        if hour > 23 or minute > 59:
            raise ValueError(f"Malformed time: {value!r}")
        return hour * 60 + minute

    start = parse_time(day_start)
    end = parse_time(day_end)
    if end <= start:
        raise ValueError("day_end must be later than day_start")
    if duration_min < 1:
        raise ValueError("duration_min must be at least 1")

    intervals: list[tuple[int, int]] = []
    for person in busy:
        for busy_start, busy_end in person:
            left = parse_time(busy_start)
            right = parse_time(busy_end)
            if right <= left:
                raise ValueError("Busy interval end must be later than its start")
            left, right = max(left, start), min(right, end)
            if left < right:
                intervals.append((left, right))

    intervals.sort()
    candidate = start
    for left, right in intervals:
        if left - candidate >= duration_min:
            return f"{candidate // 60:02d}:{candidate % 60:02d}"
        candidate = max(candidate, right)

    if end - candidate >= duration_min:
        return f"{candidate // 60:02d}:{candidate % 60:02d}"
    return None
```

