import re


def negotiate_language(header: str, available: list[str]) -> str | None:
    range_pattern = re.compile(
        r"(?:\*|[A-Za-z]{1,8}(?:-[A-Za-z0-9]{1,8})*)"
    )
    quality_pattern = re.compile(r"(?:0(?:\.[0-9]{0,3})?|1(?:\.0{0,3})?)")

    entries: list[tuple[str, int, int, int]] = []
    seen: set[str] = set()

    for position, raw_entry in enumerate(header.split(",")):
        entry = raw_entry.strip()
        if not entry:
            continue

        parts = entry.split(";")
        language_range = parts[0].strip()
        if range_pattern.fullmatch(language_range) is None:
            raise ValueError(f"Malformed language range: {language_range!r}")

        quality = 1000
        if len(parts) > 2:
            raise ValueError(f"Unexpected parameters: {entry!r}")
        if len(parts) == 2:
            parameter = parts[1].split("=")
            if len(parameter) != 2 or parameter[0].strip().lower() != "q":
                raise ValueError(f"Malformed quality parameter: {parts[1]!r}")

            value = parameter[1].strip()
            if quality_pattern.fullmatch(value) is None:
                raise ValueError(f"Malformed quality value: {value!r}")

            whole, _, fraction = value.partition(".")
            quality = int(whole) * 1000 + int(fraction.ljust(3, "0"))

        language_range = language_range.lower()
        if language_range not in seen:
            seen.add(language_range)
            specificity = 0 if language_range == "*" else len(language_range)
            entries.append((language_range, specificity, quality, position))

    best_tag: str | None = None
    best_key: tuple[int, int, int] | None = None

    for available_position, tag in enumerate(available):
        normalized_tag = tag.lower()
        controlling_entry: tuple[str, int, int, int] | None = None

        for entry in entries:
            language_range, specificity, _, _ = entry
            if (
                language_range == "*"
                or normalized_tag == language_range
                or normalized_tag.startswith(language_range + "-")
            ):
                if controlling_entry is None or specificity > controlling_entry[1]:
                    controlling_entry = entry

        if controlling_entry is None:
            continue

        _, _, quality, header_position = controlling_entry
        if quality == 0:
            continue

        key = (quality, -header_position, -available_position)
        if best_key is None or key > best_key:
            best_key = key
            best_tag = tag

    return best_tag
```

```python
from collections import OrderedDict


def lfu_cache(capacity: int, ops: list[tuple]) -> list:
    if capacity < 0:
        raise ValueError("capacity must be nonnegative")

    # key -> (value, frequency)
    cache = {}
    # frequency -> keys ordered from least to most recently used
    buckets = {}
    min_frequency = 0
    results = []

    def touch(key, value):
        nonlocal min_frequency

        _, frequency = cache[key]
        bucket = buckets[frequency]
        del bucket[key]

        if not bucket:
            del buckets[frequency]
            if min_frequency == frequency:
                min_frequency = frequency + 1

        frequency += 1
        cache[key] = (value, frequency)
        buckets.setdefault(frequency, OrderedDict())[key] = None

    for op in ops:
        if not isinstance(op, tuple) or not (
            (len(op) == 2 and op[0] == "get")
            or (len(op) == 3 and op[0] == "put")
        ):
            raise ValueError(f"Invalid operation: {op!r}")

        if op[0] == "get":
            key = op[1]
            if key not in cache:
                results.append(None)
            else:
                value, _ = cache[key]
                results.append(value)
                touch(key, value)
            continue

        _, key, value = op

        if capacity == 0:
            continue

        if key in cache:
            touch(key, value)
            continue

        if len(cache) == capacity:
            bucket = buckets[min_frequency]
            evicted_key, _ = bucket.popitem(last=False)
            del cache[evicted_key]
            if not bucket:
                del buckets[min_frequency]

        cache[key] = (value, 1)
        buckets.setdefault(1, OrderedDict())[key] = None
        min_frequency = 1

    return results
```

