import re


def natural_sort(items: list[str]) -> list[str]:
    def sort_key(text: str) -> tuple:
        runs = []
        for run in re.findall(r"[0-9]+|[^0-9]+", text):
            if "0" <= run[0] <= "9":
                significant = run.lstrip("0")
                runs.append((0, len(significant), significant, len(run)))
            else:
                runs.append((1, run.lower()))
        return (tuple(runs), text)

    return sorted(items, key=sort_key)
