import re
from datetime import datetime, timedelta

_TIME_RE = re.compile(r'^([01]\d|2[0-3]):([0-5]\d)$')

def _parse_time(t: str) -> int:
    """Parse HH:MM into minutes since midnight. Raises ValueError if malformed."""
    if not isinstance(t, str):
        raise ValueError(f"malformed time: {t!r}")
    m = _TIME_RE.match(t)
    if not m:
        raise ValueError(f"malformed time: {t!r}")
    return int(m.group(1)) * 60 + int(m.group(2))

def _fmt_time(minutes: int) -> str:
    """Format minutes since midnight as HH:MM."""
    h, m = divmod(minutes, 60)
    return f"{h:02d}:{m:02d}"

def first_common_slot(busy: list[list[tuple[str, str]]], day_start: str, day_end: str, duration_min: int) -> str | None:
    start = _parse_time(day_start)
    end = _parse_time(day_end)

    if end <= start:
        raise ValueError("day_end must be after day_start")
    if not isinstance(duration_min, int) or isinstance(duration_min, bool) or duration_min < 1:
        raise ValueError("duration_min must be a positive integer")

    # Collect and validate all busy intervals, clipping to the working day.
    clipped: list[tuple[int, int]] = []
    for person in busy:
        if not isinstance(person, list):
            raise ValueError("each person's busy list must be a list")
        for interval in person:
            if not isinstance(interval, tuple) or len(interval) != 2:
                raise ValueError("each busy interval must be a (start, end) tuple")
            s_str, e_str = interval
            s = _parse_time(s_str)
            e = _parse_time(e_str)
            if e <= s:
                raise ValueError(f"busy interval end must be after start: {interval!r}")
            # Clip to [start, end)
            cs = max(s, start)
            ce = min(e, end)
            if cs < ce:
                clipped.append((cs, ce))

    # Merge overlapping/adjacent intervals.
    clipped.sort()
    merged: list[tuple[int, int]] = []
    for s, e in clipped:
        if merged and s <= merged[-1][1]:
            if e > merged[-1][1]:
                merged[-1] = (merged[-1][0], e)
        else:
            merged.append((s, e))

    # Scan for the first free slot of duration_min.
    cursor = start
    for s, e in merged:
        if cursor + duration_min <= s:
            return _fmt_time(cursor)
        if e > cursor:
            cursor = e
    if cursor + duration_min <= end:
        return _fmt_time(cursor)

    return None
```

```python
import re

def natural_sort(items: list[str]) -> list[str]:
    _run_re = re.compile(r'(\d+)')

    def split_runs(s: str) -> list[tuple[bool, str]]:
        parts = _run_re.split(s)
        runs: list[tuple[bool, str]] = []
        for i, part in enumerate(parts):
            if part == '':
                continue
            if i % 2 == 1:  # digit run (captured group)
                runs.append((True, part))
            else:           # non-digit run
                runs.append((False, part))
        return runs

    def run_key(run: tuple[bool, str]) -> tuple:
        is_digit, text = run
        if is_digit:
            # digit run: numeric value, then fewer leading zeros first
            return (0, int(text), len(text))
        else:
            # non-digit run: case-insensitive comparison
            return (1, text.lower())

    def sort_key(s: str) -> tuple:
        runs = split_runs(s)
        # Build a key that encodes: run comparisons, then number of runs, then plain string
        run_keys = tuple(run_key(r) for r in runs)
        return (run_keys, len(runs), s)

    return sorted(items, key=sort_key)
