import re
from typing import Optional

def negotiate_language(header: str, available: list[str]) -> Optional[str]:
    # Parse the Accept-Language header
    entries = []
    if not header.strip():
        return None

    # Split into entries, ignoring empty ones and whitespace
    raw_entries = [e.strip() for e in header.split(',') if e.strip()]

    for entry in raw_entries:
        # Split into language range and parameters
        parts = [p.strip() for p in re.split(r';(?![^"]*"(?:(?:[^"]*"){2})*[^"]*$)', entry)]
        lang_range = parts[0]
        q_value = 1.0

        # Validate language range
        if lang_range != '*':
            if not re.fullmatch(r'^[a-zA-Z]{1,8}(?:-[a-zA-Z0-9]{1,8})*$', lang_range):
                raise ValueError(f"Invalid language range: {lang_range}")

        # Process parameters
        for param in parts[1:]:
            if '=' not in param:
                raise ValueError(f"Invalid parameter: {param}")
            key, value = (p.strip() for p in param.split('=', 1))
            if key.lower() != 'q':
                raise ValueError(f"Unsupported parameter: {key}")
            try:
                q_value = float(value)
                if not (0 <= q_value <= 1):
                    raise ValueError
                # Check for more than 3 decimal places
                if len(value.split('.')[-1]) > 3:
                    raise ValueError
            except ValueError:
                raise ValueError(f"Invalid q-value: {value}")

        entries.append((lang_range.lower(), q_value, len(entries)))

    # Process available languages
    best_tag = None
    best_quality = -1.0
    best_entry_index = float('inf')
    best_available_index = float('inf')

    for avail_index, tag in enumerate(available):
        tag_lower = tag.lower()
        current_quality = 0.0
        current_entry_index = float('inf')

        for lang_range, q_value, entry_index in entries:
            if q_value == 0:
                continue
            if lang_range == '*':
                if q_value > current_quality or (q_value == current_quality and entry_index < current_entry_index):
                    current_quality = q_value
                    current_entry_index = entry_index
            elif lang_range == tag_lower:
                if q_value > current_quality or (q_value == current_quality and entry_index < current_entry_index):
                    current_quality = q_value
                    current_entry_index = entry_index
            elif tag_lower.startswith(lang_range + '-'):
                # Check if this is a more specific match than current
                if len(lang_range) > len(entries[current_entry_index][0]) if current_entry_index != float('inf') else True:
                    if q_value > current_quality or (q_value == current_quality and entry_index < current_entry_index):
                        current_quality = q_value
                        current_entry_index = entry_index

        if current_quality > best_quality or \
           (current_quality == best_quality and current_entry_index < best_entry_index) or \
           (current_quality == best_quality and current_entry_index == best_entry_index and avail_index < best_available_index):
            best_quality = current_quality
            best_entry_index = current_entry_index
            best_available_index = avail_index
            best_tag = tag

    return best_tag if best_quality > 0 else None
