```python
def first_common_slot(busy: list[list[tuple[str, str]]], day_start: str, day_end: str, duration_min: int) -> str | None:
    import itertools

    def parse_time(time_str: str) -> int:
        try:
            hh, mm = map(int, time_str.split(':'))
            if not (0 <= hh <= 23 and 0 <= mm <= 59):
                raise ValueError
            return hh * 60 + mm
        except (ValueError, AttributeError):
            raise ValueError(f"Invalid time format: {time_str}")

    def format_time(minutes: int) -> str:
        hh = minutes // 60
        mm = minutes % 60
        return f"{hh:02d}:{mm:02d}"

    # Validate inputs
    if duration_min < 1:
        raise ValueError("Duration must be at least 1 minute")

    start_min = parse_time(day_start)
    end_min = parse_time(day_end)
    if end_min <= start_min:
        raise ValueError("Day end must be after day start")

    # Collect all busy intervals, convert to minutes, and validate
    all_busy = []
    for person in busy:
        for interval in person:
            if len(interval) != 2:
                raise ValueError("Each busy interval must be a tuple of (start, end)")
            s, e = interval
            s_min = parse_time(s)
            e_min = parse_time(e)
            if e_min <= s_min:
                raise ValueError(f"Busy interval end must be after start: {interval}")
            all_busy.append((s_min, e_min))

    if not all_busy:
        # No busy intervals, check if the whole day has enough time
        if end_min - start_min >= duration_min:
            return day_start
        else:
            return None

    # Merge all busy intervals
    all_busy.sort()
    merged = []
    for interval in all_busy:
        if not merged:
            merged.append(list(interval))
        else:
            last_start, last_end = merged[-1]
            current_start, current_end = interval
            if current_start <= last_end:
                # Overlapping or adjacent, merge them
                new_start = last_start
                new_end = max(last_end, current_end)
                merged[-1] = [new_start, new_end]
            else:
                merged.append(list(interval))

    # Check the gap before the first busy interval
    first_busy_start = merged[0][0]
    if first_busy_start - start_min >= duration_min:
        return day_start

    # Check gaps between busy intervals
    for i in range(1, len(merged)):
        prev_end = merged[i-1][1]
        curr_start = merged[i][0]
        gap = curr_start - prev_end
        if gap >= duration_min:
            candidate_start = prev_end
            return format_time(candidate_start)

    # Check the gap after the last busy interval
    last_busy_end = merged[-1][1]
    if end_min - last_busy_end >= duration_min:
        return format_time(last_busy_end)

    return None
```

```python
def split_sql(script: str) -> list[str]:
    statements: list[str] = []
    buffer: list[str] = []
    i = 0
    n = len(script)

    while i < n:
        char = script[i]

        if char in ("'", '"'):
            quote = char
            start = i
            i += 1
            while i < n:
                if script[i] == quote:
                    if i + 1 < n and script[i + 1] == quote:
                        i += 2
                        continue
                    i += 1
                    buffer.append(script[start:i])
                    break
                i += 1
            else:
                kind = "string" if quote == "'" else "identifier"
                raise ValueError(f"Unterminated {kind}")
            continue

        if script.startswith("--", i):
            newline = script.find("\n", i + 2)
            i = n if newline == -1 else newline
            continue

        if script.startswith("/*", i):
            end = script.find("*/", i + 2)
            if end == -1:
                raise ValueError("Unterminated block comment")
            buffer.append(" ")
            i = end + 2
            continue

        if char == ";":
            statement = "".join(buffer).strip()
            if statement:
                statements.append(statement)
            buffer.clear()
        else:
            buffer.append(char)
        i += 1

    statement = "".join(buffer).strip()
    if statement:
        statements.append(statement)

    return statements
```

