import heapq

def topo_order(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    if len(set(nodes)) != len(nodes):
        raise ValueError("nodes contains duplicates")

    node_set = set(nodes)
    indegree = {node: 0 for node in nodes}
    adjacency = {node: [] for node in nodes}

    seen_edges = set()
    for a, b in edges:
        if a not in node_set or b not in node_set:
            raise ValueError("edge mentions a node not in nodes")
        if (a, b) in seen_edges:
            continue
        seen_edges.add((a, b))
        adjacency[a].append(b)
        indegree[b] += 1

    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        node = heapq.heappop(heap)
        order.append(node)

        for neighbor in adjacency[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(order) != len(nodes):
        raise ValueError("cycle detected")

    return order
```

```python
def first_common_slot(
    busy: list[list[tuple[str, str]]],
    day_start: str,
    day_end: str,
    duration_min: int,
) -> str | None:
    def parse_time(value: str) -> int:
        if (
            not isinstance(value, str)
            or len(value) != 5
            or value[2] != ":"
            or any(ch not in "0123456789" for ch in value[:2] + value[3:])
        ):
            raise ValueError(f"Malformed time: {value!r}")

        hour, minute = int(value[:2]), int(value[3:])
        if hour > 23 or minute > 59:
            raise ValueError(f"Malformed time: {value!r}")
        return hour * 60 + minute

    work_start = parse_time(day_start)
    work_end = parse_time(day_end)
    if work_end <= work_start:
        raise ValueError("day_end must be later than day_start")
    if duration_min < 1:
        raise ValueError("duration_min must be at least 1")

    # Validate every interval before considering any possible return value.
    intervals: list[tuple[int, int]] = []
    for person in busy:
        for start_text, end_text in person:
            start = parse_time(start_text)
            end = parse_time(end_text)
            if end <= start:
                raise ValueError("Busy interval end must be later than start")

            start = max(start, work_start)
            end = min(end, work_end)
            if start < end:
                intervals.append((start, end))

    intervals.sort()
    candidate = work_start

    for start, end in intervals:
        if start - candidate >= duration_min:
            return f"{candidate // 60:02d}:{candidate % 60:02d}"
        candidate = max(candidate, end)

    if work_end - candidate >= duration_min:
        return f"{candidate // 60:02d}:{candidate % 60:02d}"
    return None
```

```python
def resolve_pointer(doc, pointer: str):
    if pointer == "":
        return doc

    if not pointer.startswith("/"):
        raise ValueError("pointer must start with '/' or be empty")

    current = doc
    # Split on '/'; the first element is empty due to leading '/'
    tokens = pointer.split("/")[1:]

    for token in tokens:
        # Decode ~1 before ~0
        decoded = []
        i = 0
        while i < len(token):
            ch = token[i]
            if ch == "~":
                if i + 1 >= len(token):
                    raise ValueError("invalid escape: '~' at end of token")
                nxt = token[i + 1]
                if nxt == "1":
                    decoded.append("/")
                    i += 2
                elif nxt == "0":
                    decoded.append("~")
                    i += 2
                else:
                    raise ValueError("invalid escape: '~' followed by " + repr(nxt))
            else:
                decoded.append(ch)
                i += 1
        key = "".join(decoded)

        if isinstance(current, dict):
            if key not in current:
                raise KeyError(key)
            current = current[key]
        elif isinstance(current, list):
            if key == "-":
                raise KeyError(key)
            # Must be ASCII digits, no leading zeros unless "0" itself
            if not key.isascii() or not key.isdigit():
                raise ValueError("invalid array index: " + repr(key))
            if len(key) > 1 and key[0] == "0":
                raise ValueError("invalid array index with leading zero: " + repr(key))
            idx = int(key)
            if idx >= len(current):
                raise KeyError(key)
            current = current[idx]
        else:
            raise KeyError(key)

    return current
```

