def token_bucket(capacity: int, refill_per_sec: float, requests: list[tuple[float, int]]) -> list[bool]:
    if capacity < 1:
        raise ValueError("capacity must be >= 1")
    if refill_per_sec < 0:
        raise ValueError("refill_per_sec must be >= 0")

    tokens = float(capacity)
    last_time = None
    result = []

    for timestamp, cost in requests:
        if not isinstance(cost, int) or isinstance(cost, bool) or cost < 1:
            raise ValueError("cost must be an integer >= 1")
        if last_time is not None and timestamp < last_time:
            raise ValueError("timestamps must be non-decreasing")

        if last_time is not None:
            elapsed = timestamp - last_time
            tokens = min(float(capacity), tokens + elapsed * refill_per_sec)

        last_time = timestamp

        if tokens >= cost:
            tokens -= cost
            result.append(True)
        else:
            result.append(False)

    return result
```

```python
def split_sql(script: str) -> list[str]:
    statements: list[str] = []
    parts: list[str] = []
    i = 0
    n = len(script)

    while i < n:
        ch = script[i]

        if ch in ("'", '"'):
            quote = ch
            start = i
            i += 1

            while i < n:
                if script[i] == quote:
                    if i + 1 < n and script[i + 1] == quote:
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    i += 1
            else:
                kind = "string" if quote == "'" else "identifier"
                raise ValueError(f"Unterminated {kind}")

            parts.append(script[start:i])

        elif script.startswith("--", i):
            end = script.find("\n", i + 2)
            i = n if end == -1 else end

        elif script.startswith("/*", i):
            end = script.find("*/", i + 2)
            if end == -1:
                raise ValueError("Unterminated block comment")
            parts.append(" ")
            i = end + 2

        elif ch == ";":
            statement = "".join(parts).strip()
            if statement:
                statements.append(statement)
            parts.clear()
            i += 1

        else:
            parts.append(ch)
            i += 1

    statement = "".join(parts).strip()
    if statement:
        statements.append(statement)

    return statements
```

```python
import re


def resolve_pointer(doc, pointer: str):
    if pointer == "":
        return doc
    if not pointer.startswith("/"):
        raise ValueError("JSON Pointer must be empty or start with '/'")

    tokens = pointer.split("/")[1:]
    for i, token in enumerate(tokens):
        if re.search(r"~(?:[^01]|$)", token):
            raise ValueError(f"Invalid escape in token: {token!r}")
        tokens[i] = token.replace("~1", "/").replace("~0", "~")

    value = doc
    for token in tokens:
        if isinstance(value, dict):
            value = value[token]
        elif isinstance(value, list):
            if token == "-":
                raise KeyError(token)
            if re.fullmatch(r"(?:0|[1-9][0-9]*)", token) is None:
                raise ValueError(f"Invalid array index: {token!r}")

            # Check bounds before conversion, including for enormous indices.
            limit = str(len(value))
            if len(token) > len(limit) or (
                len(token) == len(limit) and token >= limit
            ):
                raise KeyError(token)
            value = value[int(token)]
        else:
            raise KeyError(token)

    return value
