```python
from fractions import Fraction


def token_bucket(
    capacity: int,
    refill_per_sec: float,
    requests: list[tuple[float, int]],
) -> list[bool]:
    if capacity < 1:
        raise ValueError("capacity must be at least 1")
    if refill_per_sec < 0:
        raise ValueError("refill_per_sec must be non-negative")

    if not requests:
        return []

    # Preserve the exact values represented by the input floats.
    rate = Fraction(refill_per_sec)
    tokens = Fraction(capacity)
    previous_time = None
    results: list[bool] = []

    for timestamp, cost in requests:
        if not isinstance(cost, int) or cost < 1:
            raise ValueError("each cost must be an integer >= 1")

        current_time = Fraction(timestamp)
        if previous_time is not None:
            if current_time < previous_time:
                raise ValueError("timestamps must be non-decreasing")
            tokens = min(
                Fraction(capacity),
                tokens + (current_time - previous_time) * rate,
            )

        previous_time = current_time
        allowed = tokens >= cost
        if allowed:
            tokens -= cost
        results.append(allowed)

    return results
```

```python
import re


def negotiate_language(header: str, available: list[str]) -> str | None:
    range_pattern = re.compile(
        r"(?:\*|[A-Za-z]{1,8}(?:-[A-Za-z0-9]{1,8})*)"
    )
    q_pattern = re.compile(
        r"[qQ]\s*=\s*(0(?:\.[0-9]{0,3})?|1(?:\.0{0,3})?)"
    )

    # Keep only the first occurrence of each case-insensitive range.
    ranges: dict[str, tuple[int, int]] = {}

    for position, raw_entry in enumerate(header.split(",")):
        entry = raw_entry.strip()
        if not entry:
            continue

        parts = entry.split(";")
        if len(parts) > 2:
            raise ValueError(f"Invalid Accept-Language entry: {entry!r}")

        language_range = parts[0].strip()
        if range_pattern.fullmatch(language_range) is None:
            raise ValueError(f"Invalid language range: {language_range!r}")

        quality = 1000
        if len(parts) == 2:
            match = q_pattern.fullmatch(parts[1].strip())
            if match is None:
                raise ValueError(f"Invalid quality parameter: {parts[1]!r}")

            whole, _, fraction = match.group(1).partition(".")
            quality = int(whole) * 1000 + int(fraction.ljust(3, "0"))

        ranges.setdefault(language_range.lower(), (quality, position))

    best_tag: str | None = None
    best_key: tuple[int, int, int] | None = None

    for available_position, tag in enumerate(available):
        normalized_tag = tag.lower()
        specificity = -1
        tag_quality = 0
        header_position = 0

        for language_range, (quality, position) in ranges.items():
            if language_range == "*":
                current_specificity = 0
            elif (
                normalized_tag == language_range
                or normalized_tag.startswith(language_range + "-")
            ):
                current_specificity = len(language_range)
            else:
                continue

            if current_specificity > specificity:
                specificity = current_specificity
                tag_quality = quality
                header_position = position

        if tag_quality == 0:
            continue

        key = (tag_quality, -header_position, -available_position)
        if best_key is None or key > best_key:
            best_key = key
            best_tag = tag

    return best_tag
```

