import re
from datetime import date, timedelta


def add_business_days(start: str, days: int, holidays: list[str]) -> str:
    def parse_date(value: str) -> date:
        if not isinstance(value, str) or re.fullmatch(
            r"[0-9]{4}-[0-9]{2}-[0-9]{2}", value
        ) is None:
            raise ValueError(f"Invalid date: {value!r}")
        return date.fromisoformat(value)

    current = parse_date(start)
    holiday_dates = {parse_date(holiday) for holiday in holidays}

    def is_business_day(value: date) -> bool:
        return value.weekday() < 5 and value not in holiday_dates

    if days == 0:
        while not is_business_day(current):
            current += timedelta(days=1)
    else:
        step = timedelta(days=1 if days > 0 else -1)
        remaining = abs(days)
        while remaining:
            current += step
            if is_business_day(current):
                remaining -= 1

    return current.isoformat()
```

```python
import datetime

def add_business_days(start: str, days: int, holidays: list[str]) -> str:
    def parse_date(s: str) -> datetime.date:
        if not isinstance(s, str):
            raise ValueError(f"Invalid date: {s!r}")
        try:
            # Strict parsing: must be exactly YYYY-MM-DD
            if len(s) != 10 or s[4] != '-' or s[7] != '-':
                raise ValueError
            d = datetime.date.fromisoformat(s)
            # fromisoformat is lenient in some Python versions; verify round-trip
            if d.isoformat() != s:
                raise ValueError
            return d
        except (ValueError, TypeError):
            raise ValueError(f"Invalid date format: {s!r}, expected YYYY-MM-DD")

    start_date = parse_date(start)
    holiday_set = set()
    for h in holidays:
        holiday_set.add(parse_date(h))

    def is_business_day(d: datetime.date) -> bool:
        return d.weekday() < 5 and d not in holiday_set

    if days == 0:
        if is_business_day(start_date):
            return start_date.isoformat()
        # Find first business day after start
        d = start_date + datetime.timedelta(days=1)
        while not is_business_day(d):
            d += datetime.timedelta(days=1)
        return d.isoformat()

    if days > 0:
        d = start_date
        count = 0
        while count < days:
            d += datetime.timedelta(days=1)
            if is_business_day(d):
                count += 1
        return d.isoformat()
    else:  # days < 0
        d = start_date
        count = 0
        target = -days
        while count < target:
            d -= datetime.timedelta(days=1)
            if is_business_day(d):
                count += 1
        return d.isoformat()
