```python
def osa_distance(a: str, b: str) -> int:
    """Return the optimal string alignment distance between a and b."""
    if a == b:
        return 0

    # Keep the shorter string in the columns to minimize memory usage.
    if len(a) < len(b):
        a, b = b, a
    if not b:
        return len(a)

    n = len(b)
    previous = list(range(n + 1))
    two_back = previous

    for i, char_a in enumerate(a, start=1):
        current = [i] + [0] * n

        for j, char_b in enumerate(b, start=1):
            current[j] = min(
                previous[j] + 1,                  # Deletion
                current[j - 1] + 1,               # Insertion
                previous[j - 1] + (char_a != char_b),  # Substitution
            )

            if (
                i > 1
                and j > 1
                and char_a == b[j - 2]
                and a[i - 2] == char_b
            ):
                current[j] = min(current[j], two_back[j - 2] + 1)

        two_back, previous = previous, current

    return previous[n]
```

```python
def osa_distance(a: str, b: str) -> int:
    if a == b:
        return 0

    # Keep the shorter string in the columns to minimize memory usage.
    if len(a) < len(b):
        a, b = b, a

    n = len(b)
    if n == 0:
        return len(a)

    previous_previous = None
    previous = list(range(n + 1))

    for i, char_a in enumerate(a, 1):
        current = [i] + [0] * n
        for j, char_b in enumerate(b, 1):
            current[j] = min(
                previous[j] + 1,                  # Deletion
                current[j - 1] + 1,               # Insertion
                previous[j - 1] + (char_a != char_b),  # Substitution
            )
            if (
                i > 1
                and j > 1
                and char_a == b[j - 2]
                and a[i - 2] == char_b
            ):
                current[j] = min(
                    current[j],
                    previous_previous[j - 2] + 1,
                )

        previous_previous, previous = previous, current

    return previous[n]
