```python
def wrap_text(text: str, width: int) -> list[str]:
    if width < 1:
        raise ValueError("width must be at least 1")

    words = text.split()
    if not words:
        return []

    lines: list[str] = []
    current = ""

    for word in words:
        if len(word) > width:
            if current:
                lines.append(current)
                current = ""

            pieces = [word[i:i + width] for i in range(0, len(word), width)]
            lines.extend(pieces[:-1])
            current = pieces[-1]
        elif not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word

    if current:
        lines.append(current)

    return lines
```

```python
import ipaddress
import re


_CIDR_PATTERN = re.compile(
    r"(0|[1-9][0-9]{0,2})\."
    r"(0|[1-9][0-9]{0,2})\."
    r"(0|[1-9][0-9]{0,2})\."
    r"(0|[1-9][0-9]{0,2})/([0-9]+)"
)


def _parse_cidr(block: str) -> ipaddress.IPv4Network:
    if not isinstance(block, str):
        raise ValueError(f"Invalid IPv4 CIDR: {block!r}")

    match = _CIDR_PATTERN.fullmatch(block)
    if match is None:
        raise ValueError(f"Invalid IPv4 CIDR: {block!r}")

    octets = [int(part) for part in match.groups()[:4]]
    prefix_text = match.group(5).lstrip("0") or "0"
    if any(octet > 255 for octet in octets) or len(prefix_text) > 2:
        raise ValueError(f"Invalid IPv4 CIDR: {block!r}")

    prefix = int(prefix_text)
    if prefix > 32:
        raise ValueError(f"Invalid IPv4 CIDR: {block!r}")

    address = 0
    for octet in octets:
        address = (address << 8) | octet

    return ipaddress.IPv4Network((address, prefix), strict=True)


def cidr_subtract(base: str, remove: list[str]) -> list[str]:
    base_network = _parse_cidr(base)
    base_start = int(base_network.network_address)
    base_end = int(base_network.broadcast_address)

    intervals: list[tuple[int, int]] = []
    for block in remove:
        network = _parse_cidr(block)
        start = max(base_start, int(network.network_address))
        end = min(base_end, int(network.broadcast_address))
        if start <= end:
            intervals.append((start, end))

    intervals.sort()
    result: list[str] = []

    def append_range(start: int, end: int) -> None:
        result.extend(
            str(network)
            for network in ipaddress.summarize_address_range(
                ipaddress.IPv4Address(start),
                ipaddress.IPv4Address(end),
            )
        )

    cursor = base_start
    for start, end in intervals:
        if end < cursor:
            continue
        if start > cursor:
            append_range(cursor, start - 1)
        cursor = end + 1
        if cursor > base_end:
            break

    if cursor <= base_end:
        append_range(cursor, base_end)

    return result
```

```python
from fractions import Fraction


def evaluate(expr: str) -> Fraction:
    tokens: list[int | str | None] = []
    i = 0

    while i < len(expr):
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif "0" <= ch <= "9":
            value = 0
            while i < len(expr) and "0" <= expr[i] <= "9":
                value = value * 10 + ord(expr[i]) - ord("0")
                i += 1
            tokens.append(value)
        elif ch == "*" and i + 1 < len(expr) and expr[i + 1] == "*":
            tokens.append("**")
            i += 2
        elif ch in "+-*/()":
            tokens.append(ch)
            i += 1
        else:
            raise ValueError(f"Unknown character: {ch!r}")

    tokens.append(None)
    pos = 0

    def parse_atom() -> Fraction:
        nonlocal pos
        token = tokens[pos]
        if isinstance(token, int):
            pos += 1
            return Fraction(token)
        if token == "(":
            pos += 1
            value = parse_sum()
            if tokens[pos] != ")":
                raise ValueError("Missing closing parenthesis")
            pos += 1
            return value
        raise ValueError("Expected an integer or '('")

    def parse_power() -> Fraction:
        nonlocal pos
        base = parse_atom()
        if tokens[pos] == "**":
            pos += 1
            exponent = parse_unary()
            if exponent.denominator != 1:
                raise ValueError("Exponent must be an integer")
            return base ** exponent.numerator
        return base

    def parse_unary() -> Fraction:
        nonlocal pos
        sign = 1
        while tokens[pos] in ("+", "-"):
            if tokens[pos] == "-":
                sign = -sign
            pos += 1
        return sign * parse_power()

    def parse_product() -> Fraction:
        nonlocal pos
        value = parse_unary()
        while tokens[pos] in ("*", "/"):
            operator = tokens[pos]
            pos += 1
            right = parse_unary()
            if operator == "*":
                value *= right
            else:
                value /= right
        return value

    def parse_sum() -> Fraction:
        nonlocal pos
        value = parse_product()
        while tokens[pos] in ("+", "-"):
            operator = tokens[pos]
            pos += 1
            right = parse_product()
            if operator == "+":
                value += right
            else:
                value -= right
        return value

    result = parse_sum()
    if tokens[pos] is not None:
        raise ValueError("Unexpected token")
    return result
```

```python
def glob_match(pattern: str, name: str) -> bool:
    """Match all of name against a case-sensitive glob pattern."""
    n = len(name)
    dp = [False] * (n + 1)
    dp[0] = True
    i = 0

    while i < len(pattern):
        ch = pattern[i]
        i += 1
        kind = "literal"
        literal = ch
        intervals = []
        negated = False

        if ch == "\\":
            if i < len(pattern):
                literal = pattern[i]
                i += 1
        elif ch == "*":
            kind = "star"
            if i < len(pattern) and pattern[i] == "*":
                kind = "globstar"
                i += 1
        elif ch == "?":
            kind = "any"
        elif ch == "[":
            start = i
            if start < len(pattern) and pattern[start] in "!^":
                negated = True
                start += 1

            # A leading ']' is a member, not the closing delimiter.
            search_from = start
            if search_from < len(pattern) and pattern[search_from] == "]":
                search_from += 1
            end = pattern.find("]", search_from)

            if end != -1:
                kind = "set"
                body = pattern[start:end]
                k = 0
                while k < len(body):
                    first_literal_dash = k == 0 and body[k] == "-"
                    last_literal_dash = (
                        k + 2 == len(body) - 1 and body[k + 2] == "-"
                    )
                    if (
                        k + 2 < len(body)
                        and body[k + 1] == "-"
                        and not first_literal_dash
                        and not last_literal_dash
                    ):
                        intervals.append((ord(body[k]), ord(body[k + 2])))
                        k += 3
                    else:
                        code = ord(body[k])
                        intervals.append((code, code))
                        k += 1
                i = end + 1
            # Otherwise '[' is literal; resume immediately after it.

        next_dp = [False] * (n + 1)

        if kind in ("star", "globstar"):
            next_dp[0] = dp[0]
            for j, char in enumerate(name, 1):
                allowed = kind == "globstar" or char != "/"
                next_dp[j] = dp[j] or (allowed and next_dp[j - 1])
        else:
            for j, char in enumerate(name, 1):
                if not dp[j - 1]:
                    continue
                if kind == "literal":
                    matches = char == literal
                elif kind == "any":
                    matches = char != "/"
                else:
                    code = ord(char)
                    member = any(lo <= code <= hi for lo, hi in intervals)
                    matches = char != "/" and (member != negated)
                next_dp[j] = matches

        dp = next_dp

    return dp[n]
```

```python
from fractions import Fraction


def token_bucket(
    capacity: int,
    refill_per_sec: float,
    requests: list[tuple[float, int]],
) -> list[bool]:
    if capacity < 1:
        raise ValueError("capacity must be at least 1")
    if refill_per_sec < 0:
        raise ValueError("refill_per_sec must be non-negative")
    if not requests:
        return []

    rate = Fraction(refill_per_sec)
    tokens = Fraction(capacity)
    previous_time = None
    results: list[bool] = []

    for timestamp, cost in requests:
        if not isinstance(cost, int) or cost < 1:
            raise ValueError("cost must be an integer at least 1")

        current_time = Fraction(timestamp)
        if previous_time is not None:
            if current_time < previous_time:
                raise ValueError("timestamps must be non-decreasing")
            tokens = min(
                capacity,
                tokens + (current_time - previous_time) * rate,
            )

        allowed = tokens >= cost
        if allowed:
            tokens -= cost

        results.append(allowed)
        previous_time = current_time

    return results
```

```python
def resolve_pointer(doc, pointer: str):
    if pointer == "":
        return doc
    if not pointer.startswith("/"):
        raise ValueError("A non-empty JSON Pointer must start with '/'")

    value = doc
    for raw_token in pointer.split("/")[1:]:
        i = 0
        while i < len(raw_token):
            if raw_token[i] == "~":
                if i + 1 == len(raw_token) or raw_token[i + 1] not in "01":
                    raise ValueError(f"Invalid escape in token: {raw_token!r}")
                i += 2
            else:
                i += 1

        token = raw_token.replace("~1", "/").replace("~0", "~")

        if isinstance(value, dict):
            value = value[token]
        elif isinstance(value, list):
            if token == "-":
                raise KeyError(token)
            if (
                not token.isascii()
                or not token.isdecimal()
                or (len(token) > 1 and token[0] == "0")
            ):
                raise ValueError(f"Invalid list index: {token!r}")

            # Check the range before int(), including for arbitrarily long tokens.
            limit = str(len(value))
            if len(token) > len(limit) or (
                len(token) == len(limit) and token >= limit
            ):
                raise KeyError(token)

            value = value[int(token)]
        else:
            raise KeyError(token)

    return value
```

```python
from datetime import date, timedelta


def add_business_days(start: str, days: int, holidays: list[str]) -> str:
    def parse_date(value: str) -> date:
        try:
            parsed = date.fromisoformat(value)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Invalid date: {value!r}") from exc
        if parsed.isoformat() != value:
            raise ValueError(f"Date must use YYYY-MM-DD format: {value!r}")
        return parsed

    current = parse_date(start)
    holiday_dates = {parse_date(value) for value in holidays}

    def is_business_day(value: date) -> bool:
        return value.weekday() < 5 and value not in holiday_dates

    if days == 0:
        while not is_business_day(current):
            current += timedelta(days=1)
        return current.isoformat()

    step = timedelta(days=1 if days > 0 else -1)
    remaining = abs(days)

    while remaining:
        current += step
        if is_business_day(current):
            remaining -= 1

    return current.isoformat()
```

```python
def parse_csv_line(line: str, delimiter: str = ",") -> list[str]:
    if len(delimiter) != 1 or delimiter == '"':
        raise ValueError("Delimiter must be a single character other than '\"'")

    fields = []
    current_field = []
    in_quotes = False
    i = 0
    n = len(line)

    while i < n:
        if not in_quotes:
            if line[i] == '"':
                if current_field:
                    raise ValueError("Unquoted field contains '\"'")
                in_quotes = True
                i += 1
            elif line[i] == delimiter:
                fields.append(''.join(current_field))
                current_field = []
                i += 1
            else:
                current_field.append(line[i])
                i += 1
        else:
            if line[i] == '"':
                if i + 1 < n and line[i + 1] == '"':
                    current_field.append('"')
                    i += 2
                else:
                    in_quotes = False
                    i += 1
                    # Check what follows the closing quote
                    if i < n and line[i] != delimiter:
                        if line[i] != '':
                            raise ValueError("Closing quote must be followed by delimiter or end of line")
            else:
                current_field.append(line[i])
                i += 1

    # After loop ends
    if in_quotes:
        raise ValueError("Unterminated quoted field")

    fields.append(''.join(current_field))

    # Handle empty line case
    if not line and not fields:
        return [""]

    return fields
