```python
import re
from ipaddress import IPv4Address, IPv4Network, summarize_address_range


def cidr_subtract(base: str, remove: list[str]) -> list[str]:
    """Return the minimal, address-sorted CIDR cover of base minus remove."""
    syntax = re.compile(
        r"(?:0|[1-9][0-9]{0,2})"
        r"(?:\.(?:0|[1-9][0-9]{0,2})){3}/[0-9]+"
    )

    def parse(block: str) -> IPv4Network:
        if not isinstance(block, str) or syntax.fullmatch(block) is None:
            raise ValueError(f"Malformed IPv4 CIDR block: {block!r}")
        return IPv4Network(block, strict=True)

    network = parse(base)
    base_start = int(network.network_address)
    base_end = int(network.broadcast_address)

    # Validate every block, even if an earlier block removes all of base.
    intervals: list[tuple[int, int]] = []
    for block in remove:
        excluded = parse(block)
        start = max(base_start, int(excluded.network_address))
        end = min(base_end, int(excluded.broadcast_address))
        if start <= end:
            intervals.append((start, end))

    intervals.sort()
    result: list[str] = []

    def append_range(start: int, end: int) -> None:
        result.extend(
            str(block)
            for block in summarize_address_range(
                IPv4Address(start), IPv4Address(end)
            )
        )

    cursor = base_start
    for start, end in intervals:
        if start > cursor:
            append_range(cursor, start - 1)
        cursor = max(cursor, end + 1)
        if cursor > base_end:
            break

    if cursor <= base_end:
        append_range(cursor, base_end)

    return result
