import json

def resolve_pointer(doc, pointer: str):
    if not isinstance(pointer, str):
        raise ValueError("Pointer must be a string")

    if pointer == "":
        return doc

    if not pointer.startswith("/"):
        raise ValueError("Pointer must start with '/'")

    tokens = pointer.split("/")[1:]  # Skip the initial empty string from leading '/'

    current = doc
    for token in tokens:
        # Decode ~0 and ~1
        decoded_token = []
        i = 0
        n = len(token)
        while i < n:
            if token[i] == '~':
                if i + 1 >= n:
                    raise ValueError("Invalid escape sequence in pointer")
                if token[i+1] == '0':
                    decoded_token.append('~')
                    i += 2
                elif token[i+1] == '1':
                    decoded_token.append('/')
                    i += 2
                else:
                    raise ValueError("Invalid escape sequence in pointer")
            else:
                decoded_token.append(token[i])
                i += 1
        decoded_token = ''.join(decoded_token)

        if isinstance(current, dict):
            if decoded_token not in current:
                raise KeyError(f"Key '{decoded_token}' not found in dictionary")
            current = current[decoded_token]
        elif isinstance(current, list):
            if decoded_token == "-":
                raise KeyError("Index '-' refers to non-existent element after last list item")
            if not decoded_token.isdigit():
                raise ValueError(f"List index must be a non-negative integer, got '{decoded_token}'")
            if len(decoded_token) > 1 and decoded_token[0] == '0':
                raise ValueError(f"List index must not have leading zeros, got '{decoded_token}'")
            index = int(decoded_token)
            if index >= len(current):
                raise KeyError(f"List index {index} out of range")
            current = current[index]
        else:
            raise KeyError(f"Cannot index into {type(current).__name__} with token '{decoded_token}'")

    return current
