from fractions import Fraction


def evaluate(expr: str) -> Fraction:
    precedence = {
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "u+": 3, "u-": 3,
        "**": 4,
    }
    operators: list[str] = []
    postfix: list[int | str] = []
    expecting_operand = True
    i = 0

    # Validate the syntax and produce postfix notation before evaluating.
    while i < len(expr):
        ch = expr[i]

        if ch.isspace():
            i += 1
            continue

        if "0" <= ch <= "9":
            if not expecting_operand:
                raise ValueError("Two operands in a row")

            # Avoid the digit-count limit imposed on int(string).
            number = 0
            while i < len(expr) and "0" <= expr[i] <= "9":
                number = number * 10 + ord(expr[i]) - ord("0")
                i += 1

            postfix.append(number)
            expecting_operand = False
            continue

        if ch == "(":
            if not expecting_operand:
                raise ValueError("Missing operator before '('")
            operators.append(ch)
            i += 1
            continue

        if ch == ")":
            if expecting_operand:
                raise ValueError("Missing operand before ')'")

            while operators and operators[-1] != "(":
                postfix.append(operators.pop())

            if not operators:
                raise ValueError("Unmatched ')'")
            operators.pop()
            i += 1
            continue

        if ch not in "+-*/":
            raise ValueError(f"Unknown character: {ch!r}")

        if expr.startswith("**", i):
            op = "**"
            i += 2
        else:
            op = ch
            i += 1

        if expecting_operand:
            if op not in ("+", "-"):
                raise ValueError("Missing operand")

            # Prefix operators do not pop preceding operators. In particular,
            # this permits unary signs on the right-hand side of '**'.
            operators.append("u" + op)
            continue

        while operators and operators[-1] != "(":
            top = operators[-1]
            if precedence[top] < precedence[op]:
                break
            if precedence[top] == precedence[op] and op == "**":
                break
            postfix.append(operators.pop())

        operators.append(op)
        expecting_operand = True

    if expecting_operand:
        raise ValueError("Empty expression or missing operand")

    while operators:
        op = operators.pop()
        if op == "(":
            raise ValueError("Unmatched '('")
        postfix.append(op)

    values: list[Fraction] = []

    for token in postfix:
        if isinstance(token, int):
            values.append(Fraction(token))
        elif token == "u+":
            continue
        elif token == "u-":
            values[-1] = -values[-1]
        else:
            right = values.pop()
            left = values.pop()

            if token == "+":
                result = left + right
            elif token == "-":
                result = left - right
            elif token == "*":
                result = left * right
            elif token == "/":
                result = left / right
            else:  # **
                if right.denominator != 1:
                    raise ValueError("Exponent must be an integer")
                if left == 0 and right.numerator < 0:
                    raise ZeroDivisionError("Zero raised to a negative power")
                result = left ** right.numerator

            values.append(result)

    return values[0]
```

Here's the Python function `split_sql` that adheres to the specified rules:

```python
def split_sql(script: str) -> list[str]:
    statements = []
    current_statement = []
    i = 0
    n = len(script)
    in_single_quote = False
    in_double_quote = False
    in_line_comment = False
    in_block_comment = False
    escape_next = False

    while i < n:
        if not in_single_quote and not in_double_quote and not in_line_comment and not in_block_comment:
            if script.startswith('--', i):
                in_line_comment = True
                i += 2
                continue
            elif script.startswith('/*', i):
                in_block_comment = True
                i += 2
                current_statement.append(' ')
                continue
            elif script[i] == ';':
                stmt = ''.join(current_statement).strip()
                if stmt:
                    statements.append(stmt)
                current_statement = []
                i += 1
                continue

        if in_line_comment:
            if script[i] == '\n':
                in_line_comment = False
            i += 1
            continue

        if in_block_comment:
            if script.startswith('*/', i):
                in_block_comment = False
                i += 2
            else:
                i += 1
            continue

        if escape_next:
            escape_next = False
            current_statement.append(script[i])
            i += 1
            continue

        if in_single_quote:
            if script[i] == "'":
                if i + 1 < n and script[i+1] == "'":
                    current_statement.append("''")
                    i += 2
                else:
                    in_single_quote = False
                    current_statement.append("'")
                    i += 1
            else:
                current_statement.append(script[i])
                i += 1
        elif in_double_quote:
            if script[i] == '"':
                if i + 1 < n and script[i+1] == '"':
                    current_statement.append('""')
                    i += 2
                else:
                    in_double_quote = False
                    current_statement.append('"')
                    i += 1
            else:
                current_statement.append(script[i])
                i += 1
        else:
            if script[i] == "'":
                in_single_quote = True
                current_statement.append("'")
                i += 1
            elif script[i] == '"':
                in_double_quote = True
                current_statement.append('"')
                i += 1
            else:
                current_statement.append(script[i])
                i += 1

    if in_single_quote or in_double_quote:
        raise ValueError("Unterminated string or identifier")
    if in_block_comment:
        raise ValueError("Unterminated block comment")

    stmt = ''.join(current_statement).strip()
    if stmt:
        statements.append(stmt)

    return statements
```

This function processes the SQL script character by character, keeping track of whether it's inside quotes, line comments, or block comments. It handles escaped quotes within strings and identifiers, and properly splits statements at semicolons that are outside of these contexts. It raises a `ValueError` if it encounters an unterminated string, identifier, or block comment. The resulting statements are stripped of leading and trailing whitespace, and empty statements are omitted from the result.

```python
def merge_intervals(
    intervals: list[tuple[int, int, str]],
) -> list[tuple[int, int, list[str]]]:
    for start, end, _ in intervals:
        if start >= end:
            raise ValueError("Each interval must have start < end")

    if not intervals:
        return []

    ordered = sorted(intervals, key=lambda interval: interval[0])
    merged: list[tuple[int, int, list[str]]] = []

    current_start, current_end, label = ordered[0]
    labels = {label}

    for start, end, label in ordered[1:]:
        if start <= current_end:
            current_end = max(current_end, end)
            labels.add(label)
        else:
            merged.append((current_start, current_end, sorted(labels)))
            current_start, current_end = start, end
            labels = {label}

    merged.append((current_start, current_end, sorted(labels)))
    return merged
```

