import re
from functools import total_ordering

_VERSION_RE = re.compile(
    r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
    r'(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)'
    r'(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?'
    r'(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
)

_IDENT_RE = re.compile(r'^[0-9A-Za-z-]+$')

@total_ordering
class SemVer:
    __slots__ = ('major', 'minor', 'patch', 'prerelease')

    def __init__(self, major: int, minor: int, patch: int, prerelease: tuple[str, ...] | None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease  # None means no prerelease

    @classmethod
    def parse(cls, s: str) -> 'SemVer':
        m = _VERSION_RE.match(s)
        if not m:
            raise ValueError(f"malformed version: {s!r}")
        major = int(m.group(1))
        minor = int(m.group(2))
        patch = int(m.group(3))
        pre = m.group(4)
        # build = m.group(5)  # ignored
        if pre is None:
            prerelease = None
        else:
            parts = pre.split('.')
            for p in parts:
                if not _IDENT_RE.match(p):
                    raise ValueError(f"malformed prerelease identifier: {p!r}")
            prerelease = tuple(parts)
        return cls(major, minor, patch, prerelease)

    def _key(self):
        # For comparison: no prerelease > any prerelease
        if self.prerelease is None:
            pre_key = (1,)  # greater than any prerelease tuple
        else:
            pre_key = (0,) + tuple(
                (0, int(p)) if p.isdigit() else (1, p)
                for p in self.prerelease
            )
        return (self.major, self.minor, self.patch, pre_key)

    def __eq__(self, other):
        if not isinstance(other, SemVer):
            return NotImplemented
        return self._key() == other._key()

    def __lt__(self, other):
        if not isinstance(other, SemVer):
            return NotImplemented
        return self._key() < other._key()

    def __hash__(self):
        return hash(self._key())

    def __repr__(self):
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease is not None:
            s += "-" + ".".join(self.prerelease)
        return s


_OPS = ('>=', '<=', '>', '<', '=', '^', '~')

def _parse_comparator(comp: str) -> tuple[str, SemVer] | None:
    """Parse a single comparator. Returns (op, version) or None for '*'."""
    comp = comp.strip()
    if comp == '*':
        return None
    op = ''
    for candidate in _OPS:
        if comp.startswith(candidate):
            op = candidate
            rest = comp[len(candidate):]
            break
    else:
        # no operator means '='
        op = '='
        rest = comp
    rest = rest.strip()
    if not rest:
        raise ValueError(f"malformed comparator: {comp!r}")
    ver = SemVer.parse(rest)
    return (op, ver)


def _expand_caret(ver: SemVer) -> list[tuple[str, SemVer]]:
    x, y, z = ver.major, ver.minor, ver.patch
    lower = SemVer(x, y, z, ver.prerelease)
    if x > 0:
        upper = SemVer(x + 1, 0, 0, None)
    elif y > 0:
        upper = SemVer(0, y + 1, 0, None)
    else:
        upper = SemVer(0, 0, z + 1, None)
    return [('>=', lower), ('<', upper)]


def _expand_tilde(ver: SemVer) -> list[tuple[str, SemVer]]:
    x, y, z = ver.major, ver.minor, ver.patch
    lower = SemVer(x, y, z, ver.prerelease)
    upper = SemVer(x, y + 1, 0, None)
    return [('>=', lower), ('<', upper)]


def _satisfies_one(version: SemVer, op: str, target: SemVer) -> bool:
    if op == '=':
        return version == target
    if op == '>':
        return version > target
    if op == '>=':
        return version >= target
    if op == '<':
        return version < target
    if op == '<=':
        return version <= target
    raise ValueError(f"unknown operator: {op!r}")


