def merge_intervals(
    intervals: list[tuple[int, int, str]],
) -> list[tuple[int, int, list[str]]]:
    for start, end, _ in intervals:
        if start >= end:
            raise ValueError("Each interval must have start < end.")

    if not intervals:
        return []

    ordered = iter(sorted(intervals, key=lambda interval: interval[0]))
    current_start, current_end, label = next(ordered)
    labels = {label}
    merged: list[tuple[int, int, list[str]]] = []

    for start, end, label in ordered:
        if start <= current_end:
            current_end = max(current_end, end)
            labels.add(label)
        else:
            merged.append((current_start, current_end, sorted(labels)))
            current_start, current_end = start, end
            labels = {label}

    merged.append((current_start, current_end, sorted(labels)))
    return merged
