import re

_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?"
    r"(?:\+([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?",
    re.ASCII,
)
_COMPARATOR_RE = re.compile(r"(>=|<=|=|>|<|\^|~)?(.+)", re.ASCII)


def _numeric_key(digits: str) -> tuple[int, str]:
    # String-based numeric comparison avoids Python's integer-string size limit.
    normalized = digits.lstrip("0") or "0"
    return len(normalized), normalized


def _increment(digits: str) -> str:
    chars = list(digits)
    for i in range(len(chars) - 1, -1, -1):
        if chars[i] != "9":
            chars[i] = chr(ord(chars[i]) + 1)
            return "".join(chars)
        chars[i] = "0"
    return "1" + "".join(chars)


def _version_key(core: tuple[str, str, str], prerelease: str | None):
    core_key = tuple(_numeric_key(part) for part in core)
    if prerelease is None:
        return core_key + ((1,),)

    identifiers = tuple(
        (0, _numeric_key(part)) if part.isascii() and part.isdigit()
        else (1, part)
        for part in prerelease.split(".")
    )
    return core_key + ((0, identifiers),)


def _parse_version(text: str):
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"Malformed version: {text!r}")
    major, minor, patch, prerelease, _build = match.groups()
    core = (major, minor, patch)
    return core, _version_key(core, prerelease)


def satisfies(version: str, range_expr: str) -> bool:
    _, candidate = _parse_version(version)
    results = []

    # Validate every comparator, even if an earlier set already matches.
    for comparator_set in range_expr.split("||"):
        tokens = comparator_set.split()
        if not tokens:
            raise ValueError("Range contains an empty comparator set")

        set_matches = True
        for token in tokens:
            if token == "*":
                continue

            match = _COMPARATOR_RE.fullmatch(token)
            if match is None:
                raise ValueError(f"Malformed comparator: {token!r}")

            operator, operand = match.groups()
            operator = operator or "="
            core, target = _parse_version(operand)

            if operator == "=":
                matches = candidate == target
            elif operator == ">":
                matches = candidate > target
            elif operator == ">=":
                matches = candidate >= target
            elif operator == "<":
                matches = candidate < target
            elif operator == "<=":
                matches = candidate <= target
            else:
                major, minor, patch = core
                if operator == "~":
                    upper_core = (major, _increment(minor), "0")
                elif major != "0":
                    upper_core = (_increment(major), "0", "0")
                elif minor != "0":
                    upper_core = ("0", _increment(minor), "0")
                else:
                    upper_core = ("0", "0", _increment(patch))

                upper = _version_key(upper_core, None)
                matches = target <= candidate < upper

            set_matches = set_matches and matches

        results.append(set_matches)

    return any(results)
