    if not range_expr:
        raise ValueError("empty range expression")

    # Split into comparator sets
    comparator_sets = [s.strip() for s in range_expr.split('||')]
    if not all(comparator_sets):
        raise ValueError("empty comparator set")

    # Check if any comparator set is satisfied
    for comparator_set in comparator_sets:
        if _satisfies_comparator_set(v, comparator_set):
            return True
    return False

def _parse_version(version: str) -> Tuple[int, int, int, Optional[List[str]], Optional[List[str]]]:
    # Regex for semantic version
    pattern = r'^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
    match = re.fullmatch(pattern, version)
    if not match:
        raise ValueError(f"malformed version: {version}")

    major = int(match.group(1))
    minor = int(match.group(2))
    patch = int(match.group(3))
    prerelease = match.group(4).split('.') if match.group(4) else None
    build = match.group(5).split('.') if match.group(5) else None

    # Validate no leading zeros in numeric parts
    if (len(match.group(1)) > 1 and match.group(1)[0] == '0') or \
       (len(match.group(2)) > 1 and match.group(2)[0] == '0') or \
       (len(match.group(3)) > 1 and match.group(3)[0] == '0'):
        raise ValueError(f"malformed version: {version}")

    return (major, minor, patch, prerelease, build)

def _compare_versions(a: Tuple[int, int, int, Optional[List[str]], Optional[List[str]]],
                      b: Tuple[int, int, int, Optional[List[str]], Optional[List[str]]]) -> int:
    # Compare major, minor, patch
    if a[0] != b[0]:
        return a[0] - b[0]
    if a[1] != b[1]:
        return a[1] - b[1]
    if a[2] != b[2]:
        return a[2] - b[2]

    # Compare prerelease
    a_prerelease = a[3]
    b_prerelease = b[3]

    if a_prerelease is None and b_prerelease is None:
        return 0
    if a_prerelease is None:
        return 1
    if b_prerelease is None:
        return -1

    # Compare prerelease identifiers
    for i in range(min(len(a_prerelease), len(b_prerelease))):
        a_id = a_prerelease[i]
        b_id = b_prerelease[i]

        a_num = a_id.isdigit()
        b_num = b_id.isdigit()

        if a_num and b_num:
            a_val = int(a_id)
            b_val = int(b_id)
            if a_val != b_val:
                return a_val - b_val
        elif a_num:
            return -1
        elif b_num:
            return 1
        else:
            if a_id != b_id:
                return -1 if a_id < b_id else 1

    # Compare lengths
    return len(a_prerelease) - len(b_prerelease)

def _satisfies_comparator_set(version: Tuple[int, int, int, Optional[List[str]], Optional[List[str]]],
                              comparator_set: str) -> bool:
