def glob_match(pattern: str, name: str) -> bool:
    # After each pattern token, dp[j] indicates a match of name[:j].
    dp = bytearray(len(name) + 1)
    dp[0] = 1
    i = 0
    plen = len(pattern)
    last_close = pattern.rfind("]")

    while i < plen:
        char = pattern[i]
        i += 1

        if char == "*":
            crosses_slash = i < plen and pattern[i] == "*"
            while i < plen and pattern[i] == "*":
                i += 1

            for j, candidate in enumerate(name, 1):
                dp[j] = dp[j] or (
                    dp[j - 1] and (crosses_slash or candidate != "/")
                )
            continue

        if char == "?":
            for j in range(len(name), 0, -1):
                dp[j] = dp[j - 1] and name[j - 1] != "/"
            dp[0] = 0
            continue

        if char == "[":
            start = i
            negated = start < plen and pattern[start] in "!^"
            if negated:
                start += 1

            search_from = start
            if search_from < plen and pattern[search_from] == "]":
                search_from += 1

            # This guard also avoids repeated failed scans for unmatched '['.
            if search_from <= last_close:
                end = pattern.find("]", search_from)
                intervals = []
                k = start

                while k < end:
                    if k + 2 < end and pattern[k + 1] == "-":
                        intervals.append((pattern[k], pattern[k + 2]))
                        k += 3
                    else:
                        intervals.append((pattern[k], pattern[k]))
                        k += 1

                i = end + 1
                for j in range(len(name), 0, -1):
                    candidate = name[j - 1]
                    dp[j] = (
                        dp[j - 1]
                        and candidate != "/"
                        and (
                            any(
                                low <= candidate <= high
                                for low, high in intervals
                            )
                            != negated
                        )
                    )
                dp[0] = 0
                continue

            # An unmatched '[' is handled as an ordinary literal below.

        if char == "\\" and i < plen:
            char = pattern[i]
            i += 1

        for j in range(len(name), 0, -1):
            dp[j] = dp[j - 1] and name[j - 1] == char
        dp[0] = 0

    return bool(dp[len(name)])
