import re

def parse_duration(s: str) -> float:
    if not s:
        raise ValueError("Empty string")

    # Check for leading P and overall structure
    if not s.startswith('P'):
        raise ValueError("Missing leading P")
    if len(s) == 1:
        raise ValueError("P with no components")

    # Split into date and time parts
    if 'T' in s:
        date_part, time_part = s.split('T', 1)
        if not time_part:
            raise ValueError("T with nothing after it")
    else:
        date_part, time_part = s, ''

    # Validate date part
    if date_part != 'P':
        date_components = date_part[1:]  # Remove P
        if not date_components:
            raise ValueError("P with no components")

        # Check for valid date components in order: Y, M, W, D
        date_pattern = r'^(\d+(\.\d+|,\d+)?Y)?(\d+M)?(\d+W)?(\d+(\.\d+|,\d+)?D)?$'
        if not re.fullmatch(date_pattern, date_components):
            raise ValueError("Invalid date components")

        # Check that components are in order and no duplicates
        date_order = ['Y', 'M', 'W', 'D']
        last_index = -1
        for component in date_components:
            if not component[-1] in date_order:
                raise ValueError("Invalid date component")
            current_index = date_order.index(component[-1])
            if current_index <= last_index:
                raise ValueError("Date components out of order or repeated")
            last_index = current_index

        # Check fractional part only on last component
        if '.' in date_components or ',' in date_components:
            last_component = date_components.split('Y')[-1].split('M')[-1].split('W')[-1].split('D')[0]
            if not (last_component.startswith('.') or last_component.startswith(',')):
                raise ValueError("Fractional part only allowed on last component")

