import re
from bisect import bisect_right
from datetime import datetime, timedelta


def next_run(expr: str, after: str) -> str:
    def parse_field(field: str, low: int, high: int) -> set[int]:
        values = set()
        for item in field.split(","):
            match = re.fullmatch(
                r"(\*|[0-9]+(?:-[0-9]+)?)(?:/([0-9]+))?", item
            )
            if match is None:
                raise ValueError("Malformed cron field")

            base, step_text = match.groups()
            step = int(step_text) if step_text is not None else 1
            if step < 1:
                raise ValueError("Step must be positive")

            if base == "*":
                start, end = low, high
            elif "-" in base:
                start, end = map(int, base.split("-"))
            else:
                if step_text is not None:
                    raise ValueError("Steps on single numbers are invalid")
                start = end = int(base)

            if not low <= start <= end <= high:
                raise ValueError("Invalid range or out-of-range value")

            values.update(range(start, end + 1, step))
        return values

    if not isinstance(expr, str) or not isinstance(after, str):
        raise ValueError("expr and after must be strings")

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Expected exactly five cron fields")

    minutes, hours, month_days, months, week_days = (
        parse_field(field, low, high)
        for field, (low, high) in zip(
            fields, ((0, 59), (0, 23), (1, 31), (1, 12), (0, 6))
        )
    )
    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"

    if re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}", after) is None:
        raise ValueError("Invalid after format")
    try:
        start = datetime.strptime(after, "%Y-%m-%d %H:%M")
    except ValueError as exc:
        raise ValueError("Invalid after date or time") from exc

    # Use a calendar-year horizon, clamping February 29 to February 28.
    if start.year + 5 > 9999:
        limit = datetime(9999, 12, 31, 23, 59)
    else:
        try:
            limit = start.replace(year=start.year + 5)
        except ValueError:
            limit = start.replace(year=start.year + 5, day=28)

    times = sorted(hour * 60 + minute for hour in hours for minute in minutes)
    day = start.date()
    last_day = limit.date()

    while day <= last_day:
        if day.month in months:
            dom_match = day.day in month_days
            dow_match = (day.weekday() + 1) % 7 in week_days

            if dom_restricted and dow_restricted:
                day_match = dom_match or dow_match
            elif dom_restricted:
                day_match = dom_match
            elif dow_restricted:
                day_match = dow_match
            else:
                day_match = True

            if day_match:
                index = (
                    bisect_right(times, start.hour * 60 + start.minute)
                    if day == start.date()
                    else 0
                )
                if index < len(times):
                    hour, minute = divmod(times[index], 60)
                    candidate = datetime(day.year, day.month, day.day, hour, minute)
                    if candidate <= limit:
                        return (
                            f"{candidate.year:04d}-{candidate.month:02d}-"
                            f"{candidate.day:02d} {hour:02d}:{minute:02d}"
                        )

        if day == last_day:
            break
        day += timedelta(days=1)

    raise ValueError("No matching time within five years")
