            step_match = re.fullmatch(r'(\*|(\d+)(?:-(\d+))?)/(\d+)', item)
            if step_match:
                start, a, b, step = step_match.groups()
                step = int(step)
                if step < 1:
                    raise ValueError(f"Step must be >= 1 in {field_name} field")

                if start == '*':
                    a_val = min_val
                    b_val = max_val
