                    a_val = int(a)
                    if b is not None:
                        b_val = int(b)
                    else:
                        b_val = a_val

                    if a_val < min_val or a_val > max_val or b_val < min_val or b_val > max_val:
                        raise ValueError(f"Value out of range in {field_name} field")
                    if a_val > b_val:
                        raise ValueError(f"Descending range in {field_name} field")

                for val in range(a_val, b_val + 1, step):
                    values.add(val)
