            if range_match:
                a, b = map(int, range_match.groups())
                if a < min_val or a > max_val or b < min_val or b > max_val:
                    raise ValueError(f"Value out of range in {field_name} field")
                if a > b:
                    raise ValueError(f"Descending range in {field_name} field")
                values.update(range(a, b + 1))
