def _split_runs(s: str) -> list[tuple[bool, str]]:
    runs = []
    i = 0
    n = len(s)
    while i < n:
        if '0' <= s[i] <= '9':
            j = i + 1
            while j < n and '0' <= s[j] <= '9':
                j += 1
            runs.append((True, s[i:j]))
            i = j
        else:
            j = i + 1
            while j < n and not ('0' <= s[j] <= '9'):
                j += 1
            runs.append((False, s[i:j]))
            i = j
    return runs


def _run_key(run: tuple[bool, str]) -> tuple:
    is_digit, text = run
    if is_digit:
        return (0, int(text), len(text))
    return (1, text.lower())


def _natural_key(s: str) -> tuple:
    return (tuple(_run_key(run) for run in _split_runs(s)), s)


def natural_sort(items: list[str]) -> list[str]:
    return sorted(items, key=_natural_key)
