```python
import re

type _Version = tuple[int, int, int, tuple[int | str, ...] | None]

_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?"
    r"(?:\+[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*)?"
)


def _decimal(text: str) -> int:
    # Avoid Python's limit on converting very long decimal strings.
    value = 0
    for start in range(0, len(text), 9):
        chunk = text[start:start + 9]
        value = value * (10 ** len(chunk)) + int(chunk)
    return value


def _parse_version(text: str) -> _Version:
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"Malformed version: {text!r}")

    prerelease = match.group(4)
    identifiers = (
        None
        if prerelease is None
        else tuple(
            _decimal(part) if part.isdigit() else part
            for part in prerelease.split(".")
        )
    )
    return (
        _decimal(match.group(1)),
        _decimal(match.group(2)),
        _decimal(match.group(3)),
        identifiers,
    )


def _compare(left: _Version, right: _Version) -> int:
    left_core, right_core = left[:3], right[:3]
    if left_core != right_core:
        return (left_core > right_core) - (left_core < right_core)

    left_pre, right_pre = left[3], right[3]
    if left_pre is None:
        return 0 if right_pre is None else 1
    if right_pre is None:
        return -1

    for left_id, right_id in zip(left_pre, right_pre):
        left_numeric = isinstance(left_id, int)
        right_numeric = isinstance(right_id, int)

        if left_numeric != right_numeric:
            return -1 if left_numeric else 1
        if left_id != right_id:
            return (left_id > right_id) - (left_id < right_id)

    return (len(left_pre) > len(right_pre)) - (
        len(left_pre) < len(right_pre)
    )


def satisfies(version: str, range_expr: str) -> bool:
    """Return whether version satisfies range_expr; reject malformed input."""
    parsed_version = _parse_version(version)
    comparator_sets: list[list[tuple[str, _Version]]] = []

    # Validate the entire range before evaluating any comparator set.
    for set_expr in range_expr.split("||"):
        tokens = set_expr.split()
        if not tokens:
            raise ValueError("Range contains an empty comparator set")

        comparators: list[tuple[str, _Version]] = []
        for token in tokens:
            if token == "*":
                continue

            operator = "="
            operand = token
            for candidate in (">=", "<=", "=", ">", "<", "^", "~"):
                if token.startswith(candidate):
                    operator = candidate
                    operand = token[len(candidate):]
                    break

            bound = _parse_version(operand)

            if operator in ("^", "~"):
                major, minor, patch, _ = bound
                if operator == "~":
                    upper: _Version = (major, minor + 1, 0, None)
                elif major > 0:
                    upper = (major + 1, 0, 0, None)
                elif minor > 0:
                    upper = (0, minor + 1, 0, None)
                else:
                    upper = (0, 0, patch + 1, None)

                comparators.extend(((">=", bound), ("<", upper)))
            else:
                comparators.append((operator, bound))

        comparator_sets.append(comparators)

    for comparators in comparator_sets:
        for operator, bound in comparators:
            comparison = _compare(parsed_version, bound)
            if not {
                "=": comparison == 0,
                ">": comparison > 0,
                ">=": comparison >= 0,
                "<": comparison < 0,
                "<=": comparison <= 0,
            }[operator]:
                break
        else:
            return True

    return False
```

