import re
from bisect import bisect_right
from calendar import monthrange
from datetime import date, datetime


def _cron_field(text: str, low: int, high: int) -> set[int]:
    values = set()

    for item in text.split(","):
        match = re.fullmatch(r"(\*|[0-9]+(?:-[0-9]+)?)(?:/([0-9]+))?", item)
        if match is None:
            raise ValueError(f"Invalid cron item: {item!r}")

        base, step_text = match.groups()

        if base == "*":
            start, end = low, high
        elif "-" in base:
            left, right = base.split("-")
            start = int(left.lstrip("0") or "0")
            end = int(right.lstrip("0") or "0")
        else:
            if step_text is not None:
                raise ValueError("Steps on single numbers are not allowed")
            start = end = int(base.lstrip("0") or "0")

        if not low <= start <= end <= high:
            raise ValueError(f"Invalid cron range: {base!r}")

        step = 1
        if step_text is not None:
            digits = step_text.lstrip("0")
            if not digits:
                raise ValueError("Cron steps must be positive")

            # Larger steps all select only the range's first value.
            width = high - low + 1
            step = int(digits) if len(digits) <= len(str(width)) else width

        values.update(range(start, end + 1, step))

    return values


def next_run(expr: str, after: str) -> str:
    if not isinstance(expr, str):
        raise ValueError("Cron expression must be a string")

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Cron expression must contain exactly five fields")

    minutes, hours, month_days, months, weekdays = [
        _cron_field(field, low, high)
        for field, (low, high) in zip(
            fields, ((0, 59), (0, 23), (1, 31), (1, 12), (0, 6))
        )
    ]

    if not isinstance(after, str) or re.fullmatch(
        r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}", after
    ) is None:
        raise ValueError("after must have format YYYY-MM-DD HH:MM")

    start = datetime(
        int(after[0:4]),
        int(after[5:7]),
        int(after[8:10]),
        int(after[11:13]),
        int(after[14:16]),
    )

    # Five calendar years, inclusive; February 29 clips to February 28.
    if start.year + 5 <= 9999:
        end_year = start.year + 5
        deadline = start.replace(
            year=end_year,
            day=min(start.day, monthrange(end_year, start.month)[1]),
        )
    else:
        deadline = datetime(9999, 12, 31, 23, 59)

    times = sorted(hour * 60 + minute for hour in hours for minute in minutes)
    start_minute = start.hour * 60 + start.minute
    first_day = start.date().toordinal()
    last_day = deadline.date().toordinal()

    dom_unrestricted = fields[2] == "*"
    dow_unrestricted = fields[4] == "*"

    for ordinal in range(first_day, last_day + 1):
        day = date.fromordinal(ordinal)
        if day.month not in months:
            continue

        dom_matches = day.day in month_days
        dow_matches = (day.weekday() + 1) % 7 in weekdays

        if dom_unrestricted:
            day_matches = dow_unrestricted or dow_matches
        elif dow_unrestricted:
            day_matches = dom_matches
        else:
            day_matches = dom_matches or dow_matches

        if not day_matches:
            continue

        index = bisect_right(times, start_minute) if ordinal == first_day else 0
        if index == len(times):
            continue

        hour, minute = divmod(times[index], 60)
        candidate = datetime(day.year, day.month, day.day, hour, minute)

        if candidate > deadline:
            break

        return (
            f"{day.year:04d}-{day.month:02d}-{day.day:02d} "
            f"{hour:02d}:{minute:02d}"
        )

    raise ValueError("No matching time within five years after after")
