from fractions import Fraction


class _Scanner:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.n = len(text)

    def next_token(self):
        while self.pos < self.n and self.text[self.pos].isspace():
            self.pos += 1

        if self.pos >= self.n:
            return ('EOF', None)

        c = self.text[self.pos]

        if '0' <= c <= '9':
            start = self.pos
            while self.pos < self.n and '0' <= self.text[self.pos] <= '9':
                self.pos += 1
            return ('NUM', int(self.text[start:self.pos]))

        if c == '+':
            self.pos += 1
            return ('PLUS', None)
        if c == '-':
            self.pos += 1
            return ('MINUS', None)
        if c == '*':
            if self.pos + 1 < self.n and self.text[self.pos + 1] == '*':
                self.pos += 2
                return ('POWER', None)
            self.pos += 1
            return ('STAR', None)
        if c == '/':
            self.pos += 1
            return ('SLASH', None)
        if c == '(':
            self.pos += 1
            return ('LPAREN', None)
        if c == ')':
            self.pos += 1
            return ('RPAREN', None)

        raise ValueError(f"unknown character: {c!r}")


class _Parser:
    def __init__(self, text: str):
        self.scanner = _Scanner(text)
        self.current = self.scanner.next_token()

    def eat(self, kind: str):
        if self.current[0] != kind:
            raise ValueError(f"expected {kind}, got {self.current[0]}")
        self.current = self.scanner.next_token()

    def parse(self) -> Fraction:
        if self.current[0] == 'EOF':
            raise ValueError("empty expression")

        result = self.parse_expr()

        if self.current[0] != 'EOF':
            raise ValueError("unexpected token")

        return result

    def parse_expr(self) -> Fraction:
        node = self.parse_term()

        while self.current[0] in ('PLUS', 'MINUS'):
            op = self.current[0]
            self.eat(op)
            right = self.parse_term()

            if op == 'PLUS':
                node = node + right
            else:
                node = node - right

        return node

    def parse_term(self) -> Fraction:
        node = self.parse_factor()

        while self.current[0] in ('STAR', 'SLASH'):
            op = self.current[0]
            self.eat(op)
            right = self.parse_factor()

            if op == 'STAR':
                node = node * right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                node = node / right

        return node

    def parse_factor(self) -> Fraction:
        sign = 1

        while self.current[0] in ('PLUS', 'MINUS'):
            if self.current[0] == 'MINUS':
                sign = -sign
            self.eat(self.current[0])

        result = self.parse_power()
        return result if sign == 1 else -result

    def parse_power(self) -> Fraction:
        base = self.parse_primary()

        if self.current[0] == 'POWER':
            self.eat('POWER')
            exponent = self.parse_factor()

            if exponent.denominator != 1:
                raise ValueError("non-integer exponent")

            exp_int = exponent.numerator

            if base == 0 and exp_int < 0:
                raise ZeroDivisionError("0 cannot be raised to a negative power")

            return base ** exp_int

        return base

    def parse_primary(self) -> Fraction:
        if self.current[0] == 'NUM':
            val = self.current[1]
            self.eat('NUM')
            return Fraction(val, 1)

        if self.current[0] == 'LPAREN':
            self.eat('LPAREN')
            result = self.parse_expr()
            self.eat('RPAREN')
            return result

        raise ValueError("missing operand")


def evaluate(expr: str) -> Fraction:
    return _Parser(expr).parse()
```

```python
import re
from typing import Optional, Tuple

_VERSION_RE = re.compile(
    r'^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)'
    r'(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?'
    r'(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?\Z'
)

class _Version:
    __slots__ = ('major', 'minor', 'patch', 'prerelease')

    def __init__(self, major: int, minor: int, patch: int, prerelease: Optional[Tuple[str, ...]]):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease

def _parse_version(s: str) -> _Version:
    m = _VERSION_RE.fullmatch(s)
    if not m:
        raise ValueError(f"invalid version: {s!r}")

    major = int(m.group(1))
    minor = int(m.group(2))
    patch = int(m.group(3))
    pre = m.group(4)
    prerelease = tuple(pre.split('.')) if pre is not None else None

    return _Version(major, minor, patch, prerelease)

def _is_numeric_ident(ident: str) -> bool:
    return all('0' <= ch <= '9' for ch in ident)

def _compare(a: _Version, b: _Version) -> int:
    if a.major != b.major:
        return -1 if a.major < b.major else 1
    if a.minor != b.minor:
        return -1 if a.minor < b.minor else 1
    if a.patch != b.patch:
        return -1 if a.patch < b.patch else 1

    a_pre = a.prerelease
    b_pre = b.prerelease

    if a_pre is None and b_pre is None:
        return 0
    if a_pre is None:
        return 1
    if b_pre is None:
        return -1

    for x, y in zip(a_pre, b_pre):
        x_num = _is_numeric_ident(x)
        y_num = _is_numeric_ident(y)

        if x_num and y_num:
            xi = int(x)
            yi = int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif x_num != y_num:
            return -1 if x_num else 1
        else:
            if x != y:
                return -1 if x < y else 1

    if len(a_pre) != len(b_pre):
        return -1 if len(a_pre) < len(b_pre) else 1

    return 0

def _parse_comparator(token: str):
    if token == '*':
        return ('*', None)

    if token.startswith('>='):
        op = '>='; rest = token[2:]
    elif token.startswith('<='):
        op = '<='; rest = token[2:]
    elif token.startswith('='):
        op = '='; rest = token[1:]
    elif token.startswith('>'):
        op = '>'; rest = token[1:]
    elif token.startswith('<'):
        op = '<'; rest = token[1:]
    elif token.startswith('^'):
        op = '^'; rest = token[1:]
    elif token.startswith('~'):
        op = '~'; rest = token[1:]
    else:
        op = '='; rest = token

    return (op, _parse_version(rest))

def _caret_upper(v: _Version) -> _Version:
    if v.major > 0:
        return _Version(v.major + 1, 0, 0, None)
    if v.minor > 0:
        return _Version(0, v.minor + 1, 0, None)
    return _Version(0, 0, v.patch + 1, None)

def _parse_range(range_expr: str):
    if not isinstance(range_expr, str) or range_expr.strip() == '':
        raise ValueError("empty range")

    sets = []
    for set_str in range_expr.split('||'):
        set_str = set_str.strip()
        if set_str == '':
            raise ValueError("empty comparator set")

        comps = []
        for token in set_str.split():
            comps.append(_parse_comparator(token))
        sets.append(comps)

    return sets

def satisfies(version: str, range_expr: str) -> bool:
    ver = _parse_version(version)
    sets = _parse_range(range_expr)

    for comps in sets:
        ok = True

        for op, ref in comps:
            if op == '*':
                continue

            cmp = _compare(ver, ref)

            if op == '=':
                if cmp != 0:
                    ok = False
                    break
            elif op == '>':
                if cmp <= 0:
                    ok = False
                    break
            elif op == '>=':
                if cmp < 0:
                    ok = False
                    break
            elif op == '<':
                if cmp >= 0:
                    ok = False

