import heapq


def topo_order(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    node_set = set(nodes)
    if len(node_set) != len(nodes):
        raise ValueError("nodes contains duplicates")

    adjacency: dict[str, set[str]] = {node: set() for node in nodes}
    indegree = {node: 0 for node in nodes}

    for a, b in edges:
        if a not in node_set or b not in node_set:
            raise ValueError("edge mentions a node not in nodes")
        if b not in adjacency[a]:
            adjacency[a].add(b)
            indegree[b] += 1

    available = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(available)
    order: list[str] = []

    while available:
        node = heapq.heappop(available)
        order.append(node)
        for successor in adjacency[node]:
            indegree[successor] -= 1
            if indegree[successor] == 0:
                heapq.heappush(available, successor)

    if len(order) != len(nodes):
        raise ValueError("edges contain a cycle")

    return order
```

```python
import heapq

def topo_order(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    # Check for duplicate nodes
    if len(nodes) != len(set(nodes)):
        raise ValueError("nodes contains duplicates")

    node_set = set(nodes)

    # Build adjacency list and in-degree count
    adj: dict[str, list[str]] = {node: [] for node in nodes}
    in_degree: dict[str, int] = {node: 0 for node in nodes}

    # Track unique edges to handle repeated edges
    seen_edges: set[tuple[str, str]] = set()

    for a, b in edges:
        # Validate edge nodes
        if a not in node_set or b not in node_set:
            raise ValueError(f"edge ({a}, {b}) mentions a node not in nodes")

        # Self-loop is a cycle
        if a == b:
            raise ValueError("cycle detected (self-loop)")

        # Skip repeated edges
        if (a, b) in seen_edges:
            continue
        seen_edges.add((a, b))

        adj[a].append(b)
        in_degree[b] += 1

    # Kahn's algorithm with min-heap for lexicographically smallest order
    heap: list[str] = []
    for node in nodes:
        if in_degree[node] == 0:
            heapq.heappush(heap, node)

    result: list[str] = []

    while heap:
        current = heapq.heappop(heap)
        result.append(current)

        for neighbor in adj[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    # Check for cycle
    if len(result) != len(nodes):
        raise ValueError("cycle detected")

    return result
```

```python
def split_sql(script: str) -> list[str]:
    statements: list[str] = []
    buffer: list[str] = []
    i = 0
    n = len(script)

    while i < n:
        char = script[i]

        if char in ("'", '"'):
            quote = char
            start = i
            i += 1

            while i < n:
                if script[i] == quote:
                    if i + 1 < n and script[i + 1] == quote:
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    i += 1
            else:
                kind = "string" if quote == "'" else "identifier"
                raise ValueError(f"Unterminated {kind}")

            buffer.append(script[start:i])

        elif script.startswith("--", i):
            newline = script.find("\n", i + 2)
            i = n if newline == -1 else newline

        elif script.startswith("/*", i):
            end = script.find("*/", i + 2)
            if end == -1:
                raise ValueError("Unterminated block comment")
            buffer.append(" ")
            i = end + 2

        elif char == ";":
            statement = "".join(buffer).strip()
            if statement:
                statements.append(statement)
            buffer.clear()
            i += 1

        else:
            buffer.append(char)
            i += 1

    statement = "".join(buffer).strip()
    if statement:
        statements.append(statement)

    return statements
```

