def wrap_text(text: str, width: int) -> list[str]:
    if width < 1:
        raise ValueError("width must be at least 1")

    lines: list[str] = []
    current = ""

    for word in text.split():
        if len(word) > width:
            if current:
                lines.append(current)
                current = ""

            # Keep the last piece as the current line, even if it is full.
            last_start = ((len(word) - 1) // width) * width
            for start in range(0, last_start, width):
                lines.append(word[start:start + width])
            current = word[last_start:]
        elif not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word

    if current:
        lines.append(current)

    return lines
```

```python
import re
from functools import cmp_to_key

def natural_sort(items: list[str]) -> list[str]:
    """
    Return a new list with the strings sorted in "natural" order.
    The input list is not modified.
    """
    # Split a string into maximal runs of digits and non-digits.
    # Each run is represented as a tuple: (is_digit, value)
    #   - For digit runs: (True, int_value, original_length)
    #   - For non-digit runs: (False, lowercased_string)
    _run_re = re.compile(r'(\d+|\D+)')

    def split_runs(s: str) -> list[tuple]:
        runs = []
        for match in _run_re.finditer(s):
            token = match.group(0)
            if token[0].isdigit():
                # Digit run: store numeric value and original length (for tie-breaking)
                runs.append((True, int(token), len(token)))
            else:
                # Non-digit run: store lowercased form for case-insensitive comparison
                runs.append((False, token.lower()))
        return runs

    def compare(a: str, b: str) -> int:
        runs_a = split_runs(a)
        runs_b = split_runs(b)

        for ra, rb in zip(runs_a, runs_b):
            # Digit run comes before non-digit run
            if ra[0] != rb[0]:
                return -1 if ra[0] else 1

            if ra[0]:  # Both are digit runs
                # Compare by numeric value
                if ra[1] != rb[1]:
                    return -1 if ra[1] < rb[1] else 1
                # Numeric values equal: shorter run (fewer leading zeros) comes first
                if ra[2] != rb[2]:
                    return -1 if ra[2] < rb[2] else 1
            else:  # Both are non-digit runs
                if ra[1] != rb[1]:
                    return -1 if ra[1] < rb[1] else 1

        # All compared runs are equal; fewer runs comes first
        if len(runs_a) != len(runs_b):
            return -1 if len(runs_a) < len(runs_b) else 1

        # Still tied: fall back to plain Python string comparison
        if a < b:
            return -1
        elif a > b:
            return 1
        else:
            return 0

    return sorted(items, key=cmp_to_key(compare))
```

