import re


def first_common_slot(
    busy: list[list[tuple[str, str]]],
    day_start: str,
    day_end: str,
    duration_min: int,
) -> str | None:
    def to_minutes(value: str) -> int:
        if not isinstance(value, str) or re.fullmatch(
            r"(?:[01][0-9]|2[0-3]):[0-5][0-9]", value
        ) is None:
            raise ValueError(f"Malformed time: {value!r}")
        return int(value[:2]) * 60 + int(value[3:])

    start = to_minutes(day_start)
    end = to_minutes(day_end)
    if end <= start:
        raise ValueError("day_end must be after day_start")
    if duration_min < 1:
        raise ValueError("duration_min must be at least 1")

    intervals: list[tuple[int, int]] = []
    for person in busy:
        for busy_start, busy_end in person:
            left = to_minutes(busy_start)
            right = to_minutes(busy_end)
            if right <= left:
                raise ValueError("Busy interval end must be after its start")
            left = max(left, start)
            right = min(right, end)
            if left < right:
                intervals.append((left, right))

    intervals.sort()
    candidate = start

    for left, right in intervals:
        if left - candidate >= duration_min:
            return f"{candidate // 60:02d}:{candidate % 60:02d}"
        candidate = max(candidate, right)

    if end - candidate >= duration_min:
        return f"{candidate // 60:02d}:{candidate % 60:02d}"
    return None
```

