```python
def split_sql(script: str) -> list[str]:
    statements = []
    current_statement = []
    i = 0
    n = len(script)
    in_single_quote = False
    in_double_quote = False
    in_line_comment = False
    in_block_comment = False
    escape_next = False

    while i < n:
        if not in_single_quote and not in_double_quote and not in_line_comment and not in_block_comment:
            if script.startswith('--', i):
                in_line_comment = True
                i += 2
                continue
            elif script.startswith('/*', i):
                in_block_comment = True
                i += 2
                continue
            elif script[i] == ';':
                stmt = ''.join(current_statement).strip()
                if stmt:
                    statements.append(stmt)
                current_statement = []
                i += 1
                continue
            elif script[i] in ' \t\n\r':
                # Replace any whitespace with a single space, but only if not in a comment
                if current_statement and current_statement[-1] != ' ':
                    current_statement.append(' ')
                i += 1
                continue

        if in_line_comment:
            if script[i] == '\n':
                in_line_comment = False
            i += 1
            continue

        if in_block_comment:
            if script.startswith('*/', i):
                in_block_comment = False
                current_statement.append(' ')  # Replace block comment with a space
                i += 2
            else:
                i += 1
            continue

        if escape_next:
            current_statement.append(script[i])
            escape_next = False
            i += 1
            continue

        if in_single_quote:
            if script[i] == "'":
                if i + 1 < n and script[i+1] == "'":
                    current_statement.append("''")
                    i += 2
                else:
                    current_statement.append("'")
                    in_single_quote = False
                    i += 1
            else:
                current_statement.append(script[i])
                i += 1
            continue

        if in_double_quote:
            if script[i] == '"':
                if i + 1 < n and script[i+1] == '"':
                    current_statement.append('""')
                    i += 2
                else:
                    current_statement.append('"')
                    in_double_quote = False
                    i += 1
            else:
                current_statement.append(script[i])
                i += 1
            continue

        if script[i] == "'":
            in_single_quote = True
            current_statement.append("'")
            i += 1
        elif script[i] == '"':
            in_double_quote = True
            current_statement.append('"')
            i += 1
        else:
            current_statement.append(script[i])
            i += 1

    # Check for unterminated strings or block comments
    if in_single_quote or in_double_quote:
        raise ValueError("Unterminated string or identifier")
    if in_block_comment:
        raise ValueError("Unterminated block comment")

    # Add the last statement if it's not empty
    if current_statement:
        stmt = ''.join(current_statement).strip()
        if stmt:
            statements.append(stmt)

    return statements
```

This function processes the SQL script character by character, keeping track of whether it's inside quotes, line comments, or block comments. It handles escaped quotes within strings and identifiers, and properly splits statements at semicolons that are outside of quotes and comments. It also checks for and raises errors for unterminated strings, identifiers, or block comments.

