```python
import re
from datetime import datetime, timedelta

_TIME_RE = re.compile(r'^([01]\d|2[0-3]):([0-5]\d)$')

def _parse_time(t: str) -> int:
    """Parse HH:MM into minutes since midnight, raising ValueError if malformed."""
    if not isinstance(t, str):
        raise ValueError(f"malformed time: {t!r}")
    m = _TIME_RE.match(t)
    if not m:
        raise ValueError(f"malformed time: {t!r}")
    return int(m.group(1)) * 60 + int(m.group(2))

def _fmt_time(minutes: int) -> str:
    """Format minutes since midnight as HH:MM."""
    h, m = divmod(minutes, 60)
    return f"{h:02d}:{m:02d}"

def first_common_slot(busy: list[list[tuple[str, str]]], day_start: str, day_end: str, duration_min: int) -> str | None:
    # Validate duration
    if not isinstance(duration_min, int) or isinstance(duration_min, bool) or duration_min < 1:
        raise ValueError(f"duration_min must be a positive integer, got {duration_min!r}")

    # Parse and validate day boundaries
    ds = _parse_time(day_start)
    de = _parse_time(day_end)
    if de <= ds:
        raise ValueError(f"day_end must be after day_start: {day_start!r} .. {day_end!r}")

    # Collect and validate busy intervals, clipping to the working day
    clipped: list[tuple[int, int]] = []
    for person in busy:
        if not isinstance(person, list):
            raise ValueError(f"each person's busy list must be a list, got {type(person).__name__}")
        for interval in person:
            if not isinstance(interval, tuple) or len(interval) != 2:
                raise ValueError(f"busy interval must be a (start, end) tuple, got {interval!r}")
            s_str, e_str = interval
            s = _parse_time(s_str)
            e = _parse_time(e_str)
            if e <= s:
                raise ValueError(f"busy interval end must be after start: {s_str!r} .. {e_str!r}")
            # Clip to [day_start, day_end)
            cs = max(s, ds)
            ce = min(e, de)
            if cs < ce:
                clipped.append((cs, ce))

    # Merge overlapping/adjacent intervals
    clipped.sort()
    merged: list[tuple[int, int]] = []
    for s, e in clipped:
        if merged and s <= merged[-1][1]:
            if e > merged[-1][1]:
                merged[-1] = (merged[-1][0], e)
        else:
            merged.append((s, e))

    # Find earliest free slot of duration_min
    cursor = ds
    for s, e in merged:
        if s - cursor >= duration_min:
            return _fmt_time(cursor)
        if e > cursor:
            cursor = e
        if cursor >= de:
            break

    if de - cursor >= duration_min:
        return _fmt_time(cursor)

    return None
```

