import re
from typing import Optional

def negotiate_language(header: str, available: list[str]) -> Optional[str]:
    # Parse the Accept-Language header
    entries = []
    if not header or header.isspace():
        return None

    # Split into entries, ignoring empty ones
    raw_entries = [e.strip() for e in header.split(',') if e.strip()]
    for entry in raw_entries:
        # Split into language range and parameters
        parts = [p.strip() for p in re.split(r';(?![^"]*"(?:(?:[^"]*"){2})*[^"]*$)', entry)]
        lang_range = parts[0]
        q = 1.0
        for param in parts[1:]:
            if param.lower().startswith('q='):
                q_str = param[2:].strip()
                try:
                    q = float(q_str)
                except ValueError:
                    raise ValueError(f"Invalid q value: {q_str}")
                if not (0 <= q <= 1) or len(q_str.split('.')[1]) > 3 if '.' in q_str else False:
                    raise ValueError(f"Invalid q value: {q_str}")
            else:
                raise ValueError(f"Unsupported parameter: {param}")

        # Validate language range
        if lang_range == '*':
            pass
        else:
            if not re.fullmatch(r'^[a-zA-Z]{1,8}(?:-[a-zA-Z0-9]{1,8})*$', lang_range):
                raise ValueError(f"Invalid language range: {lang_range}")
        entries.append((lang_range.lower(), q))

    # Process available languages
    candidates = []
    for tag in available:
        tag_lower = tag.lower()
        best_q = 0.0
        best_entry_index = -1
        for entry_index, (lang_range, q) in enumerate(entries):
            if q == 0:
                continue
            if lang_range == '*':
                if q > best_q or (q == best_q and entry_index < best_entry_index):
                    best_q = q
                    best_entry_index = entry_index
            else:
                # Check if lang_range matches tag_lower
                if (tag_lower == lang_range or
                    tag_lower.startswith(lang_range + '-')):
                    # More specific (longer) range wins
                    if len(lang_range) > len(entries[best_entry_index][0]) if best_entry_index != -1 else True:
                        best_q = q
                        best_entry_index = entry_index
                    elif len(lang_range) == len(entries[best_entry_index][0]) if best_entry_index != -1 else False:
                        if q > best_q or (q == best_q and entry_index < best_entry_index):
                            best_q = q
                            best_entry_index = entry_index
        if best_q > 0:
            candidates.append((best_q, best_entry_index, tag))

    if not candidates:
        return None

    # Sort candidates: highest q first, then earliest entry in header, then earliest in available
    candidates.sort(key=lambda x: (-x[0], x[1], available.index(x[2])))
    return candidates[0][2]
```

