def first_common_slot(busy: list[list[tuple[str, str]]], day_start: str, day_end: str, duration_min: int) -> str | None:
    from itertools import chain

    def parse_time(time_str: str) -> int:
        try:
            hh, mm = map(int, time_str.split(':'))
            if not (0 <= hh <= 23 and 0 <= mm <= 59):
                raise ValueError
            return hh * 60 + mm
        except (ValueError, AttributeError):
            raise ValueError(f"Invalid time format: {time_str}")

    def format_time(total_min: int) -> str:
        hh = total_min // 60
        mm = total_min % 60
        return f"{hh:02d}:{mm:02d}"

    # Validate inputs
    if duration_min < 1:
        raise ValueError("Duration must be at least 1 minute")

    start_min = parse_time(day_start)
    end_min = parse_time(day_end)
    if end_min <= start_min:
        raise ValueError("Day end must be after day start")

    # Collect and validate all busy intervals
    all_busy = []
    for person in busy:
        for interval in person:
            if len(interval) != 2:
                raise ValueError("Each busy interval must be a tuple of (start, end)")
            s, e = interval
            s_min = parse_time(s)
            e_min = parse_time(e)
            if e_min <= s_min:
                raise ValueError(f"Busy interval end must be after start: {interval}")
            all_busy.append((s_min, e_min))

    # Merge overlapping or adjacent intervals
    if not all_busy:
        merged = []
    else:
        all_busy.sort()
        merged = [all_busy[0]]
        for current_start, current_end in all_busy[1:]:
            last_start, last_end = merged[-1]
            if current_start <= last_end:
                # Overlapping or adjacent, merge them
                new_start = min(last_start, current_start)
                new_end = max(last_end, current_end)
                merged[-1] = (new_start, new_end)
            else:
                merged.append((current_start, current_end))

    # Check the gap before the first busy interval
    first_busy_start = merged[0][0] if merged else end_min
    gap_start = start_min
    gap_end = first_busy_start
    if gap_end - gap_start >= duration_min:
        return format_time(gap_start)

    # Check gaps between busy intervals
    for i in range(1, len(merged)):
        prev_end = merged[i-1][1]
        curr_start = merged[i][0]
        gap_start = prev_end
        gap_end = curr_start
        if gap_end - gap_start >= duration_min:
            return format_time(gap_start)

    # Check the gap after the last busy interval
    last_busy_end = merged[-1][1] if merged else start_min
    gap_start = last_busy_end
    gap_end = end_min
    if gap_end - gap_start >= duration_min:
        return format_time(gap_start)

    return None
```

```python
def split_sql(script: str) -> list[str]:
    statements: list[str] = []
    parts: list[str] = []
    i = 0
    n = len(script)

    while i < n:
        char = script[i]

        if char in ("'", '"'):
            quote = char
            start = i
            i += 1

            while i < n:
                if script[i] == quote:
                    if i + 1 < n and script[i + 1] == quote:
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    i += 1
            else:
                kind = "string" if quote == "'" else "identifier"
                raise ValueError(f"Unterminated {kind}")

            parts.append(script[start:i])

        elif script.startswith("--", i):
            end = script.find("\n", i + 2)
            i = n if end == -1 else end

        elif script.startswith("/*", i):
            end = script.find("*/", i + 2)
            if end == -1:
                raise ValueError("Unterminated block comment")
            parts.append(" ")
            i = end + 2

        elif char == ";":
            statement = "".join(parts).strip()
            if statement:
                statements.append(statement)
            parts.clear()
            i += 1

        else:
            parts.append(char)
            i += 1

    statement = "".join(parts).strip()
    if statement:
        statements.append(statement)

    return statements
```

```python
def wrap_text(text: str, width: int) -> list[str]:
    if width < 1:
        raise ValueError("width must be at least 1")

    lines: list[str] = []
    current = ""

    for word in text.split():
        if current and len(current) + 1 + len(word) > width:
            lines.append(current)
            current = ""

        if len(word) > width:
            for start in range(0, len(word), width):
                piece = word[start:start + width]
                if start + width < len(word):
                    lines.append(piece)
                else:
                    current = piece
        elif current:
            current += " " + word
        else:
            current = word

    if current:
        lines.append(current)

    return lines
```

