import re


def negotiate_language(header: str, available: list[str]) -> str | None:
    range_pattern = re.compile(r"(?:\*|[A-Za-z]{1,8}(?:-[A-Za-z0-9]{1,8})*)")
    quality_pattern = re.compile(
        r"[qQ]\s*=\s*(0(?:\.[0-9]{0,3})?|1(?:\.0{0,3})?)"
    )

    entries: list[tuple[str, int, int]] = []

    for position, raw_entry in enumerate(header.split(",")):
        entry = raw_entry.strip()
        if not entry:
            continue

        parts = entry.split(";")
        language_range = parts[0].strip()
        if len(parts) > 2 or not range_pattern.fullmatch(language_range):
            raise ValueError(f"Invalid Accept-Language entry: {entry!r}")

        quality = 1000
        if len(parts) == 2:
            match = quality_pattern.fullmatch(parts[1].strip())
            if match is None:
                raise ValueError(f"Invalid Accept-Language parameter: {parts[1]!r}")

            whole, _, fraction = match.group(1).partition(".")
            quality = int(whole) * 1000 + int(fraction.ljust(3, "0"))

        entries.append((language_range.lower(), quality, position))

    best_tag: str | None = None
    best_key: tuple[int, int, int] | None = None

    for available_position, tag in enumerate(available):
        normalized_tag = tag.lower()
        chosen_specificity = -2
        chosen_quality = 0
        chosen_position = 0

        for language_range, quality, position in entries:
            if language_range == "*":
                specificity = -1
            elif (
                normalized_tag == language_range
                or normalized_tag.startswith(language_range + "-")
            ):
                specificity = len(language_range)
            else:
                continue

            # Strictly greater preserves the earlier duplicate range.
            if specificity > chosen_specificity:
                chosen_specificity = specificity
                chosen_quality = quality
                chosen_position = position

        if chosen_quality > 0:
            key = (chosen_quality, -chosen_position, -available_position)
            if best_key is None or key > best_key:
                best_key = key
                best_tag = tag

    return best_tag
