```python
def first_common_slot(
    busy: list[list[tuple[str, str]]],
    day_start: str,
    day_end: str,
    duration_min: int,
) -> str | None:
    def parse_time(value: str) -> int:
        if (
            not isinstance(value, str)
            or len(value) != 5
            or value[2] != ":"
            or any(c < "0" or c > "9" for c in value[:2] + value[3:])
        ):
            raise ValueError(f"Malformed time: {value!r}")

        hours, minutes = int(value[:2]), int(value[3:])
        if hours > 23 or minutes > 59:
            raise ValueError(f"Malformed time: {value!r}")
        return hours * 60 + minutes

    start_of_day = parse_time(day_start)
    end_of_day = parse_time(day_end)
    if end_of_day <= start_of_day:
        raise ValueError("day_end must be later than day_start")
    if duration_min < 1:
        raise ValueError("duration_min must be at least 1")

    intervals: list[tuple[int, int]] = []
    for person in busy:
        for start_text, end_text in person:
            start = parse_time(start_text)
            end = parse_time(end_text)
            if end <= start:
                raise ValueError("Busy interval end must be later than start")

            start = max(start, start_of_day)
            end = min(end, end_of_day)
            if start < end:
                intervals.append((start, end))

    # Validate every interval before returning any result.
    intervals.sort()
    candidate = start_of_day

    for start, end in intervals:
        if candidate + duration_min <= start:
            return f"{candidate // 60:02d}:{candidate % 60:02d}"
        candidate = max(candidate, end)

    if candidate + duration_min <= end_of_day:
        return f"{candidate // 60:02d}:{candidate % 60:02d}"
    return None
