```python
def parse_csv_line(line: str, delimiter: str = ",") -> list[str]:
    if not isinstance(delimiter, str) or len(delimiter) != 1 or delimiter == '"':
        raise ValueError("delimiter must be a single character other than '\"'")

    fields: list[str] = []
    i = 0
    n = len(line)

    while True:
        # Start of a field
        if i < n and line[i] == '"':
            # Quoted field
            i += 1
            chars: list[str] = []
            closed = False
            while i < n:
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        chars.append('"')
                        i += 2
                    else:
                        # Closing quote
                        i += 1
                        closed = True
                        break
                else:
                    chars.append(c)
                    i += 1
            if not closed:
                raise ValueError("unterminated quoted field")
            # After closing quote must be delimiter or end of line
            if i < n and line[i] != delimiter:
                raise ValueError("characters after closing quote")
            fields.append("".join(chars))
        else:
            # Unquoted field: read until delimiter or end of line
            start = i
            while i < n and line[i] != delimiter:
                if line[i] == '"':
                    raise ValueError("quote in unquoted field")
                i += 1
            fields.append(line[start:i])

        # After field, either delimiter or end of line
        if i < n and line[i] == delimiter:
            i += 1
            # If delimiter is at end, next iteration will produce trailing empty field
            continue
        else:
            break

    return fields
```

```python
def resolve_pointer(doc, pointer: str):
    if pointer == "":
        return doc

    if not pointer.startswith("/"):
        raise ValueError("pointer must start with '/' or be empty")

    tokens = pointer.split("/")[1:]

    current = doc
    for token in tokens:
        # Decode ~1 before ~0
        decoded = []
        i = 0
        while i < len(token):
            ch = token[i]
            if ch == "~":
                if i + 1 >= len(token):
                    raise ValueError("invalid escape: '~' at end of token")
                nxt = token[i + 1]
                if nxt == "1":
                    decoded.append("/")
                    i += 2
                elif nxt == "0":
                    decoded.append("~")
                    i += 2
                else:
                    raise ValueError("invalid escape sequence")
            else:
                decoded.append(ch)
                i += 1
        key = "".join(decoded)

        if isinstance(current, dict):
            if key not in current:
                raise KeyError(key)
            current = current[key]
        elif isinstance(current, list):
            if key == "-":
                raise KeyError(key)
            # Must be ASCII digits, no leading zeros unless "0"
            if not key.isascii() or not key.isdigit():
                raise ValueError("invalid array index")
            if len(key) > 1 and key[0] == "0":
                raise ValueError("invalid array index: leading zero")
            index = int(key)
            if index >= len(current):
                raise KeyError(key)
            current = current[index]
        else:
            raise KeyError(key)

    return current
```

