```python
def glob_match(pattern: str, name: str) -> bool:
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def match(p_idx: int, n_idx: int) -> bool:
        # Both exhausted: match
        if p_idx == len(pattern) and n_idx == len(name):
            return True
        # Pattern exhausted but name remains: no match
        if p_idx == len(pattern):
            return False

        p_char = pattern[p_idx]

        # Handle ** (matches any sequence including /)
        if p_char == '*' and p_idx + 1 < len(pattern) and pattern[p_idx + 1] == '*':
            # Try matching 0 characters, or consume one character from name
            # Skip the ** and try matching rest with same name position
            if match(p_idx + 2, n_idx):
                return True
            # Or consume one character from name and keep **
            if n_idx < len(name) and match(p_idx, n_idx + 1):
                return True
            return False

        # Handle single * (matches any sequence without /)
        if p_char == '*':
            # Try matching 0 characters
            if match(p_idx + 1, n_idx):
                return True
            # Or consume one character from name (if not /)
            if n_idx < len(name) and name[n_idx] != '/' and match(p_idx, n_idx + 1):
                return True
            return False

        # Handle ? (matches exactly one character other than /)
        if p_char == '?':
            if n_idx < len(name) and name[n_idx] != '/':
                return match(p_idx + 1, n_idx + 1)
            return False

        # Handle character class [...]
        if p_char == '[':
            # Find closing ]
            j = p_idx + 1
            if j < len(pattern) and pattern[j] in ('!', '^'):
                j += 1
            # Check if ] is first (after optional ! or ^) - it's literal
            if j < len(pattern) and pattern[j] == ']':
                j += 1
            # Find actual closing ]
            while j < len(pattern) and pattern[j] != ']':
                j += 1

            if j >= len(pattern):
                # No closing ], treat [ as literal
                if n_idx < len(name) and name[n_idx] == '[':
                    return match(p_idx + 1, n_idx + 1)
                return False

            # Parse the character class
            class_start = p_idx + 1
            negated = False
            if class_start < len(pattern) and pattern[class_start] in ('!', '^'):
                negated = True
                class_start += 1

            # Build set of characters and ranges
            chars = set()
            ranges = []
            k = class_start
            # Handle ] as first character (literal)
            if k < j and pattern[k] == ']':
                chars.add(']')
                k += 1

            while k < j:
                if k + 2 < j and pattern[k + 1] == '-' and pattern[k + 2] != ']':
                    # Range
                    start = pattern[k]
                    end = pattern[k + 2]
                    if ord(start) <= ord(end):
                        ranges.append((ord(start), ord(end)))
                    # else: range matches nothing, skip it
                    k += 3
                else:
                    # Single character
                    chars.add(pattern[k])
                    k += 1

            # Check if name character matches
            if n_idx >= len(name):
                return False
            c = name[n_idx]
            if c == '/':
                return False  # character class never matches /

            matched = c in chars
            if not matched:
                code = ord(c)
                for start, end in ranges:
                    if start <= code <= end:
                        matched = True
                        break

            if negated:
                matched = not matched

