import re
from datetime import date, timedelta

def add_business_days(start: str, days: int, holidays: list[str]) -> str:
    # Validate format and parse start date
    date_pattern = re.compile(r'^\d{4}-\d{2}-\d{2}$')

    def parse_date(s: str, name: str) -> date:
        if not isinstance(s, str) or not date_pattern.match(s):
            raise ValueError(f"{name} must be a valid date in YYYY-MM-DD format")
        try:
            return date.fromisoformat(s)
        except ValueError:
            raise ValueError(f"{name} must be a valid date in YYYY-MM-DD format")

    start_date = parse_date(start, "start")

    # Parse and validate holidays
    holiday_set = set()
    for h in holidays:
        holiday_set.add(parse_date(h, "holiday"))

    def is_business_day(d: date) -> bool:
        return d.weekday() < 5 and d not in holiday_set

    if days == 0:
        # Return start if business day, else first business day after
        current = start_date
        while not is_business_day(current):
            current += timedelta(days=1)
        return current.isoformat()

    if days > 0:
        # Move forward, counting business days after start
        current = start_date
        count = 0
        while count < days:
            current += timedelta(days=1)
            if is_business_day(current):
                count += 1
        return current.isoformat()

    else:  # days < 0
        # Move backward, counting business days before start
        current = start_date
        count = 0
        target = -days
        while count < target:
            current -= timedelta(days=1)
            if is_business_day(current):
                count += 1
        return current.isoformat()
```

```python
import re
from datetime import date, timedelta


def add_business_days(start: str, days: int, holidays: list[str]) -> str:
    def parse_date(value: str) -> date:
        if not isinstance(value, str) or re.fullmatch(
            r"[0-9]{4}-[0-9]{2}-[0-9]{2}", value
        ) is None:
            raise ValueError(f"Invalid date: {value!r}")
        return date.fromisoformat(value)

    current = parse_date(start)
    holiday_dates = {parse_date(value) for value in holidays}

    def is_business_day(value: date) -> bool:
        return value.weekday() < 5 and value not in holiday_dates

    if days == 0:
        while not is_business_day(current):
            current += timedelta(days=1)
    else:
        step = timedelta(days=1 if days > 0 else -1)
        remaining = abs(days)
        while remaining:
            current += step
            if is_business_day(current):
                remaining -= 1

    return current.isoformat()
```

```python
from datetime import datetime, timedelta

def add_business_days(start: str, days: int, holidays: list[str]) -> str:
    # Validate start date
    try:
        current = datetime.strptime(start, "%Y-%m-%d").date()
    except ValueError:
        raise ValueError("Invalid start date format")

    # Validate holiday dates
    holiday_dates = set()
    for holiday in holidays:
        try:
            holiday_date = datetime.strptime(holiday, "%Y-%m-%d").date()
            holiday_dates.add(holiday_date)
        except ValueError:
            raise ValueError("Invalid holiday date format")

    if days == 0:
        # Check if start is a business day
        if current.weekday() < 5 and current not in holiday_dates:
            return start
        # Find first business day after start
        days = 1

    step = 1 if days > 0 else -1
    business_days = abs(days)

    while business_days > 0:
        current += timedelta(days=step)
        if current.weekday() < 5 and current not in holiday_dates:
            business_days -= 1

    return current.strftime("%Y-%m-%d")
