import json

def resolve_pointer(doc, pointer: str):
    if not pointer.startswith('/') and pointer != "":
        raise ValueError("Pointer must start with '/' or be empty")

    if pointer == "":
        return doc

    tokens = pointer.split('/')[1:]  # Skip the leading empty string from split

    current = doc
    for token in tokens:
        # Decode ~1 and ~0 in the token
        decoded_token = []
        i = 0
        n = len(token)
        while i < n:
            if token[i] == '~':
                if i + 1 >= n:
                    raise ValueError("Invalid escape sequence in pointer")
                if token[i+1] == '0':
                    decoded_token.append('~')
                    i += 2
                elif token[i+1] == '1':
                    decoded_token.append('/')
                    i += 2
                else:
                    raise ValueError("Invalid escape sequence in pointer")
            else:
                decoded_token.append(token[i])
                i += 1
        decoded_token = ''.join(decoded_token)

        # Navigate based on the type of current
        if isinstance(current, dict):
            if decoded_token not in current:
                raise KeyError(f"Key not found: {decoded_token}")
            current = current[decoded_token]
        elif isinstance(current, list):
            if decoded_token == '-':
                raise KeyError("Index '-' refers to non-existent element")
            if not decoded_token.isdigit():
                raise ValueError(f"Invalid list index: {decoded_token}")
            if len(decoded_token) > 1 and decoded_token[0] == '0':
                raise ValueError(f"List index has leading zeros: {decoded_token}")
            index = int(decoded_token)
            if index >= len(current):
                raise KeyError(f"Index out of range: {index}")
            current = current[index]
        else:
            raise KeyError("Cannot apply token to non-dict/list")

    return current
