import ipaddress
import re

_CIDR_PATTERN = re.compile(
    r"(0|[1-9][0-9]{0,2})\."
    r"(0|[1-9][0-9]{0,2})\."
    r"(0|[1-9][0-9]{0,2})\."
    r"(0|[1-9][0-9]{0,2})/([0-9]+)"
)


def _parse_cidr(block: str) -> tuple[int, int]:
    if not isinstance(block, str):
        raise ValueError(f"Invalid IPv4 CIDR: {block!r}")

    match = _CIDR_PATTERN.fullmatch(block)
    if match is None:
        raise ValueError(f"Invalid IPv4 CIDR: {block!r}")

    octets = [int(part) for part in match.groups()[:4]]
    prefix_text = match.group(5).lstrip("0") or "0"
    if any(octet > 255 for octet in octets) or len(prefix_text) > 2:
        raise ValueError(f"Invalid IPv4 CIDR: {block!r}")

    prefix = int(prefix_text)
    if prefix > 32:
        raise ValueError(f"Invalid IPv4 CIDR: {block!r}")

    address = 0
    for octet in octets:
        address = (address << 8) | octet

    size = 1 << (32 - prefix)
    if address % size:
        raise ValueError(f"Host bits set in IPv4 CIDR: {block!r}")

    return address, address + size - 1


def cidr_subtract(base: str, remove: list[str]) -> list[str]:
    base_start, base_end = _parse_cidr(base)

    # Validate every removal, including those outside base.
    intervals = []
    for block in remove:
        start, end = _parse_cidr(block)
        start = max(start, base_start)
        end = min(end, base_end)
        if start <= end:
            intervals.append((start, end))
    intervals.sort()

    result: list[str] = []

    def emit(start: int, end: int) -> None:
        result.extend(
            str(network)
            for network in ipaddress.summarize_address_range(
                ipaddress.IPv4Address(start),
                ipaddress.IPv4Address(end),
            )
        )

    cursor = base_start
    for start, end in intervals:
        if end < cursor:
            continue
        if start > cursor:
            emit(cursor, start - 1)
        cursor = end + 1
        if cursor > base_end:
            break

    if cursor <= base_end:
        emit(cursor, base_end)

    return result
```

