import re


def resolve_pointer(doc, pointer: str):
    if pointer == "":
        return doc
    if not pointer.startswith("/"):
        raise ValueError("A non-empty JSON Pointer must start with '/'")

    tokens = pointer.split("/")[1:]
    for i, token in enumerate(tokens):
        if re.search(r"~(?:[^01]|$)", token):
            raise ValueError(f"Invalid escape in reference token: {token!r}")
        tokens[i] = token.replace("~1", "/").replace("~0", "~")

    current = doc
    for token in tokens:
        if isinstance(current, dict):
            current = current[token]
        elif isinstance(current, list):
            if token == "-":
                raise KeyError(token)
            if re.fullmatch(r"(?:0|[1-9][0-9]*)", token) is None:
                raise ValueError(f"Invalid array index: {token!r}")

            # Reject huge indices before int() to avoid its digit limit.
            length = len(current)
            if len(token) > len(str(length)):
                raise KeyError(token)
            index = int(token)
            if index >= length:
                raise KeyError(token)
            current = current[index]
        else:
            raise KeyError(token)

    return current
