            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(expr[i:j])
            i = j
            continue
        raise ValueError(f"Unknown character: {c}")
    return tokens

def parse_expression(tokens: List[str]) -> Tuple[Union[Fraction, 'AST'], List[str]]:
    return parse_binary_op(tokens, 0)

def parse_binary_op(tokens: List[str], min_precedence: int) -> Tuple[Union[Fraction, 'AST'], List[str]]:
    left, tokens = parse_unary_op(tokens)

    while tokens:
        op = tokens[0]
        if op in ('+', '-') and min_precedence <= 1:
            precedence = 1
        elif op in ('*', '/') and min_precedence <= 2:
            precedence = 2
        elif op == '**' and min_precedence <= 3:
            precedence = 3
        else:
            break

