            # Right-associative
            right, tokens = parse_binary_op(tokens[1:], precedence)
        else:
            # Left-associative
            right, tokens = parse_binary_op(tokens[1:], precedence + 1)

        left = ('binary', op, left, right)

    return left, tokens

def parse_unary_op(tokens: List[str]) -> Tuple[Union[Fraction, 'AST'], List[str]]:
    if not tokens:
        raise ValueError("Missing operand")

    if tokens[0] in ('+', '-'):
        op = tokens[0]
        operand, tokens = parse_unary_op(tokens[1:])
        return ('unary', op, operand), tokens
    else:
        return parse_primary(tokens)

def parse_primary(tokens: List[str]) -> Tuple[Union[Fraction, 'AST'], List[str]]:
    if not tokens:
        raise ValueError("Missing operand")

    token = tokens[0]
    if token == '(':
