def glob_match(pattern: str, name: str) -> bool:
    tokens = []
    i = 0

    while i < len(pattern):
        c = pattern[i]

        if c == "\\":
            if i + 1 < len(pattern):
                tokens.append(("literal", pattern[i + 1]))
                i += 2
            else:
                tokens.append(("literal", "\\"))
                i += 1

        elif c == "*":
            if i + 1 < len(pattern) and pattern[i + 1] == "*":
                tokens.append(("globstar", None))
                i += 2
            else:
                tokens.append(("star", None))
                i += 1

        elif c == "?":
            tokens.append(("any", None))
            i += 1

        elif c == "[":
            start = i + 1
            negated = start < len(pattern) and pattern[start] in "!^"
            if negated:
                start += 1

            # An initial ']' is a member, not the closing delimiter.
            search_from = start
            if search_from < len(pattern) and pattern[search_from] == "]":
                search_from += 1

            end = pattern.find("]", search_from)
            if end == -1:
                tokens.append(("literal", "["))
                i += 1
                continue

            members = pattern[start:end]
            ranges = []
            left, right = 0, len(members)

            # Boundary hyphens are always literal members.
            if left < right and members[left] == "-":
                ranges.append((ord("-"), ord("-")))
                left += 1
            if left < right and members[right - 1] == "-":
                ranges.append((ord("-"), ord("-")))
                right -= 1

            while left < right:
                if left + 2 < right and members[left + 1] == "-":
                    lo = ord(members[left])
                    hi = ord(members[left + 2])
                    if lo <= hi:
                        ranges.append((lo, hi))
                    left += 3
                else:
                    code = ord(members[left])
                    ranges.append((code, code))
                    left += 1

            tokens.append(("set", (negated, ranges)))
            i = end + 1

        else:
            tokens.append(("literal", c))
            i += 1

    # dp[j]: the processed pattern matches exactly name[:j].
    n = len(name)
    dp = [False] * (n + 1)
    dp[0] = True

    for kind, value in tokens:
        next_dp = [False] * (n + 1)

        if kind in ("star", "globstar"):
            next_dp[0] = dp[0]
            crosses_slashes = kind == "globstar"
            for j, char in enumerate(name, 1):
                next_dp[j] = dp[j] or (
                    next_dp[j - 1] and (crosses_slashes or char != "/")
                )

        else:
            for j, char in enumerate(name, 1):
                if not dp[j - 1]:
                    continue

                if kind == "literal":
                    matches = char == value
                elif kind == "any":
                    matches = char != "/"
                else:
                    negated, ranges = value
                    code = ord(char)
                    contained = any(lo <= code <= hi for lo, hi in ranges)
                    matches = char != "/" and (contained != negated)

                next_dp[j] = matches

        dp = next_dp

    return dp[n]
