```python
from fractions import Fraction


def evaluate(expr: str) -> Fraction:
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2,
                  "u+": 3, "u-": 3, "**": 4}
    output: list[Fraction | str] = []
    operators: list[str] = []
    expecting_operand = True
    i = 0
    n = len(expr)

    # Validate the entire expression and convert it to postfix notation.
    while i < n:
        c = expr[i]

        if c.isspace():
            i += 1
            continue

        if "0" <= c <= "9":
            if not expecting_operand:
                raise ValueError("Expected an operator")

            # Avoid the interpreter's limit on decimal string-to-int conversion.
            number = 0
            while i < n and "0" <= expr[i] <= "9":
                number = number * 10 + ord(expr[i]) - ord("0")
                i += 1

            output.append(Fraction(number))
            expecting_operand = False
            continue

        if c == "(":
            if not expecting_operand:
                raise ValueError("Expected an operator before '('")
            operators.append(c)
            i += 1
            continue

        if c == ")":
            if expecting_operand:
                raise ValueError("Missing operand before ')'")

            while operators and operators[-1] != "(":
                output.append(operators.pop())
            if not operators:
                raise ValueError("Unmatched ')'")

            operators.pop()
            expecting_operand = False
            i += 1
            continue

        if c not in "+-*/":
            raise ValueError(f"Unknown character: {c!r}")

        op = c
        i += 1
        if c == "*" and i < n and expr[i] == "*":
            op = "**"
            i += 1

        if expecting_operand:
            if op not in ("+", "-"):
                raise ValueError("Missing operand")
            # Prefix operators must not pop a preceding power operator.
            operators.append("u" + op)
            continue

        while operators and operators[-1] != "(":
            top = operators[-1]
            if (precedence[top] > precedence[op]
                    or (precedence[top] == precedence[op] and op != "**")):
                output.append(operators.pop())
            else:
                break

        operators.append(op)
        expecting_operand = True

    if expecting_operand:
        raise ValueError("Empty expression or missing operand")
    if "(" in operators:
        raise ValueError("Unmatched '('")

    output.extend(reversed(operators))

    # Evaluate only after syntax validation has succeeded.
    values: list[Fraction] = []
    for token in output:
        if isinstance(token, Fraction):
            values.append(token)
        elif token == "u+":
            continue
        elif token == "u-":
            values[-1] = -values[-1]
        else:
            right = values.pop()
            left = values.pop()

            if token == "+":
                result = left + right
            elif token == "-":
                result = left - right
            elif token == "*":
                result = left * right
            elif token == "/":
                result = left / right
            else:  # **
                if right.denominator != 1:
                    raise ValueError("Exponent must be an integer")
                result = left ** right.numerator

            values.append(result)

    return values[0]
