import re

def glob_match(pattern: str, name: str) -> bool:
    def compile_pattern(p: str) -> str:
        i = 0
        n = len(p)
        res = []
        while i < n:
            c = p[i]
            if c == '\\':
                if i + 1 < n:
                    res.append(re.escape(p[i+1]))
                    i += 2
                else:
                    res.append(re.escape('\\'))
                    i += 1
            elif c == '?':
                res.append('[^/]')
                i += 1
            elif c == '*':
                if i + 1 < n and p[i+1] == '*':
                    res.append('.*')
                    i += 2
                else:
                    res.append('[^/]*')
                    i += 1
            elif c == '[':
                j = i + 1
                if j >= n:
                    res.append(re.escape('['))
                    i += 1
                    continue
                negate = False
                if p[j] in '!^':
                    negate = True
                    j += 1
                if j >= n:
                    res.append(re.escape('['))
                    i += 1
                    continue
                chars = []
                while j < n and p[j] != ']':
                    if p[j] == '\\':
                        if j + 1 < n:
                            chars.append(re.escape(p[j+1]))
                            j += 2
                        else:
                            chars.append(re.escape('\\'))
                            j += 1
                    elif j + 2 < n and p[j+1] == '-':
                        start = p[j]
                        end = p[j+2]
                        if start > end:
                            chars.append(re.escape(start + '-' + end))
                        else:
                            chars.append(f'{re.escape(start)}-{re.escape(end)}')
                        j += 3
                    else:
                        chars.append(re.escape(p[j]))
                        j += 1
                if j >= n:
                    res.append(re.escape('['))
                    i += 1
                else:
                    if negate:
                        res.append(f'[^{"".join(chars)}]')
                    else:
                        res.append(f'[{"".join(chars)}]')
                    i = j + 1
            else:
                res.append(re.escape(c))
                i += 1
        return '^' + ''.join(res) + '$'

    regex = compile_pattern(pattern)
    return bool(re.fullmatch(regex, name))
```

This function works by:
1. Converting the glob pattern into a regular expression pattern
2. Using the `re.fullmatch` function to check if the entire name matches the converted pattern

The conversion handles all the specified glob syntax:
- `?` becomes `[^/]`
- `*` becomes `[^/]*`
- `**` becomes `.*`
- `[...]` sets are properly converted with all their special cases
- Backslashes are handled for escaping
- All other characters are treated literally

The function is case-sensitive as required.

```python
import re
from datetime import date, datetime, timedelta

_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


def _parse_date(value: str) -> date:
    if not isinstance(value, str) or not _DATE_RE.fullmatch(value):
        raise ValueError(f"Invalid date: {value!r}")
    try:
        return datetime.strptime(value, "%Y-%m-%d").date()
    except ValueError as exc:
        raise ValueError(f"Invalid date: {value!r}") from exc


def add_business_days(start: str, days: int, holidays: list[str]) -> str:
    start_date = _parse_date(start)
    holiday_set = {_parse_date(h) for h in holidays}

    def is_business_day(d: date) -> bool:
        return d.weekday() < 5 and d not in holiday_set

    if days > 0:
        current = start_date
        remaining = days
        while remaining > 0:
            current += timedelta(days=1)
            if is_business_day(current):
                remaining -= 1
        return current.isoformat()

    if days < 0:
        current = start_date
        remaining = -days
        while remaining > 0:
            current -= timedelta(days=1)
            if is_business_day(current):
                remaining -= 1
        return current.isoformat()

    # days == 0
    if is_business_day(start_date):
        return start_date.isoformat()

    current = start_date
    while True:
        current += timedelta(days=1)
        if is_business_day(current):
            return current.isoformat()
```

```python
def glob_match(pattern: str, name: str) -> bool:
    """Return whether the entire name matches the case-sensitive glob."""
    n = len(name)
    m = len(pattern)
    reachable = bytearray(n + 1)
    reachable[0] = 1
    last_close = pattern.rfind("]")
    i = 0

    while i < m:
        char = pattern[i]
        i += 1

        if char == "*":
            # Any uninterrupted run of at least two stars is equivalent to **.
            crosses_slashes = i < m and pattern[i] == "*"
            while i < m and pattern[i] == "*":
                i += 1

            for j in range(1, n + 1):
                reachable[j] = reachable[j] or (
                    reachable[j - 1]
                    and (crosses_slashes or name[j - 1] != "/")
                )
            continue

        kind = "literal"
        intervals: list[tuple[int, int]] = []
        negated = False

        if char == "\\":
            if i < m:
                char = pattern[i]
                i += 1
        elif char == "?":
            kind = "any"
        elif char == "[":
            start = i
            if start < m and pattern[start] in "!^":
                negated = True
                start += 1

            # An initial ] is a member, not the closing delimiter.
            search_from = start
            if search_from < m and pattern[search_from] == "]":
                search_from += 1

            end = (
                pattern.find("]", search_from)
                if search_from <= last_close
                else -1
            )

            if end != -1:
                kind = "class"
                k = start
                while k < end:
                    if k + 2 < end and pattern[k + 1] == "-":
                        low = ord(pattern[k])
                        high = ord(pattern[k + 2])
                        if low <= high:
                            intervals.append((low, high))
                        k += 3
                    else:
                        code = ord(pattern[k])
                        intervals.append((code, code))
                        k += 1
                i = end + 1
            # Otherwise only the opening [ is consumed, as a literal.

        # A non-star token consumes exactly one character. Work backwards
        # so reachable[j - 1] still belongs to the previous pattern prefix.
        for j in range(n, 0, -1):
            if not reachable[j - 1]:
                reachable[j] = 0
                continue

            current = name[j - 1]
            if kind == "literal":
                matched = current == char
            elif kind == "any":
                matched = current != "/"
            elif current == "/":
                matched = False
            else:
                code = ord(current)
                contained = any(low <= code <= high for low, high in intervals)
                matched = contained != negated

            reachable[j] = matched

        reachable[0] = 0

    return bool(reachable[n])
```

```python
import heapq

def topo_order(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    node_set = set(nodes)
    if len(node_set) != len(nodes):
        raise ValueError("nodes contains duplicates")

    unique_edges = set(edges)

    for a, b in unique_edges:
        if a not in node_set or b not in node_set:
            raise ValueError("edge mentions a node not in nodes")

    indegree = {node: 0 for node in nodes}
    adjacency = {node: [] for node in nodes}

    for a, b in unique_edges:
        adjacency[a].append(b)
        indegree[b] += 1

    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        node = heapq.heappop(heap)
        order.append(node)

        for neighbor in adjacency[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(order) != len(nodes):
        raise ValueError("edges contain a cycle")

    return order
```

```python
def parse_csv_line(line: str, delimiter: str = ",") -> list[str]:
    if len(delimiter) != 1 or delimiter == '"':
        raise ValueError("delimiter must be a single character other than '\"'")

    fields: list[str] = []
    i = 0
    n = len(line)

    while True:
        if i < n and line[i] == '"':
            i += 1
            buf: list[str] = []
            closed = False

            while i < n:
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        buf.append('"')
                        i += 2
                    else:
                        i += 1
                        closed = True
                        break
                else:
                    buf.append(c)
                    i += 1

            if not closed:
                raise ValueError("unterminated quoted field")

            if i < n and line[i] != delimiter:
                raise ValueError("unexpected character after closing quote")

            fields.append("".join(buf))

            if i < n:
                i += 1
                continue
            else:
                break
        else:
            start = i
            while i < n and line[i] != delimiter:
                if line[i] == '"':
                    raise ValueError("unquoted field contains a quote")
                i += 1

            fields.append(line[start:i])

            if i < n:
                i += 1
                continue
            else:
                break

    return fields
```

```python
import ipaddress

def cidr_subtract(base: str, remove: list[str]) -> list[str]:
    try:
        base_net = ipaddress.IPv4Network(base, strict=True)
    except ValueError as e:
        raise ValueError(f"Invalid base CIDR block: {e}")

    remove_nets = []
    for cidr in remove:
        try:
            net = ipaddress.IPv4Network(cidr, strict=True)
        except ValueError as e:
            raise ValueError(f"Invalid remove CIDR block '{cidr}': {e}")
        remove_nets.append(net)

    # Start with the base network
    remaining = [base_net]

    for net in remove_nets:
        new_remaining = []
        for current in remaining:
            # If current is completely outside net, keep it as is
            if current.is_disjoint(net):
                new_remaining.append(current)
            else:
                # Otherwise, subtract net from current
                new_remaining.extend(current.address_exclude(net))
        remaining = new_remaining
        if not remaining:
            return []

    # Convert to strings and sort by network address
    result = [str(net) for net in sorted(remaining, key=lambda n: (n.network_address, n.prefixlen))]
    return result
