import re

_RUN_RE = re.compile(r'[0-9]+|[^0-9]+')

def _run_key(run: str):
    if '0' <= run[0] <= '9':
        stripped = run.lstrip('0')
        return (0, len(stripped), stripped, len(run))
    return (1, run.lower())

def _natural_key(s: str):
    runs = _RUN_RE.findall(s)
    return (tuple(_run_key(run) for run in runs), s)

def natural_sort(items: list[str]) -> list[str]:
    return sorted(items, key=_natural_key)
