```python
def osa_distance(a: str, b: str) -> int:
    """Return the optimal string alignment (restricted Damerau-Levenshtein) distance."""
    m, n = len(a), len(b)
    d = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        d[i][0] = i
    for j in range(n + 1):
        d[0][j] = j

    for i in range(1, m + 1):
        ai = a[i - 1]
        for j in range(1, n + 1):
            cost = 0 if ai == b[j - 1] else 1
            best = min(
                d[i - 1][j] + 1,      # deletion
                d[i][j - 1] + 1,      # insertion
                d[i - 1][j - 1] + cost  # substitution/match
            )

            if i > 1 and j > 1 and a[i - 2] == b[j - 1] and ai == b[j - 2]:
                best = min(best, d[i - 2][j - 2] + 1)  # adjacent transposition

            d[i][j] = best

    return d[m][n]
```

