def wrap_text(text: str, width: int) -> list[str]:
    if width < 1:
        raise ValueError("width must be at least 1")

    words = text.split()
    if not words:
        return []

    lines = []
    current_line = []
    current_length = 0

    for word in words:
        if len(word) > width:
            # Handle long word: finish current line if not empty
            if current_line:
                lines.append(' '.join(current_line))
                current_line = []
                current_length = 0
            # Split the long word into chunks
            for i in range(0, len(word), width):
                chunk = word[i:i+width]
                if i + width < len(word):
                    lines.append(chunk)
                else:
                    current_line.append(chunk)
                    current_length = len(chunk)
        else:
            # Check if word fits in current line
            if current_line:
                new_length = current_length + 1 + len(word)
            else:
                new_length = len(word)

            if new_length <= width:
                current_line.append(word)
                current_length = new_length
            else:
                lines.append(' '.join(current_line))
                current_line = [word]
                current_length = len(word)

    if current_line:
        lines.append(' '.join(current_line))

    return lines
```

```python
def wrap_text(text: str, width: int) -> list[str]:
    if width < 1:
        raise ValueError("width must be at least 1")

    lines: list[str] = []
    current = ""

    for word in text.split():
        if len(word) > width:
            if current:
                lines.append(current)
                current = ""

            # Keep the final piece as the current line, even if it is full.
            last_start = ((len(word) - 1) // width) * width
            for start in range(0, last_start, width):
                lines.append(word[start:start + width])
            current = word[last_start:]
        elif not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word

    if current:
        lines.append(current)

    return lines
