import heapq


def topo_order(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    node_set = set(nodes)
    if len(node_set) != len(nodes):
        raise ValueError("nodes contains duplicates")

    successors: dict[str, set[str]] = {node: set() for node in nodes}
    indegree: dict[str, int] = {node: 0 for node in nodes}

    for a, b in edges:
        if a not in node_set or b not in node_set:
            raise ValueError("edge mentions a node not in nodes")
        if b not in successors[a]:
            successors[a].add(b)
            indegree[b] += 1

    available = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(available)
    order: list[str] = []

    while available:
        node = heapq.heappop(available)
        order.append(node)
        for successor in successors[node]:
            indegree[successor] -= 1
            if indegree[successor] == 0:
                heapq.heappush(available, successor)

    if len(order) != len(nodes):
        raise ValueError("edges contain a cycle")

    return order
