import heapq
from collections import defaultdict

def topo_order(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    # Check for duplicate nodes
    if len(nodes) != len(set(nodes)):
        raise ValueError("nodes contains duplicates")

    node_set = set(nodes)

    # Validate edges and build graph
    adj = defaultdict(set)
    indegree = {node: 0 for node in nodes}

    for a, b in edges:
        if a not in node_set or b not in node_set:
            raise ValueError(f"edge mentions unknown node: ({a}, {b})")
        if a == b:
            raise ValueError("self-loop detected")
        if b not in adj[a]:
            adj[a].add(b)
            indegree[b] += 1

    # Kahn's algorithm with min-heap for lexicographically smallest order
    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)

    result = []

    while heap:
        node = heapq.heappop(heap)
        result.append(node)

        for neighbor in sorted(adj[node]):
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("cycle detected")

    return result
