def split_sql(script: str) -> list[str]:
    statements: list[str] = []
    parts: list[str] = []
    i = 0
    n = len(script)

    while i < n:
        char = script[i]

        if char in ("'", '"'):
            quote = char
            start = i
            i += 1

            while i < n:
                if script[i] != quote:
                    i += 1
                    continue

                i += 1
                if i < n and script[i] == quote:
                    i += 1  # Doubled quote: still inside the quoted text.
                else:
                    parts.append(script[start:i])
                    break
            else:
                kind = "string" if quote == "'" else "identifier"
                raise ValueError(f"Unterminated {kind}")

        elif script.startswith("--", i):
            end = script.find("\n", i + 2)
            i = n if end == -1 else end  # Preserve the newline.

        elif script.startswith("/*", i):
            end = script.find("*/", i + 2)
            if end == -1:
                raise ValueError("Unterminated block comment")
            parts.append(" ")
            i = end + 2

        elif char == ";":
            statement = "".join(parts).strip()
            if statement:
                statements.append(statement)
            parts.clear()
            i += 1

        else:
            parts.append(char)
            i += 1

    statement = "".join(parts).strip()
    if statement:
        statements.append(statement)

    return statements
