```python
def wrap_text(text: str, width: int) -> list[str]:
    if width < 1:
        raise ValueError("width must be at least 1")

    lines: list[str] = []
    current: list[str] = []
    line_length = 0

    for word in text.split():
        if current and line_length + 1 + len(word) > width:
            lines.append(" ".join(current))
            current = []
            line_length = 0

        if len(word) > width:
            last_start = ((len(word) - 1) // width) * width
            lines.extend(
                word[start:start + width]
                for start in range(0, last_start, width)
            )
            word = word[last_start:]

        if current:
            line_length += 1
        current.append(word)
        line_length += len(word)

    if current:
        lines.append(" ".join(current))

    return lines
