def first_common_slot(busy: list[list[tuple[str, str]]], day_start: str, day_end: str, duration_min: int) -> str | None:
    import itertools

    def parse_time(time_str: str) -> int:
        try:
            hh, mm = map(int, time_str.split(':'))
            if not (0 <= hh <= 23 and 0 <= mm <= 59):
                raise ValueError
            return hh * 60 + mm
        except (ValueError, AttributeError):
            raise ValueError(f"Malformed time: {time_str}")

    def format_time(minutes: int) -> str:
        hh = minutes // 60
        mm = minutes % 60
        return f"{hh:02d}:{mm:02d}"

    # Validate inputs
    if duration_min < 1:
        raise ValueError("Duration must be at least 1 minute")

    start_min = parse_time(day_start)
    end_min = parse_time(day_end)
    if end_min <= start_min:
        raise ValueError("Day end must be after day start")

    # Collect and validate all busy intervals
    all_intervals = []
    for person in busy:
        for interval in person:
            if len(interval) != 2:
                raise ValueError("Each busy interval must be a tuple of (start, end)")
            s, e = interval
            s_min = parse_time(s)
            e_min = parse_time(e)
            if e_min <= s_min:
                raise ValueError(f"Busy interval end must be after start: {interval}")
            all_intervals.append((s_min, e_min))

    # Merge all busy intervals
    if not all_intervals:
        # No busy intervals, check if the whole day is free
        if (end_min - start_min) >= duration_min:
            return day_start
        else:
            return None

    # Sort intervals by start time
    all_intervals.sort()

    # Merge overlapping or adjacent intervals
    merged = []
    current_start, current_end = all_intervals[0]
    for s, e in all_intervals[1:]:
        if s <= current_end:
            current_end = max(current_end, e)
        else:
            merged.append((current_start, current_end))
            current_start, current_end = s, e
    merged.append((current_start, current_end))

    # Check the gap before the first busy interval
    first_busy_start = merged[0][0]
    if (first_busy_start - start_min) >= duration_min:
        return day_start

    # Check gaps between merged intervals
    for i in range(1, len(merged)):
        prev_end = merged[i-1][1]
        curr_start = merged[i][0]
        gap = curr_start - prev_end
        if gap >= duration_min:
            candidate = prev_end
            if (candidate + duration_min) <= end_min:
                return format_time(candidate)

    # Check the gap after the last busy interval
    last_busy_end = merged[-1][1]
    if (end_min - last_busy_end) >= duration_min:
        return format_time(last_busy_end)

    return None
```

