import re


def first_common_slot(
    busy: list[list[tuple[str, str]]],
    day_start: str,
    day_end: str,
    duration_min: int,
) -> str | None:
    def to_minutes(value: str) -> int:
        if not isinstance(value, str) or re.fullmatch(
            r"(?:[01][0-9]|2[0-3]):[0-5][0-9]", value
        ) is None:
            raise ValueError(f"Malformed time: {value!r}")
        return int(value[:2]) * 60 + int(value[3:])

    start_of_day = to_minutes(day_start)
    end_of_day = to_minutes(day_end)

    if end_of_day <= start_of_day:
        raise ValueError("day_end must be later than day_start")
    if duration_min < 1:
        raise ValueError("duration_min must be at least 1")

    intervals: list[tuple[int, int]] = []
    for person in busy:
        for start, end in person:
            start_min = to_minutes(start)
            end_min = to_minutes(end)
            if end_min <= start_min:
                raise ValueError("Busy interval end must be later than its start")

            clipped_start = max(start_min, start_of_day)
            clipped_end = min(end_min, end_of_day)
            if clipped_start < clipped_end:
                intervals.append((clipped_start, clipped_end))

    intervals.sort()
    candidate = start_of_day

    for start, end in intervals:
        if candidate + duration_min <= start:
            return f"{candidate // 60:02d}:{candidate % 60:02d}"
        candidate = max(candidate, end)

    if candidate + duration_min <= end_of_day:
        return f"{candidate // 60:02d}:{candidate % 60:02d}"
    return None
