import re


def negotiate_language(header: str, available: list[str]) -> str | None:
    range_re = re.compile(r"(?:\*|[A-Za-z]{1,8}(?:-[A-Za-z0-9]{1,8})*)")
    quality_re = re.compile(r"(?:0(?:\.[0-9]{0,3})?|1(?:\.0{0,3})?)")

    entries: list[tuple[str, int, int]] = []
    seen: set[str] = set()

    for position, raw_entry in enumerate(header.split(",")):
        entry = raw_entry.strip()
        if not entry:
            continue

        parts = entry.split(";")
        language_range = parts[0].strip()
        if range_re.fullmatch(language_range) is None:
            raise ValueError(f"Malformed language range: {language_range!r}")

        quality = 1000
        if len(parts) == 2:
            parameter = parts[1].split("=")
            if len(parameter) != 2 or parameter[0].strip().lower() != "q":
                raise ValueError(f"Malformed parameter: {parts[1]!r}")
            value = parameter[1].strip()
            if quality_re.fullmatch(value) is None:
                raise ValueError(f"Malformed quality: {value!r}")
            whole, _, fraction = value.partition(".")
            quality = int(whole) * 1000 + int(fraction.ljust(3, "0"))
        elif len(parts) > 2:
            raise ValueError(f"Too many parameters: {entry!r}")

        language_range = language_range.lower()
        if language_range not in seen:
            seen.add(language_range)
            entries.append((language_range, quality, position))

    best_tag: str | None = None
    best_rank: tuple[int, int, int] | None = None

    for available_position, tag in enumerate(available):
        normalized_tag = tag.lower()
        specificity = -1
        selected_quality = 0
        selected_position = 0

        for language_range, quality, position in entries:
            if language_range == "*":
                current_specificity = 0
            elif (
                normalized_tag == language_range
                or normalized_tag.startswith(language_range + "-")
            ):
                current_specificity = len(language_range)
            else:
                continue

            if current_specificity > specificity:
                specificity = current_specificity
                selected_quality = quality
                selected_position = position

        if selected_quality > 0:
            rank = (
                selected_quality,
                -selected_position,
                -available_position,
            )
            if best_rank is None or rank > best_rank:
                best_rank = rank
                best_tag = tag

    return best_tag
