```python
import re


def format_money(amount: str, currency: str) -> str:
    currencies = {
        "USD": ("$", 2),
        "EUR": ("€", 2),
        "JPY": ("¥", 0),
        "BHD": ("BHD ", 3),
    }
    if not isinstance(currency, str) or currency not in currencies:
        raise ValueError("Unknown currency code")

    if not isinstance(amount, str):
        raise ValueError("Malformed amount")
    match = re.fullmatch(r"(-?)([0-9]+)(?:\.([0-9]+))?", amount)
    if match is None:
        raise ValueError("Malformed amount")

    symbol, places = currencies[currency]
    sign, integer, fraction = match.groups()
    fraction = fraction or ""

    # Work with digit strings to avoid precision and integer-conversion limits.
    digits = (integer + fraction[:places].ljust(places, "0")).lstrip("0") or "0"
    discarded = fraction[places:]

    round_up = bool(discarded) and (
        discarded[0] > "5"
        or (
            discarded[0] == "5"
            and (
                any(digit != "0" for digit in discarded[1:])
                or digits[-1] in "13579"
            )
        )
    )

    if round_up:
        i = len(digits) - 1
        while i >= 0 and digits[i] == "9":
            i -= 1
        if i < 0:
            digits = "1" + "0" * len(digits)
        else:
            digits = (
                digits[:i]
                + chr(ord(digits[i]) + 1)
                + "0" * (len(digits) - i - 1)
            )

    negative = sign == "-" and digits != "0"
    digits = digits.zfill(places + 1)

    if places:
        integer = digits[:-places]
        fractional_part = "." + digits[-places:]
    else:
        integer = digits
        fractional_part = ""

    first_group = len(integer) % 3 or 3
    grouped = integer[:first_group] + "".join(
        "," + integer[i:i + 3]
        for i in range(first_group, len(integer), 3)
    )

    return ("-" if negative else "") + symbol + grouped + fractional_part
