import re

def negotiate_language(header: str, available: list[str]) -> str | None:
    # Parse header into list of (range, q, position) entries
    entries: list[tuple[str, float, int]] = []
    if header.strip():
        for pos, raw_entry in enumerate(header.split(',')):
            entry = raw_entry.strip()
            if not entry:
                continue
            # Split on ';'
            parts = [p.strip() for p in entry.split(';')]
            range_part = parts[0]
            if not range_part:
                raise ValueError("empty language range")
            # Validate range
            if not _is_valid_range(range_part):
                raise ValueError(f"malformed range: {range_part}")
            q = 1.0
            # Process parameters
            for param in parts[1:]:
                if not param:
                    raise ValueError("empty parameter")
                if '=' not in param:
                    raise ValueError(f"malformed parameter: {param}")
                key, value = param.split('=', 1)
                key = key.strip()
                value = value.strip()
                if key != 'q':
                    raise ValueError(f"unknown parameter: {key}")
                if not _is_valid_q(value):
                    raise ValueError(f"malformed q value: {value}")
                q = float(value)
            entries.append((range_part.lower(), q, pos))

    # For each available tag, find best matching range
    best_for_tag: list[tuple[float, int, int] | None] = []  # (q, header_pos, range_len)
    for tag in available:
        tag_lower = tag.lower()
        best_q = 0.0
        best_pos = -1
        best_len = -1
        for range_str, q, pos in entries:
            if q == 0:
                # Still need to check if it matches to potentially override? No, q=0 means not acceptable
                # But we need to check if this range matches to set q=0
                pass
            # Check if range matches tag
            if range_str == '*':
                match_len = 0  # least specific
                matches = True
            elif tag_lower == range_str:
                match_len = len(range_str)
                matches = True
            elif tag_lower.startswith(range_str + '-'):
                match_len = len(range_str)
                matches = True
            else:
                matches = False
                match_len = -1

            if matches:
                # More specific (longer range) wins, then earlier position
                if match_len > best_len or (match_len == best_len and pos < best_pos):
                    best_len = match_len
                    best_q = q
                    best_pos = pos
                # If same range appears again, earlier wins (already handled by pos < best_pos check)
        if best_pos == -1:
            # No matching range means q=0 (not acceptable)
            best_for_tag.append(None)
        else:
            best_for_tag.append((best_q, best_pos, best_len))

    # Find best tag
    best_tag_idx = -1
    best_q = 0.0
    best_pos = -1
    for idx, (tag_info, tag) in enumerate(zip(best_for_tag, available)):
        if tag_info is None:
            continue
        q, pos, _ = tag_info
        if q == 0:
            continue
        if q > best_q or (q == best_q and pos < best_pos):
            best_q = q
            best_pos = pos
            best_tag_idx = idx

    if best_tag_idx == -1:
        return None
    return available[best_tag_idx]

