def first_common_slot(
    busy: list[list[tuple[str, str]]],
    day_start: str,
    day_end: str,
    duration_min: int,
) -> str | None:
    def parse_time(value: str) -> int:
        if (
            not isinstance(value, str)
            or len(value) != 5
            or value[2] != ":"
            or not all(c in "0123456789" for c in value[:2] + value[3:])
        ):
