        hours = int(value[:2])
        minutes = int(value[3:])
        if hours > 23 or minutes > 59:
            raise ValueError(f"Malformed time: {value!r}")
        return hours * 60 + minutes

    if duration_min < 1:
        raise ValueError("duration_min must be at least 1")

    start = parse_time(day_start)
    end = parse_time(day_end)
    if end <= start:
        raise ValueError("day_end must be later than day_start")

    intervals: list[tuple[int, int]] = []
    for person in busy:
        for busy_start, busy_end in person:
            interval_start = parse_time(busy_start)
            interval_end = parse_time(busy_end)
            if interval_end <= interval_start:
                raise ValueError("Busy interval end must be later than its start")

            clipped_start = max(start, interval_start)
            clipped_end = min(end, interval_end)
            if clipped_start < clipped_end:
                intervals.append((clipped_start, clipped_end))

    # All inputs have been validated before any successful return.
    intervals.sort()
    candidate = start

    for interval_start, interval_end in intervals:
        if interval_start - candidate >= duration_min:
            return f"{candidate // 60:02d}:{candidate % 60:02d}"
        candidate = max(candidate, interval_end)

    if end - candidate >= duration_min:
        return f"{candidate // 60:02d}:{candidate % 60:02d}"
    return None
```

