import re
from typing import Optional

def negotiate_language(header: str, available: list[str]) -> Optional[str]:
    # Parse the Accept-Language header into a list of (range, quality, original_index) tuples
    entries = []
    if not header.strip():
        return None

    # Split the header into individual entries, ignoring empty ones
    raw_entries = [e.strip() for e in header.split(',') if e.strip()]

    for idx, entry in enumerate(raw_entries):
        # Split into language range and parameters
        parts = [p.strip() for p in entry.split(';')]
        if not parts:
            continue

        lang_range = parts[0]
        quality = 1.0

        # Validate language range
        if lang_range != '*':
            if not re.fullmatch(r'^[a-zA-Z]{1,8}(-[a-zA-Z0-9]{1,8})*$', lang_range):
                raise ValueError(f"Invalid language range: {lang_range}")

        # Process parameters
        for param in parts[1:]:
            if '=' not in param:
                raise ValueError(f"Invalid parameter: {param}")
            key, value = param.split('=', 1)
            key = key.strip().lower()
            value = value.strip()
            if key != 'q':
                raise ValueError(f"Unsupported parameter: {key}")
            try:
                quality = float(value)
                if not (0 <= quality <= 1):
                    raise ValueError
                # Check for more than 3 decimal places
                if len(value.split('.')[1]) > 3 if '.' in value else False:
                    raise ValueError
            except ValueError:
                raise ValueError(f"Invalid q value: {value}")

        entries.append((lang_range.lower(), quality, idx))

    # For each available language, find the best matching entry
    best_tag = None
    best_quality = -1.0
    best_header_index = float('inf')
    best_available_index = float('inf')

    for avail_idx, tag in enumerate(available):
        tag_lower = tag.lower()
        current_quality = 0.0
        current_header_index = float('inf')

        for lang_range, quality, header_idx in entries:
            if quality == 0:
                continue
            if lang_range == '*':
                if quality > current_quality or (quality == current_quality and header_idx < current_header_index):
                    current_quality = quality
                    current_header_index = header_idx
            elif tag_lower == lang_range:
                if quality > current_quality or (quality == current_quality and header_idx < current_header_index):
                    current_quality = quality
                    current_header_index = header_idx
            elif tag_lower.startswith(lang_range + '-'):
                # Check if this is a more specific match than current
                if len(lang_range) > len(entries[current_header_index][0]) if current_header_index != float('inf') else True:
                    if quality > current_quality or (quality == current_quality and header_idx < current_header_index):
                        current_quality = quality
                        current_header_index = header_idx

        if current_quality > best_quality:
            best_quality = current_quality
            best_tag = tag
            best_header_index = current_header_index
            best_available_index = avail_idx
        elif current_quality == best_quality:
            if current_header_index < best_header_index:
                best_tag = tag
                best_header_index = current_header_index
                best_available_index = avail_idx
            elif current_header_index == best_header_index:
                if avail_idx < best_available_index:
                    best_tag = tag
                    best_available_index = avail_idx

    return best_tag if best_quality > 0 else None
```

