import re

def _natural_key(s: str) -> tuple:
    parts = re.findall(r'[0-9]+|[^0-9]+', s)
    runs = []
    for part in parts:
        if '0' <= part[0] <= '9':
            stripped = part.lstrip('0')
            if not stripped:
                stripped = '0'
            runs.append((0, len(stripped), stripped, len(part)))
        else:
            runs.append((1, part.lower()))
    return (tuple(runs), s)

def natural_sort(items: list[str]) -> list[str]:
    return sorted(items, key=_natural_key)
```

```python
def _parse_time(t: str) -> int:
    if not isinstance(t, str) or len(t) != 5 or t[2] != ":":
        raise ValueError(f"malformed time: {t!r}")
    if any(c not in "0123456789" for c in (t[0], t[1], t[3], t[4])):
        raise ValueError(f"malformed time: {t!r}")
    h = int(t[:2])
    m = int(t[3:])
    if h > 23 or m > 59:
        raise ValueError(f"malformed time: {t!r}")
    return h * 60 + m


def _fmt_time(minutes: int) -> str:
    return f"{minutes // 60:02d}:{minutes % 60:02d}"


def first_common_slot(
    busy: list[list[tuple[str, str]]],
    day_start: str,
    day_end: str,
    duration_min: int,
) -> str | None:
    start = _parse_time(day_start)
    end = _parse_time(day_end)

    if end <= start:
        raise ValueError("day_end must be after day_start")
    if not isinstance(duration_min, int) or duration_min < 1:
        raise ValueError("duration_min must be an integer >= 1")

    clipped = []

    for person in busy:
        for s_str, e_str in person:
            s = _parse_time(s_str)
            e = _parse_time(e_str)

            if e <= s:
                raise ValueError("busy interval end must be after start")

            if e <= start or s >= end:
                continue

            clipped.append((max(s, start), min(e, end)))

    clipped.sort()

    merged = []
    for s, e in clipped:
        if not merged or s > merged[-1][1]:
            merged.append([s, e])
        else:
            if e > merged[-1][1]:
                merged[-1][1] = e

    candidate = start

    for s, e in merged:
        if candidate + duration_min <= s:
            return _fmt_time(candidate)
        if e > candidate:
            candidate = e

    if candidate + duration_min <= end:
        return _fmt_time(candidate)

    return None
```

```python
from collections import OrderedDict, defaultdict

def lfu_cache(capacity: int, ops: list[tuple]) -> list:
    if capacity < 0:
        raise ValueError("capacity must be non-negative")

    values = {}
    freq = {}
    buckets = defaultdict(OrderedDict)
    min_freq = 0

    def touch(key):
        nonlocal min_freq
        f = freq[key]
        bucket = buckets[f]
        del bucket[key]
        if not bucket:
            del buckets[f]
            if min_freq == f:
                min_freq += 1
        new_f = f + 1
        freq[key] = new_f
        buckets[new_f][key] = None

    def insert(key, value):
        nonlocal min_freq
        values[key] = value
        freq[key] = 1
        buckets[1][key] = None
        min_freq = 1

    def evict():
        bucket = buckets[min_freq]
        evict_key, _ = bucket.popitem(last=False)
        if not bucket:
            del buckets[min_freq]
        del values[evict_key]
        del freq[evict_key]

    results = []
    for op in ops:
        if not isinstance(op, tuple):
            raise ValueError(f"invalid operation: {op!r}")

        if len(op) == 2 and op[0] == "get":
            key = op[1]
            if key in values:
                results.append(values[key])
                touch(key)
            else:
                results.append(None)

        elif len(op) == 3 and op[0] == "put":
            if capacity == 0:
                continue
            key, value = op[1], op[2]
            if key in values:
                values[key] = value
                touch(key)
            else:
                if len(values) >= capacity:
                    evict()
                insert(key, value)

        else:
            raise ValueError(f"invalid operation: {op!r}")

    return results
```
